184	    private resolveMainCacheFile(cachePath: string): string {
185	        const legacyPath = path.join(cachePath, 'main_file_cache.dat2');
186	        const rootIndexPath = path.join(cachePath, 'js5-index.jcache');
187	
188	        if (fs.existsSync(rootIndexPath)) return rootIndexPath;
189	        if (fs.existsSync(legacyPath)) return legacyPath;
190	
191	        const files = fs.readdirSync(cachePath).filter(f => f.endsWith('.jcache'));
192	        const bundles = files.map(f => ({ name: f, major: parseInt(f.match(/\d+/)?.[0] || '0', 10) }))
193	            .sort((a, b) => b.major - a.major);
194	        return bundles.length > 0 ? path.join(cachePath, bundles[0].name) : 'OFFLINE';
195	    }
