435	    /**
436	     * resolveWikiTitle - Maps a wiki-style name to a canonical game ID.
437	     * Checks Items and NPCs catalogs.
438	     *
439	     * @returns Result with primaryId and confidence score.
440	     */
441	    public async resolveWikiTitle(name: string): Promise<{ primaryId: number | null, confidence: 'exact' | 'fuzzy' | 'ambiguous' | 'none' }> {
442	        const term = name.toLowerCase();
443	
444	        // 1. Try exact match across items and NPCs
445	        const itemExact = this.queryTaxonomy({ layer: 'items', term, queryType: 'exact' });
446	        const npcExact = this.queryTaxonomy({ layer: 'npcs', term, queryType: 'exact' });
447	
448	        const exactItems = itemExact.ok ? itemExact.value : [];
449	        const exactNpcs = npcExact.ok ? npcExact.value : [];
450	
451	        if (exactItems.length === 1 && exactNpcs.length === 0) return { primaryId: exactItems[0].id, confidence: 'exact' };
452	        if (exactNpcs.length === 1 && exactItems.length === 0) return { primaryId: exactNpcs[0].id, confidence: 'exact' };
453	        if (exactItems.length + exactNpcs.length > 1) return { primaryId: null, confidence: 'ambiguous' };
454	
455	        // 2. Try partial match
456	        const itemPartial = this.queryTaxonomy({ layer: 'items', term, queryType: 'partial' });
457	        const npcPartial = this.queryTaxonomy({ layer: 'npcs', term, queryType: 'partial' });
458	
459	        const partialItems = itemPartial.ok ? itemPartial.value : [];
460	        const partialNpcs = npcPartial.ok ? npcPartial.value : [];
461	
462	        const totalMatches = partialItems.length + partialNpcs.length;
463	        if (totalMatches === 0) return { primaryId: null, confidence: 'none' };
464	        if (totalMatches > 1) return { primaryId: null, confidence: 'ambiguous' };
465	
466	        const match = partialItems[0] || partialNpcs[0];
467	        return { primaryId: match.id, confidence: 'fuzzy' };
468	    }
