491	    /**
492	     * queryTaxonomy - Search for a specific character, item, or object in the game database.
493	     */
494	    public queryTaxonomy(params: { layer: 'npcs' | 'items' | 'objects' | 'quests', term: string, queryType: 'exact' | 'partial' | 'regex' }): Result<any[]> {
495	        this.loadCatalogData(); // Ensure base catalogs are present
496	
497	        let data: any[] = [];
498	        switch (params.layer) {
499	            case 'npcs':
500	                if (!this.npcs) {
501	                    const npcPath = path.join(this.rootDir, 'npcs.json');
502	                    if (fs.existsSync(npcPath)) this.npcs = JSON.parse(fs.readFileSync(npcPath, 'utf8'));
503	                }
504	                data = this.npcs || [];
505	                break;
506	            case 'items':
507	                if (!this.items) {
508	                    const itemPath = path.join(this.rootDir, 'items.json');
509	                    if (fs.existsSync(itemPath)) this.items = JSON.parse(fs.readFileSync(itemPath, 'utf8'));
510	                }
511	                data = this.items || [];
512	                break;
513	            case 'objects':
514	                if (!this.objects) {
515	                    const objPath = path.join(this.rootDir, 'objects.json');
516	                    if (fs.existsSync(objPath)) this.objects = JSON.parse(fs.readFileSync(objPath, 'utf8'));
517	                }
518	                data = this.objects || [];
519	                break;
520	            case 'quests':
521	                data = this.quests?.quests || [];
522	                break;
523	        }
524	
525	        const term = params.term.toLowerCase();
526	        const results = data.filter(e => {
527	            const name = (e.name || '').toLowerCase();
528	            if (params.queryType === 'exact') return name === term;
529	            if (params.queryType === 'regex') return new RegExp(params.term, 'i').test(name);
530	            return name.includes(term);
531	        });
532	
533	        return ok(results);
534	    }
