540	        const npcRes = this.queryTaxonomy({ layer: 'npcs', term: name, queryType: 'exact' });
541	        if (!npcRes.ok || npcRes.value.length === 0) {
542	            const partialRes = this.queryTaxonomy({ layer: 'npcs', term: name, queryType: 'partial' });
543	            if (!partialRes.ok || partialRes.value.length === 0) {
544	                return err(new Error(`No NPC found matching "${name}"`));
545	            }
546	            return this.getCrossReferenceForNpc(partialRes.value[0]);
547	        }
548	        return this.getCrossReferenceForNpc(npcRes.value[0]);
549	    }
