551	    private getCrossReferenceForNpc(npc: NpcEntry): Result<any> {
552	        const models = npc.models || [];
553	        return ok({
554	            npcContext: {
555	                id: npc.id,
556	                name: npc.name
557	            },
558	            id: npc.id,
559	            rawModelIds: models
560	        });
561	    }
