565	     */
566	    public async crossReferenceItem(name: string): Promise<Result<any>> {
567	        const itemRes = this.queryTaxonomy({ layer: 'items', term: name, queryType: 'exact' });
568	        if (!itemRes.ok || itemRes.value.length === 0) {
569	            // Try partial if exact fails
570	            const partialRes = this.queryTaxonomy({ layer: 'items', term: name, queryType: 'partial' });
571	            if (!partialRes.ok || partialRes.value.length === 0) {
572	                return err(new Error(`No item found matching "${name}"`));
573	            }
574	            return this.getCrossReferenceForEntry(partialRes.value[0]);
575	        }
576	        return this.getCrossReferenceForEntry(itemRes.value[0]);
577	    }
