579	    private getCrossReferenceForEntry(item: ItemEntry): Result<any> {
580	        const maleModels = item.maleModels || [];
581	        const femaleModels = item.femaleModels || [];
582	        const allModels = Array.from(new Set([...maleModels, ...femaleModels]));
583	
584	        return ok({
585	            itemContext: {
586	                id: item.id,
587	                name: item.name
588	            },
589	            rawModelIds: allModels
590	        });
591	    }
