593	    /**
594	     * Search for an entity by name across all exported JSON catalogs.
595	     */
596	    public async search(query: string, type: 'npc' | 'item' | 'object' | 'all' = 'all'): Promise<Result<any[], Error>> {
597	        const results: any[] = [];
598	        if (type === 'npc' || type === 'all') {
599	            const res = this.queryTaxonomy({ layer: 'npcs', term: query, queryType: 'partial' });
600	            if (res.ok) results.push(...res.value.map(v => ({ ...v, type: 'npc' })));
601	        }
602	        if (type === 'item' || type === 'all') {
603	            const res = this.queryTaxonomy({ layer: 'items', term: query, queryType: 'partial' });
604	            if (res.ok) results.push(...res.value.map(v => ({ ...v, type: 'item' })));
605	        }
606	        if (type === 'object' || type === 'all') {
607	            const res = this.queryTaxonomy({ layer: 'objects', term: query, queryType: 'partial' });
608	            if (res.ok) results.push(...res.value.map(v => ({ ...v, type: 'object' })));
609	        }
610	        return ok(results);
611	    }
612	}

