69	export class CacheWatcherLimb {
70	    private static instance: CacheWatcherLimb;
71	    private watchers: FSWatcher[] = [];
72	    private betaCachePath: string | null;
73	    private liveCachePath: string | null;
74	    private baselines: Map<number, ScriptBaseline> = new Map();
75	    private baselinePath: string;
76	    private debounceTimer: ReturnType<typeof setTimeout> | null = null;
77	    private isProcessing = false;
78	    private fileHashes: Map<string, string> = new Map();
79	    private listeners: Map<number, Set<CacheInvalidationListener>> = new Map();
80	
81	    // Callback for external systems (HUD, sentinel) to subscribe to changes
82	    public onCacheChange?: (event: CacheChangeEvent) => void;
83	
84	    public registerListener(majorIndex: number, listener: CacheInvalidationListener): void {
85	        if (!this.listeners.has(majorIndex)) {
86	            this.listeners.set(majorIndex, new Set());
87	        }
88	        this.listeners.get(majorIndex)!.add(listener);
89	        logger.info({ majorIndex }, 'Registered new CacheInvalidationListener.');
90	    }
91	
92	    private constructor() {
93	        this.betaCachePath = getrsmvBetaCachePath();
94	        this.liveCachePath = getrsmvLiveCachePath();
95	        this.baselinePath = resolveSovereignPath('cache_pedagogy/script_baselines.json');
96	        this.loadBaselines();
97	    }
98	
99	    public static getInstance(): CacheWatcherLimb {
100	        if (!CacheWatcherLimb.instance) {
101	            CacheWatcherLimb.instance = new CacheWatcherLimb();
102	        }
103	        return CacheWatcherLimb.instance;
104	    }
105	
106	    /**
107	     * Start watching both live and beta cache directories for changes.
108	     * Uses fs.watch with 500ms debounce to coalesce rapid writes.
109	     */
110	    public startWatching(): boolean {
111	        const pathsToWatch: { path: string; name: string }[] = [];
112	        if (this.betaCachePath && existsSync(this.betaCachePath)) {
113	            pathsToWatch.push({ path: this.betaCachePath, name: 'Beta' });
114	        }
115	        if (this.liveCachePath && existsSync(this.liveCachePath)) {
116	            pathsToWatch.push({ path: this.liveCachePath, name: 'Live' });
117	        }
118	
119	        if (pathsToWatch.length === 0) {
120	            logger.warn('Neither Beta nor Live cache directories were found. Watcher not started.');
121	            return false;
122	        }
123	
124	        if (this.watchers.length > 0) {
125	            logger.info('Watchers already active. Skipping re-initialization.');
126	            return true;
127	        }
128	
129	        let startedAny = false;
130	        for (const item of pathsToWatch) {
131	            try {
132	                const watcher = watch(item.path, { recursive: false }, (eventType, filename) => {
133	                    if (!filename || !filename.endsWith('.jcache')) return;
134	
135	                    // Debounce: Jagex cache writes are multi-step; wait for quiescence
136	                    if (this.debounceTimer) clearTimeout(this.debounceTimer);
137	                    this.debounceTimer = setTimeout(() => {
138	                        this.handleCacheFileChange(filename, item.path);
139	                    }, 500);
140	                });
141	
142	                this.watchers.push(watcher);
143	                logger.info({ path: item.path, type: item.name }, `Cache watcher started on ${item.name} directory.`);
144	                startedAny = true;
145	            } catch (e) {
146	                logger.error({ err: e, path: item.path }, `Failed to start cache watcher on ${item.name} directory.`);
147	            }
148	        }
149	
150	        return startedAny;
151	    }
152	
153	    /**
154	     * Stop watching.
155	     */
156	    public stopWatching(): void {
157	        if (this.watchers.length > 0) {
158	            for (const watcher of this.watchers) {
159	                watcher.close();
160	            }
161	            this.watchers = [];
162	            logger.info('All cache watchers stopped.');
163	        }
164	    }
