166	    /**
167	     * Handle a cache file modification event.
168	     * Determines which major index changed and triggers targeted extraction.
169	     */
170	    private async handleCacheFileChange(filename: string, cachePath: string): Promise<void> {
171	        if (this.isProcessing) return;
172	        this.isProcessing = true;
173	
174	        try {
175	            const filePath = join(cachePath, filename);
176	            if (!existsSync(filePath)) {
177	                this.isProcessing = false;
178	                return;
179	            }
180	
181	            // 1. Hash the file (detect change vs. identical)
182	            let buf: Buffer;
183	            try {
184	                buf = readFileSync(filePath);
185	            } catch (e) {
186	                logger.warn({ filePath, err: e }, 'Could not read cache file, it might be locked. Retrying next time.');
187	                this.isProcessing = false;
188	                return;
189	            }
190	            const hash = this.simpleHash(buf);
191	            const prevHash = this.fileHashes.get(filename);
192	            
193	            if (prevHash === hash) {
194	                logger.debug({ filename }, 'Cache file content identical (spurious event). Skipping.');
195	                this.isProcessing = false;
196	                return;
197	            }
198	            this.fileHashes.set(filename, hash);
199	
200	            // Parse major index from filename (e.g., "js5-11.jcache" → 11)
201	            const match = filename.match(/js5-(\d+)\.jcache/);
202	            if (!match) {
203	                this.isProcessing = false;
204	                return;
205	            }
206	
207	            const majorIndex = parseInt(match[1], 10);
208	            const isLive = cachePath.toLowerCase().includes('runescape') && !cachePath.toLowerCase().includes('beta');
209	            logger.info({ filename, majorIndex, hash, isLive }, 'Cache file change validated and processing.');
210	
211	            const event: CacheChangeEvent = {
212	                filename,
213	                majorIndex,
214	                timestamp: Date.now(),
215	                deltaSummary: ''
216	            };
217	
218	            // Route based on major index
219	            switch (majorIndex) {
220	                case 11: // clientscript
221	                    event.deltaSummary = await this.extractPriorityScripts(cachePath);
222	                    break;
223	                case 3:  // interfaces
224	                    event.deltaSummary = `Interface archive updated. Priority interfaces: ${PRIORITY_INTERFACES.join(', ')}`;
225	                    break;
226	                case 45: // varbits
227	                    event.deltaSummary = 'Varbit archive updated. Morph control varbits may have changed.';
228	                    break;
229	                case 17: // enums (js5-17)
230	                case 40: // enums fallback
231	                    event.deltaSummary = await this.extractPriorityEnums(cachePath);
232	                    try {
233	                        const { generateAppearanceEnums } = await import('../../generators/CacheSchemaGenerator.js');
234	                        await generateAppearanceEnums(cachePath);
235	                        event.deltaSummary += ' [AppearanceEnums Regenerated]';
236	                    } catch (genError) {
237	                        logger.error({ err: genError }, 'Failed to auto-regenerate TypeScript appearance enums.');
238	                    }
239	                    break;
240	                case 2:  // dbrows (Archive 41 is within major 2)
241	                    event.deltaSummary = 'DBRow archive updated. Potential skill XP table changes.';
242	                    break;
243	                default:
244	                    event.deltaSummary = `Major ${majorIndex} updated (non-priority).`;
245	            }
246	
247	            logger.info({ event }, 'Cache change processed.');
248	
249	            // Notify subscribers
250	            if (this.onCacheChange) {
251	                this.onCacheChange(event);
252	            }
253	
254	            // Notify registered invalidation listeners
255	            const majorListeners = this.listeners.get(majorIndex);
256	            if (majorListeners) {
257	                for (const listener of majorListeners) {
258	                    try {
259	                        const res = listener.onCacheInvalidated(majorIndex, event.deltaSummary);
260	                        if (res instanceof Promise) {
261	                            await res;
262	                        }
263	                    } catch (listenerErr) {
264	                        logger.error({ err: listenerErr }, 'Error executing listener onCacheInvalidated callback.');
265	                    }
266	                }
267	            }
268	        } catch (e) {
269	            logger.error({ err: e }, 'Error processing cache change.');
270	        } finally {
271	            this.isProcessing = false;
272	        }
273	    }
