275	    /**
276	     * Extract priority scripts from the cache and compare against baselines.
277	     * Returns a delta summary string.
278	     */
279	    private async extractPriorityScripts(cachePath: string): Promise<string> {
280	        if (!cachePath) return 'No cache path.';
281	
282	        const deltas: string[] = [];
283	
284	        try {
285	            // Dynamic import to avoid hard dependency on rsmv at module load time
286	            // The rsmv substrate lives externally (D:\rsmv) — only available at runtime
287	            const { GameCacheLoader } = await import('rsmv/cache/sqlite.js');
288	            const { cacheMajors } = await import('rsmv/constants.js');
289	            const loader = new GameCacheLoader(cachePath);
290	
291	            for (const scriptId of PRIORITY_SCRIPTS) {
292	                try {
293	                    const buf = await loader.getFileById(cacheMajors.clientscript, scriptId);
294	                    const hash = this.simpleHash(buf);
295	                    const existing = this.baselines.get(scriptId);
296	
297	                    if (!existing) {
298	                        deltas.push(`NEW: Script ${scriptId} (${buf.length} bytes)`);
299	                        this.baselines.set(scriptId, { scriptId, length: buf.length, hash, lastSeen: Date.now() });
300	                    } else if (existing.hash !== hash) {
301	                        deltas.push(`CHANGED: Script ${scriptId} (${existing.length}→${buf.length} bytes)`);
302	                        this.baselines.set(scriptId, { scriptId, length: buf.length, hash, lastSeen: Date.now() });
303	                    }
304	                    // else: unchanged, no delta
305	                } catch {
306	                    // Script doesn't exist in this cache version
307	                    if (this.baselines.has(scriptId)) {
308	                        deltas.push(`REMOVED: Script ${scriptId} no longer exists`);
309	                        this.baselines.delete(scriptId);
310	                    }
311	                }
312	            }
313	
314	            this.saveBaselines();
315	        } catch (e) {
316	            logger.error({ err: e }, 'Failed to extract priority scripts.');
317	            return `Extraction failed: ${e}`;
318	        }
319	
320	        if (deltas.length === 0) return 'No script changes detected.';
321	
322	        // Special alert for 28556
323	        if (deltas.some(d => d.includes('28556'))) {
324	            logger.warn('⚠ SCRIPT 28556 STATUS CHANGE — Avatar model update trigger may have been modified or added!');
325	        }
326	
327	        return deltas.join('; ');
328	    }
