330	    /**
331	     * Autonomous raw extraction of Enums to bypass brittle opdecoder dependencies.
332	     * Uses better-sqlite3 directly to locate candidate enum archives.
333	     */
334	    private async extractPriorityEnums(cachePath: string): Promise<string> {
335	        if (!cachePath) return 'No cache path for enums.';
336	        const js5_17 = join(cachePath, 'js5-17.jcache');
337	        if (!existsSync(js5_17)) return 'js5-17.jcache not found.';
338	
339	        try {
340	            const db = new Database(js5_17, { readonly: true });
341	            
342	            // Check count of enums
343	            const countRow = db.prepare('SELECT COUNT(*) as count FROM cache').get() as any;
344	            const count = countRow?.count ?? 0;
345	
346	            const rows = db.prepare('SELECT key, LENGTH(data) as len FROM cache ORDER BY key').all() as any[];
347	            const archives = new Map<number, number[]>();
348	
349	            for (const row of rows) {
350	                const archive = (row.key >> 16) & 0xFFFF;
351	                const group = row.key & 0xFFFF;
352	                if (!archives.has(archive)) archives.set(archive, []);
353	                archives.get(archive)!.push(group);
354	            }
355	
356	            const candidates: number[] = [];
357	            archives.forEach((groups, archive) => {
358	                if (groups.length >= 20 && groups.length <= 40) {
359	                    candidates.push(archive);
360	                }
361	            });
362	
363	            let driftSummary = `Enum archive updated. Raw SQLite read: ${count} rows.`;
364	            
365	            // Perform Enum Drift Detection
366	            const isLive = cachePath.toLowerCase().includes('runescape') && !cachePath.toLowerCase().includes('beta');
367	            if (isLive) {
368	                logger.info('Performing Enum Drift Detection between Live and Beta cache...');
369	                const betaPath = getrsmvBetaCachePath();
370	                if (betaPath) {
371	                    const betaJs5 = join(betaPath, 'js5-17.jcache');
372	                    if (existsSync(betaJs5)) {
373	                        const betaDb = new Database(betaJs5, { readonly: true });
374	                        const betaCountRow = betaDb.prepare('SELECT COUNT(*) as count FROM cache').get() as any;
375	                        const betaCount = betaCountRow?.count ?? 0;
376	                        if (betaCount !== count) {
377	                            driftSummary += ` DELTA DETECTED: Live has ${count} enums, Beta has ${betaCount}.`;
378	                            logger.warn({ liveCount: count, betaCount }, '⚠ ENUM DRIFT DETECTED: Live and Beta caches have different enum counts!');
379	                        } else {
380	                            driftSummary += ' (No drift in enum count)';
381	                        }
382	                        betaDb.close();
383	                    }
384	                }
385	            }
386	
387	            if (candidates.length === 0) {
388	                return `${driftSummary} Need format validation.`;
389	            }
390	
391	            return `${driftSummary} Found ${candidates.length} candidate archives with 20-40 groups: ${candidates.join(', ')}`;
392	        } catch (e) {
393	            logger.error({ err: e }, 'Failed to extract priority enums using SQLite.');
394	            return `Enum extraction failed: ${e}`;
395	        }
396	    }
