398	    /**
399	     * Simple non-crypto hash for fast comparison (FNV-1a 32-bit).
400	     */
401	    private simpleHash(buf: Buffer): string {
402	        let hash = 0x811c9dc5;
403	        for (let i = 0; i < buf.length; i++) {
404	            hash ^= buf[i];
405	            hash = Math.imul(hash, 0x01000193);
406	        }
407	        return (hash >>> 0).toString(16).padStart(8, '0');
408	    }
