103	
104	        // --- PHASE 43.8: JSON-FIRST SOVEREIGNTY ---
105	        const jsonPath = getrsmvCachePath().replace(/\\/g, '/').replace('cache_pedagogy/rsmv', `atlas/spatial/world_extract/ms_${mapsquareX}_${mapsquareZ}.json`);
