107	        // Wait, let's just import resolveSovereignPath or use a safe derivation.
108	        try {
109	            if (fs.existsSync(jsonPath)) {
110	                const data = JSON.parse(fs.readFileSync(jsonPath, 'utf8'));
111	
112	                // Schema A: tileFlags array (SovereignWorldExtract output)
113	                if (data.tileFlags && Array.isArray(data.tileFlags)) {
114	                    for (const tile of data.tileFlags) {
115	                        if (tile && tile.plane < 4 && tile.x < 66 && tile.z < 66) {
116	                            // NXT flags: bit 1 (0x02) = blocking. NOT bit 0 (0x01 = visible).
117	                            grid[tile.plane][tile.x][tile.z] = (tile.collision & 0x02) !== 0 ? 1 : 0;
118	                        }
119	                    }
120	                }
121	
122	                // Schema B: collision_matrix keyed by "x_z" (public heatmap output)
123	                if (data.collision_matrix) {
124	                    for (const [key, val] of Object.entries(data.collision_matrix)) {
125	                        const cm = val as any;
126	                        if (cm && cm.sourceFlags !== undefined) {
127	                            const parts = key.split('_').map(Number);
128	                            const worldX = parts.length === 3 ? parts[1] : parts[0];
129	                            const worldZ = parts.length === 3 ? parts[2] : parts[1];
130	                            const tp = parts.length === 3 ? parts[0] : 0;
131	
132	                            // Map to Padded Coordinate [0..65]
133	                            const tx = worldX - (mapsquareX << 6) + 1;
134	                            const tz = worldZ - (mapsquareZ << 6) + 1;
