146	                    for (let curZ = 0; curZ < 66; curZ++) {
147	                        const worldX = (mapsquareX << 6) + curX - 1; // Center 0..63
148	                        const worldZ = (mapsquareZ << 6) + curZ - 1;
149	                        observations.push({
150	                            x: worldX,
151	                            z: worldZ,
152	                            plane: plane,
