204	    /**
205	     * senseLocations - Extracts game objects from Archive 5, Sub 0.
206	     */
207	    public async senseLocations(mapsquareX: number, mapsquareZ: number, plane: number): Promise<Result<GameObjectInstance[]>> {
208	        if (!this.cache) return err(new Error('Limb not initialized'));
209	        const cacheKey = `${mapsquareX}_${mapsquareZ}`;
210	        const fileId = (mapsquareX << 8) | mapsquareZ;
211	
212	        if (this.locationsCache.has(cacheKey)) {
213	            return ok(this.locationsCache.get(cacheKey)!.filter(l => l.plane === plane));
214	        }
215	
216	        const buffer = this.cache.readSubEntry(5, fileId, 0); // Sub 0 = Locations
217	        if (!buffer || buffer.length === 0) return ok([]);
218	
219	        const reader = new ByteReader(buffer);
220	        const instances: GameObjectInstance[] = [];
221	        let objectId = -1;
222	
223	        while (reader.hasRemaining()) {
224	            const idDelta = reader.readTailedVarUShort();
225	            if (idDelta === 0) break;
226	            objectId += idDelta;
227	
228	            let locationData = 0;
229	            while (reader.hasRemaining()) {
230	                const locationDelta = reader.readVarUShort();
231	                if (locationDelta === 0) break;
232	                locationData += locationDelta - 1;
233	
234	                const attributes = reader.readU8();
235	                const type = attributes >> 2;
236	                const rotation = attributes & 0x3;
237	                const hasExtra = attributes & 0x80;
238	
239	                const curPlane = (locationData >> 12) & 0x3;
240	                const localX = (locationData >> 6) & 0x3F;
241	                const localZ = locationData & 0x3F;
242	
243	                if (hasExtra) {
244	                    const flags = reader.readU8();
245	                    if (flags & 0x01) reader.skip(8); // Custom rotation (4 shorts)
246	                    if (flags & 0x02) reader.skip(2); // TranslateX
247	                    if (flags & 0x04) reader.skip(2); // TranslateY
248	                    if (flags & 0x08) reader.skip(2); // TranslateZ
249	                    if (flags & 0x10) reader.skip(2); // Scale (unsigned short)
250	                    if (flags & 0x20) reader.skip(2); // ScaleX
251	                    if (flags & 0x40) reader.skip(2); // ScaleY
252	                    if (flags & 0x80) reader.skip(2); // ScaleZ
253	                }
254	
255	                instances.push({
256	                    id: objectId,
257	                    type,
258	                    rotation,
259	                    worldX: (mapsquareX << 6) + localX,
260	                    worldZ: (mapsquareZ << 6) + localZ,
261	                    plane: curPlane
262	                });
263	            }
264	        }
265	
266	        this.locationsCache.set(cacheKey, instances);
267	        return ok(instances.filter(l => l.plane === plane));
268	    }
