298	            const b = bridgeRes.value;
299	            const def: ObjectDefinition = {
300	                id: b.id,
301	                name: b.name,
302	                type: 10,
303	                width: b.sizeX || 1,
304	                length: b.sizeZ || 1,
305	                blocksMovement: !b.probably_nocollision,
