321	    /**
322	     * buildDirectionalMask - Merges terrain and object data into a quaternary mask.
323	     */
324	    public async buildDirectionalMask(x: number, z: number, plane: number): Promise<Result<DirectionalCollision>> {
325	        const mx = x >> 6;
326	        const mz = z >> 6;
327	
328	        const observationsRes = await this.senseLocalArea(x, z, plane);
329	        if (!observationsRes.ok) return err(observationsRes.error || new Error('Unknown error'));
330	
331	        const obs = observationsRes.value.find(o => o.x === x && o.z === z);
332	        const mask: DirectionalCollision = {
333	            north: true, east: true, south: true, west: true,
334	            npc_only_blocks: []
335	        };
336	
337	        // Terrain blocking (obs.collision is a base-3 packed int, center is index 0)
338	        if (obs && (obs.collision % 3 !== 0)) {
339	            mask.north = mask.east = mask.south = mask.west = false;
340	            return ok(mask);
341	        }
342	
343	        // Object blocking
344	        const locsRes = await this.senseLocations(mx, mz, plane);
345	        if (locsRes.ok && locsRes.value) {
346	            const tileObjects = locsRes.value.filter(l => l.worldX === x && l.worldZ === z);
347	            for (const obj of tileObjects) {
348	                const def = await this.getObjectDefinition(obj.id);
349	                if (!def.blocksMovement) continue;
350	
351	                const blocked = getBlockedDirections(obj.type, obj.rotation, def.width);
352	                for (const dir of blocked) {
353	                    (mask as any)[dir] = false;
354	                }
355	            }
356	        }
357	
358	        return ok(mask);
359	    }
