234	    public async getInterface(id: number): Promise<Result<InterfaceForensics>> {
235	        if (!this.cache) return err(new Error('Cache substrate not connected.'));
236	        if (!parse) return err(new Error('HUDForensicsLimb: parse not available.'));
237	
238	        try {
239	            const archive = await this.cache.getArchiveById(3, id);
240	            const components: InterfaceComponent[] = [];
241	            const textLabels: string[] = [];
242	            const parentToIndex = new Map<number, number[]>();
243	            const parseErrors: string[] = [];
244	
245	            for (const sub of archive) {
246	                const state: any = {
247	                    isWrite: false,
248	                    buffer: sub.buffer,
249	                    stack: [],
250	                    hiddenstack: [],
251	                    scan: 0,
252	                    endoffset: sub.buffer.byteLength,
253	                    args: {
254	                        ...this.cache.getDecodeArgs(),
255	                        clientVersion: BetaConfig.BUILD_ID
256	                    }
257	                };
258	
259	                try {
260	                    const comp = parse.interfaces.parser.read(state);
261	                    const compId = (id << 16) | sub.fileid;
262	
263	                    if (sub.fileid === 0) {
264	                        logger.info({ id, version: comp.version, type: comp.type, firstByte: sub.buffer[0] }, 'First component forensic header.');
265	                    }
266	
267	                    const component: InterfaceComponent = {
268	                        componentId: sub.fileid,
269	                        type: comp.type !== undefined ? this.mapTypeIdToName(comp.type) : 'UNKNOWN',
270	                        typeId: comp.type ?? -1,
271	                        text: comp.textdata?.text || comp.text,
272	                        spriteId: comp.spritedata?.spriteid || comp.spriteid,
273	                        modelId: comp.modeldata?.modelid || comp.modelid,
274	                        hidden: !!comp.hidden,
275	                        parentId: comp.parentid !== undefined ? comp.parentid : -1,
276	                        children: [],
277	
278	                        // Layout geometry
279	                        baseposx: comp.baseposx ?? 0,
280	                        baseposy: comp.baseposy ?? 0,
281	                        basewidth: comp.basewidth ?? 0,
282	                        baseheight: comp.baseheight ?? 0,
283	                        aspectxtype: comp.aspectxtype ?? 0,
284	                        aspectytype: comp.aspectytype ?? 0,
285	                        aspectwidthtype: comp.aspectwidthtype ?? 0,
286	                        aspectheighttype: comp.aspectheighttype ?? 0,
287	
288	                        // Behavior
289	                        optmask: comp.optmask ?? 0,
290	                        cursor: comp.cursor ?? 65535,
291	                        scripts: comp.scripts ?? undefined,
292	
293	                        // Interaction
294	                        menucounts: comp.menucounts ?? 0,
295	                        rightclickopts: comp.rightclickopts ?? [],
296	                        rightclickcursors: comp.rightclickcursors ?? [],
297	
298	                        // Content data blocks
299	                        containerdata: comp.containerdata ?? undefined,
300	                        textdata: comp.textdata ?? undefined,
301	                        spritedata: comp.spritedata ?? undefined,
302	                        modeldata: comp.modeldata ?? undefined,
303	                        figuredata: comp.figuredata ?? undefined,
304	                        linedata: comp.linedata ?? undefined,
305	                    };
306	
307	                    if (component.text) textLabels.push(component.text);
308	                    components.push(component);
309	
310	                    if (component.parentId !== -1 && component.parentId !== 65535) {
311	                        const children = parentToIndex.get(component.parentId) || [];
312	                        children.push(sub.fileid);
313	                        parentToIndex.set(component.parentId, children);
314	                    }
315	                } catch (err: any) {
316	                    const dumpStart = Math.max(0, state.scan - 20);
317	                    const dumpEnd = Math.min(sub.buffer.byteLength, state.scan + 20);
318	                    const hexDump = sub.buffer.subarray(dumpStart, dumpEnd).toString('hex');
319	                    const pointer = ' '.repeat((state.scan - dumpStart) * 2) + '^^';
320	
321	                    logger.error({
322	                        id,
323	                        subfile: sub.fileid,
324	                        scan: state.scan,
325	                        hexAround: hexDump,
326	                        pointerAtHex: pointer,
327	                        error: err.message
328	                    }, 'Forensic decompile failure for subfile.');
329	                    parseErrors.push(`Subfile ${sub.fileid} failed at offset ${state.scan}: ${err.message}`);
330	                    continue;
331	                }
332	            }
333	
334	            for (const comp of components) {
335	                comp.children = parentToIndex.get(comp.componentId) || [];
336	            }
337	
338	            // Legacy flat check (kept for backward compat)
339	            const isHudCandidate = textLabels.some(t =>
340	                /inventory|skill|chat|map|quest|ability|friend|clan/i.test(t)
341	            );
342	
343	            // NEW: Structural classification
344	            const classification = this.classifyInterface(id, components, textLabels);
345	
346	            let wikiContext: WikiData | undefined;
347	            if (classification.confidence === "HIGH" && textLabels.length > 0) {
348	                const query = textLabels.sort((a, b) => b.length - a.length)[0];
349	                const wikiRes = await WikiEnricher.enrich(query);
350	                if (wikiRes.ok) wikiContext = wikiRes.value;
351	            }
352	
353	            const typeDistribution: Record<string, number> = {};
354	            for (const comp of components) {
355	                typeDistribution[comp.type] = (typeDistribution[comp.type] || 0) + 1;
356	            }
357	
358	            return ok({
359	                interfaceId: id,
360	                components,
361	                textLabels,
362	                isHudCandidate,
363	                wikiContext,
364	                classification,
365	                totalComponents: components.length,
366	                parseErrors,
367	                typeDistribution
368	            });
369	        } catch (error) {
370	            logger.error({ interfaceId: id, error }, 'Failed to decompile interface.');
371	            return err(error as Error);
372	        }
