412	    /**
413	     * classifyInterface - Structural + Lexical epistemology.
414	     * Eliminates tutorial false positives by verifying topology, not just text.
415	     */
416	    public classifyInterface(
417	        interfaceId: number,
418	        components: InterfaceComponent[],
419	        textLabels: string[]
420	    ): HUDClassification {
421	        const totalComponents = components.length;
422	        const textComponents = components.filter(c => c.type === "TEXT").length;
423	        const spriteComponents = components.filter(c => c.type === "SPRITE").length;
424	        const containerComponents = components.filter(c => c.type === "CONTAINER").length;
425	
426	        const allText = textLabels.join(" ").toLowerCase();
427	        const textRatio = totalComponents > 0 ? textComponents / totalComponents : 0;
428	        const spriteRatio = totalComponents > 0 ? spriteComponents / totalComponents : 0;
429	        const containerRatio = totalComponents > 0 ? containerComponents / totalComponents : 0;
430	        const maxDepth = this.computeMaxDepth(components);
431	        const avgTextLength = textLabels.length > 0
432	            ? textLabels.reduce((a, b) => a + b.length, 0) / textLabels.length
433	            : 0;
434	
435	        // ─── Minimum Component Thresholds ───
436	        // Bare stub containers (1-4 components, zero text, zero sprite) are scaffolding,
437	        // not real HUDs. Force LOW confidence to avoid RIBBON over-population.
438	        const MIN_COMPONENTS: Record<string, number> = {
439	            RIBBON: 10,          // Real ribbon has tab icons, buttons, containers
440	            SPRITE_OVERLAY: 1,   // Single sprite is valid
441	            SETTINGS_PANEL: 5,
442	            INVENTORY_HUD: 8,
443	            CHAT_BOX: 4,
444	            MINIMAP: 3,
445	        };
446	
447	        // ─── Anti-Pattern Penalty ───
448	        let tutorialPenalty = 0;
449	        const tutorialHits = this.TUTORIAL_MARKERS.filter(re => re.test(allText)).length;
450	        if (tutorialHits >= 2) tutorialPenalty += 40;
451	        if (avgTextLength > 80) tutorialPenalty += 20;
452	        if (textComponents > 50) tutorialPenalty += 15;
453	        if (allText.includes("world event") || allText.includes("battle of")) tutorialPenalty += 25;
454	
455	        // ─── Category Scoring ───
456	        const scores: Record<string, number> = {};
457	        const reasons: string[] = [];
458	
459	        for (const [category, profile] of Object.entries(this.HUD_STRUCTURAL_PROFILES)) {
460	            let score = 50;
461	
462	            const lexMatches = (allText.match(profile.lexicalTriggers) || []).length;
463	            score += lexMatches * 10;
464	
465	            if (textRatio <= profile.maxTextRatio) score += 15;
466	            else score -= 20;
467	
468	            if (spriteRatio >= profile.minSpriteRatio) score += 10;
469	            if (maxDepth >= profile.minContainerDepth) score += 10;
470	
471	            // Minimum component gate — stub frames below threshold get penalized
472	            const minComps = MIN_COMPONENTS[category] ?? 1;
473	            if (totalComponents < minComps) score -= 30;
474	
475	            score -= tutorialPenalty;
476	            scores[category] = Math.max(0, score);
477	        }
478	
479	        const sorted = Object.entries(scores).sort((a, b) => b[1] - a[1]);
480	        const [topCategory, topScore] = sorted[0];
481	        const runnerUpScore = sorted[1]?.[1] || 0;
482	
483	        let confidence: HUDClassification["confidence"];
484	        if (tutorialPenalty > 50) {
485	            confidence = "FALSE_POSITIVE";
486	            reasons.push(`TUTORIAL_PENALTY: ${tutorialPenalty} — likely welcome/marketing screen`);
487	        } else if (topScore - runnerUpScore > 20 && topScore > 60) {
488	            confidence = "HIGH";
489	        } else if (topScore > 40) {
490	            confidence = "MEDIUM";
491	        } else {
492	            confidence = "LOW";
493	        }
494	
495	        reasons.push(
496	            `textRatio: ${(textRatio * 100).toFixed(1)}% (max: ${(this.HUD_STRUCTURAL_PROFILES[topCategory as keyof typeof this.HUD_STRUCTURAL_PROFILES]?.maxTextRatio || 0) * 100}%)`,
497	            `spriteRatio: ${(spriteRatio * 100).toFixed(1)}%`,
498	            `containerRatio: ${(containerRatio * 100).toFixed(1)}%`,
499	            `maxDepth: ${maxDepth}`,
500	            `avgTextLength: ${avgTextLength.toFixed(0)} chars`,
501	            `textComponents: ${textComponents}`,
