526	    public async searchInterfaces(query: string, limit: number = 10): Promise<Result<InterfaceForensics[]>> {
527	        if (!this.cache) return err(new Error('Cache substrate not connected.'));
528	
529	        const results: InterfaceForensics[] = [];
530	        const regex = new RegExp(query, 'i');
531	
532	        for (let id = 0; id < 2000; id++) {
533	            try {
534	                const res = await this.getInterface(id);
535	                if (res.ok) {
536	                    const forensics = res.value;
537	                    const hasLexicalHit = forensics.textLabels.some(t => regex.test(t));
538	
539	                    // NEW: Only promote to results if lexical hit AND not false positive
540	                    if (hasLexicalHit && forensics.classification?.confidence !== "FALSE_POSITIVE") {
541	                        results.push(forensics);
542	                        if (results.length >= limit) break;
543	                    }
544	                }
545	            } catch {
546	                continue;
547	            }
548	        }
549	
