613	    /**
614	     * Compute maximum nesting depth of component hierarchy.
615	     */
616	    private computeMaxDepth(components: InterfaceComponent[]): number {
617	        const idMap = new Map<number, InterfaceComponent>();
618	        components.forEach(c => { if (c.componentId !== undefined) idMap.set(c.componentId, c); });
619	
620	        function getDepth(id: number, visited = new Set<number>()): number {
621	            if (visited.has(id)) return 0;
622	            visited.add(id);
623	            const comp = idMap.get(id);
624	            if (!comp || comp.parentId === -1 || comp.parentId === 65535) return 1;
625	            return 1 + getDepth(comp.parentId, visited);
626	        }
627	
628	        let max = 0;
629	        components.forEach(c => {
630	            if (c.componentId !== undefined) {
631	                max = Math.max(max, getDepth(c.componentId));
632	            }
633	        });
634	        return max;
635	    }
