647	    /**
648	     * extractAllInterfaces - Bulk extract and decompose all Major 3 interfaces to disk.
649	     * Writes interface_<id>_decomposed.json for every interface with >0 components.
650	     * Skips IDs where the file already exists unless force=true.
651	     */
652	    public async extractAllInterfaces(options: {
653	        range?: [number, number];
654	        outputDir?: string;
655	        force?: boolean;
656	        onProgress?: (current: number, total: number, found: number, errors: number) => void;
657	    } = {}): Promise<{ extracted: number; skipped: number; errors: number; errorIds: number[] }> {
658	        if (!this.cache) throw new Error('Cache substrate not connected.');
659	        if (!parse) throw new Error('HUDForensicsLimb: parse not available.');
660	
661	        const [start, end] = options.range ?? [0, 2000];
662	        const outputDir = options.outputDir ?? this.pedagogyCandidateDir;
663	        const force = options.force ?? false;
664	        const total = end - start + 1;
665	
666	        await fs.promises.mkdir(outputDir, { recursive: true });
667	
668	        let extracted = 0;
669	        let skipped = 0;
670	        let errors = 0;
671	        const errorIds: number[] = [];
672	
673	        for (let id = start; id <= end; id++) {
674	            const outPath = path.join(outputDir, `interface_${id}_decomposed.json`);
675	
676	            // Skip if already exists and not forcing
677	            if (!force && fs.existsSync(outPath)) {
678	                skipped++;
679	                options.onProgress?.(id - start + 1, total, extracted, errors);
680	                continue;
681	            }
682	
683	            const res = await this.getInterface(id);
684	
685	            if (res.ok && res.value.components.length > 0) {
686	                // Compute type distribution for the manifest
687	                const comps = res.value.components;
688	                const typeDistribution: Record<string, number> = {};
689	                for (const c of comps) {
690	                    typeDistribution[c.type] = (typeDistribution[c.type] || 0) + 1;
691	                }
692	
693	                const manifest = {
694	                    interfaceId: res.value.interfaceId,
695	                    totalComponents: comps.length,
696	                    parsedComponents: comps.length,
697	                    parseErrors: 0,
698	                    spriteReferences: [...new Set(comps.map(c => c.spriteId).filter(Boolean))],
699	                    modelReferences: [...new Set(comps.map(c => c.modelId).filter(Boolean))],
700	                    textLabels: res.value.textLabels,
701	                    typeDistribution,
702	                    classification: res.value.classification,
703	                    components: comps,
704	                    extractedAt: new Date().toISOString(),
705	                };
706	
707	                await fs.promises.writeFile(outPath, JSON.stringify(manifest, null, 2));
708	                extracted++;
709	                logger.info({ id, components: comps.length }, 'Interface extracted.');
710	            } else if (!res.ok) {
711	                errors++;
712	                errorIds.push(id);
713	            }
714	            // Empty interfaces (0 components) are valid skips — not errors
715	
716	            options.onProgress?.(id - start + 1, total, extracted, errors);
717	        }
718	
719	        return { extracted, skipped, errors, errorIds };
720	    }
721	}
