485	    private processCombatTick() {
486	        const combatants: NPC[] = [this.avatar, ...Array.from(this.globalState.npcMap.values())];
487	
488	        for (const actor of combatants) {
489	            if (!actor.intent) continue;
490	
491	            if (actor.intent.action === 'castAbility' || actor.intent.action === 'COMBAT_ABILITY' || actor.intent.action === 'execute_ability' || actor.intent.action === 'attack') {
492	                this.resolveCombatIntent(actor);
493	            }
494	        }
495	    }
