497	    private resolveCombatIntent(actor: NPC) {
498	        const intent = actor.intent as any;
499	        const targetId = intent.targetId;
500	
501	        // Resolve target
502	        let target: NPC | undefined;
503	        if (targetId === 'player') {
504	            target = this.avatar;
505	        } else if (typeof targetId === 'string' && targetId.startsWith('npc_')) {
506	            const id = parseInt(targetId.split('_')[1]);
507	            target = this.globalState.npcMap.get(id);
508	        } else if (typeof targetId === 'number') {
509	            target = this.globalState.npcMap.get(targetId);
510	        }
511	
512	        if (!target) return;
513	
514	        const abilityId = intent.abilityId || '1'; // Default to Basic Attack if undefined
515	        const check = this.combat.canCast(actor, target, abilityId, this.tickCount);
516	
517	        if (check.success) {
518	            // FIRE!
519	            this.combat.execute(actor, target, abilityId, this.tickCount);
520	            
521	            // Set interaction state
522	            actor.interactionState = 'EXECUTING';
523	
524	            // If it's the avatar, clear intent after non-auto ability? 
525	            // For now, keep simple auto-attack loop logic.
526	        } else if (check.reason?.includes('Out of range') || check.inRange === false) {
527	            // OUT OF RANGE: Actor enters MOVING state towards target
528	            actor.interactionState = 'MOVING';
529	            // Authoritative target update
530	            actor.target = { x: target.x, y: target.y, plane: target.plane };
531	        }
532	    }
