583	    public handleInteraction(targetId: string, actionId: number) {
584	        logger.info(`INTERACTION: ${targetId} with Action ${actionId}`);
585	        
586	        // 1. Grave Recovery Logic
587	        if (targetId.startsWith('grave_') || actionId === 1) {
588	            const graveKey = `${this.avatar.x},${this.avatar.y},${this.avatar.plane}`;
589	            const grave = this.globalState.graves!.get(graveKey);
590	            
591	            if (grave && grave.owner === this.avatar.username) {
592	                logger.info(`RECOVERING GRAVE: Restoring ${grave.items.length} items.`);
