598	                         this.globalState.npcMap.delete(id);
599	                     }
600	                }
601	                return;
602	            }
603	        }
604	
605	        // 2. Ground Item Logic (Action 1: Pick Up)
606	        if (actionId === 1 && targetId.startsWith('ground_')) {
607	            const key = `${this.avatar.x},${this.avatar.y},${this.avatar.plane}`;
608	            const items = this.globalState.groundItems!.get(key);
609	            if (items && items.length > 0) {
