611	                if (this.avatar.addItem(item)) {
612	                    logger.info(`PICK UP: ${item.id} added to inventory.`);
613	                } else {
614	                    items.unshift(item); // Put it back
615	                    logger.warn('PICK UP FAILED: Inventory full.');
616	                }
617	                return;
618	            }
619	        }
620	
621	        // 3. Bank Logic (Action 184: Bank)
