623	             this.avatar.metadata = {
624	                 ...this.avatar.metadata,
625	                 activeInterface: 762,
626	                 bankOpen: true
627	             };
628	             logger.info('NIS Bank Interface (ID 762) requested.');
629	        }
630	
631	        // 4. Bank Shortcuts (Cache Derived)
