196	     * Implements "Composite Bitwise Ingestion Merge" (Phase 41).
197	     */
198	    public async loadMapsquare(x: number, z: number): Promise<Result<void>> {
199	        const key = `${x}_${z}`;
200	        if (this.loadedMapsquares.has(key)) return ok(undefined);
201	
202	        // Phase 41: Eager marking to prevent redundant loads or false-negatives
203	        this.loadedMapsquares.set(key, { flags: new Uint16Array(0), heights: new Int16Array(0) });
204	
205	        const sourceDir = this.getSourceDir();
206	        let fullPath = path.join(sourceDir, 'world_extract', `ms_${x}_${z}.json`);
207	        if (!fs.existsSync(fullPath)) {
208	            // Try flat in sourceDir
209	            const flatPath = path.join(sourceDir, `ms_${x}_${z}.json`);
210	            if (fs.existsSync(flatPath)) {
211	                fullPath = flatPath;
212	            }
213	        }
214	
215	        if (!fs.existsSync(fullPath)) {
216	            // FALLBACK: Dynamically query rsmvBridge for mapsquare tiles from local cache!
217	            logger.info({ x, z }, 'Static Mapsquare fragment missing on disk. Querying NXT Live Cache via RSMVBridge...');
218	            try {
219	                const res = await rsmvBridge.getMapsquareTiles(x, z);
220	                if (!res.ok) {
221	                    return err(new Error(`Failed to load mapsquare [${x}, ${z}] dynamically: ${res.error.message}`));
222	                }
223	
224	                const data = res.value;
225	                if (data.tiles) {
226	                    const flags = new Uint16Array(4 * TILES_PER_LEVEL);
227	                    const heights = new Int16Array(4 * TILES_PER_LEVEL);
228	                    for (const tile of data.tiles) {
229	                        const tx = tile.x;
230	                        const tz = tile.z;
231	                        const plane = tile.plane;
232	                        if (tx < 0 || tx > 65 || tz < 0 || tz > 65 || plane < 0 || plane > 3) continue;
233	
234	                        const index = (plane * TILES_PER_LEVEL) + (tx * PADDED_SIZE) + tz;
235	                        flags[index] |= (tile.collision || 0);
236	                        if (tile.height !== null && tile.height !== undefined) {
237	                            heights[index] = Math.max(heights[index], tile.height);
238	                        }
239	                    }
240	                    this.loadedMapsquares.set(key, { flags, heights });
241	                    logger.info({ x, z, count: data.tiles.length }, 'Successfully ingested Mapsquare from NXT Live Cache dynamically.');
242	                    return ok(undefined);
243	                } else {
244	                    return err(new Error(`No tile definitions returned for mapsquare [${x}, ${z}]`));
245	                }
246	            } catch (fallbackError) {
247	                return err(fallbackError as Error);
248	            }
249	        }
250	
251	        try {
252	            const data = JSON.parse(fs.readFileSync(fullPath, 'utf8'));
253	
254	            // Phase 41 Hybrid Ingestion: Load BOTH semantic matrices and padded binary buffers
255	            if (data.collision_matrix) {
256	                const syntheticArtifact: SpatialLogicArtifact = {
257	                    city: `ms_${x}_${z}`,
258	                    metadata: data.metadata || {},
259	                    anchors: {},
260	                    meta: {
261	                        bounds: {
262	                            wx_min: x * 64,
263	                            wx_max: (x * 64) + 63,
264	                            wy_min: z * 64,
265	                            wy_max: (z * 64) + 63
266	                        }
267	                    },
268	                    collision_matrix: data.collision_matrix
269	                };
270	                this.loadedMatrices.set(syntheticArtifact.city, syntheticArtifact);
271	                logger.info({ x, z }, 'Ingested Semantic Phase B3 Mapsquare Fragment.');
272	            }
273	
274	            if (data.tiles) {
275	                // NXT 66×66 Padded Ingestion
276	                const flags = new Uint16Array(4 * TILES_PER_LEVEL);
277	                const heights = new Int16Array(4 * TILES_PER_LEVEL);
278	                for (const tile of data.tiles) {
279	                    const tx = tile.x;
280	                    const tz = tile.z;
281	                    const plane = tile.plane;
282	                    if (tx < 0 || tx > 65 || tz < 0 || tz > 65 || plane < 0 || plane > 3) continue;
283	
284	                    const index = (plane * TILES_PER_LEVEL) + (tx * PADDED_SIZE) + tz;
285	                    flags[index] |= (tile.collision || 0);
286	                    if (tile.height !== null && tile.height !== undefined) {
287	                        heights[index] = Math.max(heights[index], tile.height);
288	                    }
289	                }
290	                this.loadedMapsquares.set(key, { flags, heights });
291	            }
292	
293	            // Hydrate vertical plane transitions from extracted objects
294	            if (data.objects && Array.isArray(data.objects)) {
295	                PlaneTransitionRegistry.getInstance().hydrateFromObjects(data.objects);
296	            }
297	
298	            // Also attempt to load unified grounding (NPCs) if available
299	            await this.loadUnifiedGrounding(x, z);
300	
301	            return ok(undefined);
302	        } catch (error) {
303	            return err(error as Error);
304	        }
