341	    /**
342	     * resolveSurfaceStack - Volumetric Resolution of a coordinate.
343	     * Maps NXT cache fragments to a single authoritative surface per plane.
344	     * Implements "Safe Hybrid Z" (Phase 41 logic - Option C).
345	     */
346	    public resolveSurfaceStack(x: number, y: number): SurfaceStack {
347	        const msX = x >> 6;
348	        const msZ = y >> 6;
349	        const msKey = `${msX}_${msZ}`;
350	        const ms = this.loadedMapsquares.get(msKey);
351	
352	        const stack: SurfaceStack = {
353	            layers: [],
354	            highestWalkableZ: 0
355	        };
356	
357	        if (!ms) {
358	            // If mapsquare loaded as matrix but no heightmap exists, default to flat Plane 0
359	            stack.layers.push({ type: 'terrain', z: 0, walkable: true, blocks: false, plane: 0 });
360	            return stack;
361	        }
362	
363	        // +1 offset: local 0-63 coords map to padded indices 1-64
364	        const tx = (x & 0x3F) + PADDING_OFFSET;
365	        const tz = (y & 0x3F) + PADDING_OFFSET;
366	
367	        // NXT Pattern: 4 authoritative planes (0-3) across a 66×66 padded stride
368	        for (let plane = 0; plane < 4; plane++) {
369	            const index = (plane * TILES_PER_LEVEL) + (tx * PADDED_SIZE) + tz;
370	            const flag = ms.flags[index];
371	            const terrainHeight = ms.heights[index];
372	            
373	            // Absolute Priority Resolver (Overlay > Water > Terrain)
374	            const isOverlay = (flag & FLAG_OVERLAY) !== 0;  // 0x2
375	            const isWater   = (flag & FLAG_WATER) !== 0;    // 0x80
376	            const isBlocked = (flag & FLAG_BLOCKED) !== 0;  // 0x1 (Standard Blocking Bit)
377	
378	            // --- Phase 41: Safe Hybrid Z (Option C) ---
379	            // deterministic overlay height sourcing
380	            const baseZ = terrainHeight * 32;
381	            let z = baseZ;
382	
383	            let type: 'terrain' | 'water' | 'bridge' = 'terrain';
384	            let walkable = !isBlocked;
385	
386	            // Priority Logic (The Absolute Truth)
387	            if (isOverlay) {
388	                type = 'bridge';
389	                walkable = true; // Overlay ALWAYS replaces base collision
390	                // Bridge Z is authoritative from the cache heightmap
391	                z = baseZ; 
392	            } else if (isWater) {
393	                type = 'water';
394	                walkable = false; 
395	                // Option C Epsilon: max(terrainZ, waterZ + 0.1)
396	                z = baseZ + 0.1;
397	            } else {
398	                // Standard Terrain
399	                z = baseZ;
400	            }
401	
402	            stack.layers.push({
403	                type,
404	                z,
405	                walkable,
406	                blocks: !walkable,
407	                plane
408	            });
409	
410	            if (walkable && z > stack.highestWalkableZ) {
411	                stack.highestWalkableZ = z;
412	            }
413	        }
414	
415	        return stack;
416	    }
