419	    /**
420	     * isWalkable - Unified Navigation Arbiter (Phase 41)
421	     * Checks authority layers in order:
422	     * 1. GAL (Geometry Annotation Layer - Human Override)
423	     * 2. Matrix (Sovereign Logic Artifacts)
424	     * 3. Surface Stack (Volumetric Cache Substrate)
425	     */
426	    public isWalkable(plane: number, x: number, y: number, direction?: Direction | string): boolean {
427	        // --- LAYER 0: Geometry Annotation Layer (Sovereign Instruction) ---
428	        const galResult = this.gal.isNavigable(x, y, plane);
429	        if (galResult !== null) return galResult;
430	
431	        // --- LAYER 0.5: Vertical Transition Exemption ---
432	        // Tiles with registered transitions (ladders, stairs) are walkable for approach/entry
433	        if (PlaneTransitionRegistry.getInstance().hasLink({ x, y, plane })) {
434	            return true;
435	        }
436	
437	        // --- LAYER 1: Logic Matrix (Decoded Artifacts) ---
438	        const matrix = this.findMatrixForCoords(x, y);
439	        if (matrix) {
440	            const key = `${plane}_${x}_${y}`;
441	            const altKey = `${x}_${y}`; // Plane-agnostic fallback (Ground Level)
442	            const collision = matrix.collision_matrix[key] || matrix.collision_matrix[altKey];
443	
444	            if (collision !== undefined) {
445	                // Legacy bitmask matrix
446	                if (typeof collision === 'number') return (collision & 0x1) === 0;
447	                
448	                // Semantic Matrix Object (Phase B3)
449	                if (typeof collision === 'object') {
450	                    const c = collision as any;
451	                    
452	                    // 1. Check Directional Edge blocking BEFORE tile occupancy
453	                    if (direction && (c.edges || c.north !== undefined)) {
454	                        const edges = c.edges || c; // Support both {edges:{northBlocked}} and {north:true} formats
455	                        const dir = typeof direction === 'string' ? direction.toLowerCase() : direction;
456	                        
457	                        const northBlocked = edges.northBlocked ?? (edges.north === false);
458	                        const southBlocked = edges.southBlocked ?? (edges.south === false);
459	                        const eastBlocked = edges.eastBlocked ?? (edges.east === false);
460	                        const westBlocked = edges.westBlocked ?? (edges.west === false);
461	
462	                        if (northBlocked && dir === 'north') return false;
463	                        if (southBlocked && dir === 'south') return false;
464	                        if (eastBlocked && dir === 'east') return false;
465	                        if (westBlocked && dir === 'west') return false;
466	                    }
467	
468	                    // 2. Check general structural tile occupancy
469	                    if (c.walkable !== undefined) return c.walkable;
470	                    
471	                    // Fallback for logic artifacts (Barrows) that use direction only
472	                    return c.north !== undefined || c.edges !== undefined;
473	                }
474	            }
475	
476	            // Fallback: If we have a matrix for this region but this specific tile is missing,
477	            // default to walkable (unless it's a known void or perimeter).
478	            return true;
479	        }
480	
481	        // --- LAYER 2: Surface Stack (Absolute Deterministic Resolution) ---
482	        const surfaces = this.resolveSurfaceStack(x, y);
483	        const planeSurface = surfaces.layers.find(l => l.plane === plane);
484	        
485	        return planeSurface ? planeSurface.walkable : false;
486	    }
