488	    /**
489	     * resolveEntitySurface - Plane-Constrained Z-Resolution.
490	     * Primary rule: Plane selects the layer -> Z resolves within that layer.
491	     */
492	    public resolveEntitySurface(x: number, y: number, plane: number): number {
493	        const stack = this.resolveSurfaceStack(x, y);
494	        const planeLayer = stack.layers.find(l => l.plane === plane && l.walkable);
495	        
496	        if (planeLayer) return planeLayer.z;
497	        return stack.highestWalkableZ; // Fallback to highest available surface
