614	    /**
615	     * swapObjectManifestation - Live-updates the collision matrix when an object morphism occurs.
616	     */
617	    public async swapObjectManifestation(x: number, y: number, plane: number, oldId: number, newId: number): Promise<void> {
618	        const matrix = this.findMatrixForCoords(x, y);
619	        if (!matrix) return;
620	
621	        const key = `${plane}_${x}_${y}`;
622	        const altKey = `${x}_${y}`;
623	        const targetKey = matrix.collision_matrix[key] !== undefined ? key : altKey;
624	
625	        // Perform atomic collision swap
626	        const forensics = WorldForensicsLimb.getInstance();
627	        const oldDef = await forensics.getObjectDefinition(oldId);
628	        const newDef = await forensics.getObjectDefinition(newId);
629	
630	        // Calculate masks
631	        // Note: For simplicity, we currently assume single-tile objects (Doors/Gates)
632	        // Future refinement: Handle multi-tile width/length swaps.
633	        
634	        let collision: any = matrix.collision_matrix[targetKey] || { walkable: true, edges: {} };
635	        if (typeof collision === 'number') {
636	            collision = { walkable: (collision & 0x1) === 0, edges: {} };
637	        }
638	
639	        if (newDef.blocksMovement && !oldDef.blocksMovement) {
640	            // Manifestation became SOLID
641	            collision.walkable = false;
642	        } else if (!newDef.blocksMovement && oldDef.blocksMovement) {
643	            // Manifestation became WALKABLE
644	            collision.walkable = true;
645	        }
646	
647	        // Handle directional edges for doors
648	        // [Logic: Use WorldForensicsLimb.buildDirectionalMask to get canonical edges for the new ID]
649	        const newMaskRes = await forensics.buildDirectionalMask(x, y, plane);
650	        if (newMaskRes.ok) {
651	            collision.edges = {
652	                northBlocked: !newMaskRes.value.north,
653	                southBlocked: !newMaskRes.value.south,
654	                eastBlocked: !newMaskRes.value.east,
655	                westBlocked: !newMaskRes.value.west
656	            };
657	        }
658	
659	        matrix.collision_matrix[targetKey] = collision;
660	        logger.info({ x, y, plane, oldId, newId }, '[SPATIAL] Object Manifestation Swapped.');
661	    }
