666	    public getLogicAt(plane: number, x: number, y: number): number | DirectionalCollision {
667	        const matrix = this.findMatrixForCoords(x, y);
668	        if (matrix) {
669	            let collision = matrix.collision_matrix[`${plane}_${x}_${y}`];
670	            if (collision === undefined) {
671	                collision = matrix.collision_matrix[`${x}_${y}`];
672	            }
673	            return collision || 0;
674	        }
675	
676	        const msX = x >> 6;
677	        const msZ = y >> 6;
678	        const ms = this.loadedMapsquares.get(`${msX}_${msZ}`);
679	        if (ms) {
680	            const tx = (x & 0x3F) + PADDING_OFFSET;
681	            const tz = (y & 0x3F) + PADDING_OFFSET;
682	            const index = (plane * TILES_PER_LEVEL) + (tx * PADDED_SIZE) + tz;
683	            const tile = ms.flags[index];
684	            return tile || 0;
685	        }
686	
687	        return -1;
