701	    /**
702	     * auditTile - POG2 Autonomous Spatial Audit.
703	     * Aligned with Phase 41 refined bitmasks.
704	     */
705	    public auditTile(plane: number, x: number, y: number): {
706	        coord: Coord;
707	        walkable: boolean;
708	        collisionType: 'legacy_bitmask' | 'directional' | 'unmapped' | 'mapsquare_fragment';
709	        raw: any;
710	        directional?: { north: boolean; south: boolean; east: boolean; west: boolean };
711	        npcOnlyBlocks?: Direction[];
712	        region?: string;
713	        ms?: string;
714	        stack?: SurfaceStack;
715	    } {
716	        const coord: Coord = { x, y, plane };
717	        const matrix = this.findMatrixForCoords(x, y);
718	
719	        if (matrix) {
720	            let raw = matrix.collision_matrix[`${plane}_${x}_${y}`];
721	            if (raw === undefined) {
722	                raw = matrix.collision_matrix[`${x}_${y}`];
723	            }
724	            
725	            if (!raw) return { coord, walkable: true, collisionType: 'legacy_bitmask', raw: 0, region: matrix.city };
726	
727	            if (typeof raw === 'object') {
728	                return {
729	                    coord,
730	                    walkable: (raw as any).walkable,
731	                    collisionType: 'directional',
732	                    raw,
733	                    directional: (raw as any).edges || { 
734	                        north: (raw as any).north, 
735	                        south: (raw as any).south, 
736	                        east: (raw as any).east, 
737	                        west: (raw as any).west 
738	                    },
739	                    npcOnlyBlocks: (raw as any).npc_only_blocks,
740	                    region: matrix.city
741	                };
742	            }
743	
744	            const blocked = (raw & 0x100) !== 0 || (raw & 0x200000) !== 0 || (raw & 0x1) !== 0;
745	            return { coord, walkable: !blocked, collisionType: 'legacy_bitmask', raw, region: matrix.city };
746	        }
747	
748	        // Mapsquare Fragment Audit (Volumetric Truth)
749	        const stack = this.resolveSurfaceStack(x, y);
750	        const walkable = this.isWalkable(plane, x, y);
751	        const msX = x >> 6;
752	        const msZ = y >> 6;
753	        
754	        return {
755	            coord,
756	            walkable,
757	            collisionType: 'mapsquare_fragment',
758	            raw: stack, 
759	            ms: `${msX}_${msZ}`,
760	            stack
761	        };
