266	    /**
267	     * resolveVarbitDefinitionFromCache — Async fallback that loads a single varbit
268	     * definition from the live NXT JCACHE via the rsmv bridge subprocess.
269	     *
270	     * If the bridge returns valid data, the definition is permanently injected
271	     * into the in-memory L1 registry and the varpToVarbits inverse index.
272	     */
273	    public async resolveVarbitDefinitionFromCache(varbitId: number): Promise<{ parentVarpId: number, lsb: number, msb: number } | null> {
274	        // Already loaded?
275	        if (this.definitions.has(varbitId)) {
276	            return this.definitions.get(varbitId)!;
277	        }
278	
279	        const result = await rsmvBridge.getVarbit(varbitId);
280	        if (!result.ok) {
281	            logger.warn({ varbitId, error: result.error?.message }, 'Failed to resolve varbit definition from live cache.');
282	            return null;
283	        }
284	
285	        const raw = result.value;
286	        const parentVarpId = raw.varid;
287	        if (parentVarpId === undefined || parentVarpId === null) {
288	            logger.warn({ varbitId, raw }, 'Bridge returned varbit without varid.');
289	            return null;
290	        }
291	
292	        let lsb: number;
293	        let msb: number;
294	
295	        if (raw.bits && Array.isArray(raw.bits) && raw.bits.length === 2) {
296	            lsb = raw.bits[0];
297	            msb = raw.bits[1];
298	        } else if (raw.lsb !== undefined && raw.msb !== undefined) {
299	            lsb = raw.lsb;
300	            msb = raw.msb;
301	        } else if (raw.bitcount !== undefined && raw.bitcount > 0) {
302	            lsb = 0;
303	            msb = raw.bitcount - 1;
304	        } else {
305	            logger.warn({ varbitId, raw }, 'Bridge returned varbit without bit-window data.');
306	            return null;
307	        }
308	
309	        const def = { parentVarpId, lsb, msb };
310	        this.injectVarbitDefinition(varbitId, def);
311	
312	        // Update inverse index
313	        if (!this.varpToVarbits.has(parentVarpId)) {
314	            this.varpToVarbits.set(parentVarpId, []);
315	        }
316	        this.varpToVarbits.get(parentVarpId)!.push(varbitId);
317	
318	        logger.info({ varbitId, parentVarpId, lsb, msb }, 'Varbit definition resolved from live cache and injected.');
319	        return def;
320	    }
