1	import * as fs from 'fs';
2	import * as path from 'path';
3	import { GameState, MapZone, Coord, VolumeContext } from '../../core/models.js';
4	import { createLogger } from '../../utils/logger.js';
5	import { VarbitSovereigntyLimb } from './VarbitSovereigntyLimb.js';
6	
7	const logger = createLogger('VolumeSovereigntyLimb');
8	
9	/**
10	 * VolumeSovereigntyLimb - The "Regional Context" substrate.
11	 * Manages 764 geographic mapzones with spatial binning for O(1) lookups.
12	 */
13	export class VolumeSovereigntyLimb {
14	    private static instance: VolumeSovereigntyLimb;
15	    private zones: Map<string, MapZone> = new Map();
16	    
17	    // Spatial Binning: "mapsquare_plane" -> [Zone IDs]
18	    // mapsquare = (worldX >> 6) << 8 | (worldZ >> 6)
19	    private spatialIndex: Map<string, string[]> = new Map();
20	
21	    private constructor() {
22	        this.loadRegistry();
23	    }
24	
25	    public static getInstance(): VolumeSovereigntyLimb {
26	        if (!VolumeSovereigntyLimb.instance) {
27	            VolumeSovereigntyLimb.instance = new VolumeSovereigntyLimb();
28	        }
29	        return VolumeSovereigntyLimb.instance;
30	    }
31	
32	    private loadRegistry() {
33	        try {
34	            const registryPath = 'D:\\sovereign\\memory\\pedagogy\\mapzones_registry.json';
35	            const data = JSON.parse(fs.readFileSync(registryPath, 'utf8'));
36	            
37	            for (const [id, zone] of Object.entries(data)) {
38	                const z = zone as MapZone;
39	                z.id = id;
40	                this.zones.set(id, z);
41	                this.indexZone(z);
42	            }
43	            
44	            logger.info({ zoneCount: this.zones.size }, 'MapZone Registry synchronized.');
45	        } catch (err) {
46	            logger.error({ err }, 'Failed to load MapZone Registry from Pedagogy.');
47	        }
48	    }
49	
50	    /**
51	     * indexZone - Bins a zone into all NXT mapsquares (64×64 core) it overlaps.
52	     */
53	    private indexZone(zone: MapZone) {
54	        for (const bound of zone.bounds) {
55	            const dst = bound.dst;
56	            const plane = bound.plane;
57	            
58	            // Calculate overlapping mapsquares
59	            const startX = dst.xstart >> 6;
60	            const endX = dst.xend >> 6;
61	            const startZ = dst.zstart >> 6;
62	            const endZ = dst.zend >> 6;
63	            
64	            for (let mx = startX; mx <= endX; mx++) {
65	                for (let mz = startZ; mz <= endZ; mz++) {
66	                    const key = `${mx}_${mz}_${plane}`;
67	                    const list = this.spatialIndex.get(key) || [];
68	                    if (!list.includes(zone.id)) {
69	                        list.push(zone.id);
70	                        this.spatialIndex.set(key, list);
71	                    }
72	                }
73	            }
74	        }
75	    }
76	
77	    /**
78	     * resolveVolumeContext - Returns all volumes and the primary (most specific) one.
79	     */
80	    public resolveVolumeContext(coord: Coord, gameState: GameState): VolumeContext {
81	        const mx = coord.x >> 6;
82	        const mz = coord.y >> 6;
83	        const key = `${mx}_${mz}_${coord.plane}`;
84	        
85	        const candidateIds = this.spatialIndex.get(key) || [];
86	        const matches: MapZone[] = [];
87	        
88	        for (const id of candidateIds) {
89	            const zone = this.zones.get(id)!;
90	            if (this.isInside(coord, zone)) {
91	                matches.push(zone);
92	            }
93	        }
94	
95	        // Smallest Area Wins (Highest Specificity)
96	        let primary: MapZone | null = null;
97	        let minArea = Infinity;
98	
99	        for (const m of matches) {
100	            const area = this.calculateArea(m);
101	            if (area < minArea) {
102	                minArea = area;
103	                primary = m;
104	            }
105	        }
106	
107	        return {
108	            allVolumes: matches,
109	            primaryVolume: primary
110	        };
111	    }
112	
113	    private isInside(coord: Coord, zone: MapZone): boolean {
114	        for (const bound of zone.bounds) {
115	            if (bound.plane !== coord.plane) continue;
116	            const dst = bound.dst;
117	            if (coord.x >= dst.xstart && coord.x <= dst.xend &&
118	                coord.y >= dst.zstart && coord.y <= dst.zend) {
119	                return true;
120	            }
121	        }
122	        return false;
123	    }
124	
125	    private calculateArea(zone: MapZone): number {
126	        let total = 0;
127	        for (const bound of zone.bounds) {
128	            const dst = bound.dst;
129	            total += (dst.xend - dst.xstart + 1) * (dst.zend - dst.zstart + 1);
130	        }
131	        return total;
132	    }
133	
134	    /**
135	     * checkVolumeActive - Implementation of state-gating (Phase 14 gating).
136	     * Currently a stub for specific pedagogy varbit links.
137	     */
138	    public checkVolumeActive(zone: MapZone, gameState: GameState): { active: boolean; reason: string | null } {
139	        // Logic will be expanded as we ingest specific "Area Varbit" logic
140	        return { active: true, reason: null };
141	    }
142	}
