318	  private getVarbitMeta(varbitId: number): { varid: number; base: number; size: number } | null {
319	    if (this.varbitCache.has(varbitId)) return this.varbitCache.get(varbitId)!;
320	    
321	    const filePath = `D:/sovereign/memory/pedagogy/varbits_json/varbits-${varbitId}.json`;
322	    try {
323	        if (!fs.existsSync(filePath)) { this.varbitCache.set(varbitId, null); return null; }
324	        const data = JSON.parse(fs.readFileSync(filePath, 'utf8'));
325	        if (data.varid == null || data.bits == null) { this.varbitCache.set(varbitId, null); return null; }
326	        
327	        const meta = { 
328	            varid: data.varid, 
329	            base: data.bits[0], 
330	            size: data.bits[1] 
331	        };
332	        this.varbitCache.set(varbitId, meta);
333	        return meta;
334	    } catch { 
335	        this.varbitCache.set(varbitId, null); 
336	        return null; 
337	    }
338	  }
