340	  // VarBit read/write — the core state machine operation
341	  readVarBit(varbitId: number): number {
342	    const meta = this.getVarbitMeta(varbitId);
343	    if (!meta) return 0;
344	    
345	    // Read the base variable (varp)
346	    const varpValue = this.readVarp(meta.varid);
347	    
348	    // Extract bits
349	    const bitSize = meta.size - meta.base + 1;
350	    return (varpValue >> meta.base) & ((1 << bitSize) - 1);
351	  }
352	  
353	  writeVarBit(varbitId: number, value: number): void {
354	    const meta = this.getVarbitMeta(varbitId);
355	    if (!meta) return;
356	    
357	    const bitSize = meta.size - meta.base + 1;
358	    const mask = ((1 << bitSize) - 1) << meta.base;
359	    const current = this.readVarp(meta.varid);
360	    const newValue = (current & ~mask) | ((value & ((1 << bitSize) - 1)) << meta.base);
361	    
362	    this.writeVarp(meta.varid, newValue);
363	  }
