370	  private writeVarp(varid: number, value: number): void {
371	    if (!this.entity) return;
372	    this.entity.state.varps.set(varid, value);
373	    
374	    // Notify subscribers
375	    this.entity.emit('varp_change', { varid, value });
376	    logger.debug({ varid, value }, 'Varp updated');
377	  }
