386	    if (type === 'refresh_female') vbValue = 1; // Assuming 1 is female
387	    this.writeVarBit(VARP_5745.BODY_TYPE_GENDER, vbValue);
388	    
389	    logger.debug({ bodyType: type, varbitValue: vbValue }, 'Avatar body type updated and synced to 28556');
390	  }
