404	    
405	    // Varp 5745
406	    this.state.morphology.bodyBase = this.readVarBit(VARP_5745.BODY_BASE);
407	    this.state.morphology.torsoLegsStyle = this.readVarBit(VARP_5745.TORSO_LEGS);
