409	    this.state.morphology.bodyType = bodyVal === 1 ? 'refresh_female' : 'refresh_male';
410	    this.state.morphology.gameMode = this.readVarBit(VARP_5745.GAME_MODE);
411	    this.state.morphology.oldHeadFallback = this.readVarBit(VARP_5745.OLD_HEAD_FALLBACK) === 1;
412	    this.state.morphology.torsoOverride = this.readVarBit(VARP_5745.TORSO_OVERRIDE) === 1;
413	    
414	    // Varp 5746
415	    this.state.morphology.categoryIndices = {
416	      head: this.readVarBit(VARP_5746.HEAD),
417	      torso: this.readVarBit(VARP_5746.TORSO),
418	      legs: this.readVarBit(VARP_5746.LEGS),
419	      shoes: this.readVarBit(VARP_5746.SHOES),
420	      beard: this.readVarBit(VARP_5746.BEARD),
421	      skinMat: this.readVarBit(VARP_5746.SKIN_MAT),
422	      hairMat: this.readVarBit(VARP_5746.HAIR_MAT)
423	    };
424	    
425	    // Varp 524476
426	    this.state.morphology.appearanceIndices = {
427	      skinColor: this.readVarBit(VARP_524476.SKIN_COLOR),
428	      hairColor: this.readVarBit(VARP_524476.HAIR_COLOR),
429	      torsoColor: this.readVarBit(VARP_524476.TORSO_COLOR),
430	      randomSeed: this.readVarBit(VARP_524476.RANDOM_SEED),
431	      shoeColor: this.readVarBit(VARP_524476.SHOE_COLOR)
432	    };
433	
434	    // Resolve semantic appearance names from raw indices
435	    const bodyType = this.state.morphology.bodyType;
436	    const headIndex = this.state.morphology.categoryIndices.head;
437	    const beardIndex = this.state.morphology.categoryIndices.beard;
438	    const skinColorIndex = this.state.morphology.appearanceIndices.skinColor;
439	    const hairColorIndex = this.state.morphology.appearanceIndices.hairColor;
440	
441	    let headStyleName = "Bald";
442	    if (bodyType === 'refresh_female') {
443	      headStyleName = FEMALE_HAIRSTYLES[headIndex] ?? `Female Hair ${headIndex}`;
444	    } else {
445	      headStyleName = MALE_HAIRSTYLES[headIndex] ?? `Male Hair ${headIndex}`;
446	    }
447	
448	    this.state.semantic = {
449	      headStyle: headStyleName,
450	      beardStyle: BEARDS[beardIndex] ?? `Beard ${beardIndex}`,
451	      skinColor: SKIN_COLORS[skinColorIndex] ?? `Skin Color ${skinColorIndex}`,
452	      hairColor: HAIR_COLORS[hairColorIndex] ?? `Hair Color ${hairColorIndex}`
453	    };
