69	    /**
70	     * canCast - Validates spatial and resource constraints.
71	     */
72	    public canCast(castor: NPC, target: NPC, abilityId: string, currentTick: number): { success: boolean; reason?: string; inRange?: boolean } {
73	        const ability = this.abilityRegistry.get(abilityId);
74	        if (!ability) return { success: false, reason: 'Ability not recognized' };
75	
76	        // 1. Cooldown Check
77	        const cd = castor.cooldowns?.[abilityId] || 0;
78	        if (currentTick < cd) {
79	            return { success: false, reason: `Cooldown: ${cd - currentTick} ticks remaining` };
80	        }
81	
82	        // 2. Spatial Check
83	        const dist = Math.max(Math.abs(castor.x - target.x), Math.abs(castor.y - target.y));
84	        const inRange = dist <= ability.range;
85	
86	        if (!inRange) {
87	            return { success: false, reason: 'Out of range', inRange: false };
88	        }
89	
90	        // 3. Resource Check
91	        if (ability.adrenalineCost && (castor.adrenaline || 0) < ability.adrenalineCost) {
92	            return { success: false, reason: 'Insufficient Adrenaline' };
93	        }
94	
95	        return { success: true, inRange: true };
