106	
107	        // 1. Mutate Castor State
108	        if (ability.adrenalineGained) {
109	            if ((castor as any).addAdrenaline) {
110	                (castor as any).addAdrenaline(ability.adrenalineGained);
111	            } else {
112	                castor.adrenaline = Math.min(10000, (castor.adrenaline || 0) + ability.adrenalineGained);
113	            }
114	        }
115	        if (ability.adrenalineCost) {
116	            castor.adrenaline = Math.max(0, (castor.adrenaline || 0) - ability.adrenalineCost);
117	        }
118	        if (ability.necrosisGained) {
119	            castor.necrosisStacks = (castor.necrosisStacks || 0) + ability.necrosisGained;
120	        }
121	
122	        // 2. Set Cooldowns (Modernized: Auto-attack rhythm is usually 4 ticks)
123	        const ticks = ability.cooldownTicks || 4; 
124	        castor.cooldowns[abilityId] = currentTick + ticks;
125	        castor.lastCombatTick = currentTick;
126	
127	        // 3. Apply Damage to Target
128	        if (ability.damageRange) {
129	            const [min, max] = ability.damageRange;
130	            const damage = Math.floor(Math.random() * (max - min + 1)) + min;
131	            
132	            const wasDead = (target as any).isDead;
133	            if ((target as any).applyDamage) {
