135	                logger.info(`DAMAGE: ${damage} applied to ${target.name}. New HP: ${(target as any).currentHp}`);
136	            }
137	
138	            // 4. Single-shot Death Check
139	            if ((target as any).isDead && !wasDead) {
140	                logger.info(`💀 SOVEREIGN_DEATH: ${target.name} has fallen.`);
141	                // Emit event via metadata or a central emitter if we had one.
142	                // For now, we flag it in target metadata.
143	                (target as any).metadata = {
144	                    ...(target.metadata || {}),
145	                    deathEvent: true,
146	                    deathTick: currentTick
147	                };
148	            }
149	        }
150	
151	        // 5. Apply "Hit Flash" metadata for the Radar
152	        (target as any).metadata = {
153	            ...(target.metadata || {}),
154	            lastHitTick: Date.now(),
155	            hitFlash: true,
156	            lastHitDamage: ability.damageRange ? true : false // for UI hit-splats later
157	        };
158	    }
