15	 * - 9-Tile Adjacency: center, left, bot, right, top, topleft, botleft, botright, topright.
16	 */
17	
18	export interface CollisionMask {
19	    center: boolean;
20	    left: boolean;
21	    right: boolean;
22	    top: boolean;
23	    bottom: boolean;
24	    topleft: boolean;
25	    topright: boolean;
26	    botleft: boolean;
27	    botright: boolean;
28	}
29	
30	export class SovereignCollisionEngine {
31	    private tickRateMs: number = 600;
32	    private globalCycleMs: number = 6000;
33	
34	    constructor() {
35	        logger.info('Initializing Sovereign Collision Engine (9-Way Adjacency)...');
36	    }
37	
38	    /**
39	     * "Yesterday's Truth" logic for the 600ms World Pulse.
40	     * Determines if a 1-tile movement is possible based on the adjacency bitmask.
41	     */
42	    public canMove(currentPos: { x: number, y: number, plane: number }, targetPos: { x: number, y: number }, mask: CollisionMask): boolean {
43	        // Simple 9-way truth check
44	        if (targetPos.x === currentPos.x && targetPos.y === currentPos.y) return true; // Center
45	        
46	        const dx = targetPos.x - currentPos.x;
47	        const dy = targetPos.y - currentPos.y;
48	
49	        if (dx === -1 && dy === 0) return mask.left;
50	        if (dx === 1 && dy === 0) return mask.right;
51	        if (dx === 0 && dy === 1) return mask.top;
52	        if (dx === 0 && dy === -1) return mask.bottom;
53	        
54	        // Diagonals
55	        if (dx === -1 && dy === 1) return mask.topleft;
56	        if (dx === 1 && dy === 1) return mask.topright;
57	        if (dx === -1 && dy === -1) return mask.botleft;
58	        if (dx === 1 && dy === -1) return mask.botright;
59	
60	        return false;
61	    }
