7	const logger = createLogger('DirectionalPathfinder');
8	
9	class PathNode implements Comparable<PathNode> {
10	    public x: number;
11	    public y: number;
12	    public plane: number;
13	    public gScore: number;
14	    public fScore: number;
15	    public parent?: PathNode;
16	
17	    constructor(coord: Coord, gScore: number, fScore: number, parent?: PathNode) {
18	        this.x = coord.x;
19	        this.y = coord.y;
20	        this.plane = coord.plane;
21	        this.gScore = gScore;
22	        this.fScore = fScore;
23	        this.parent = parent;
24	    }
25	
26	    compare(other: PathNode): number {
27	        // Min-heap: lower fScore = higher priority
28	        return this.fScore - other.fScore;
29	    }
30	
31	    toCoord(): Coord {
32	        return { x: this.x, y: this.y, plane: this.plane };
33	    }
