40	/**
41	 * DirectionalPathfinder - The "Motor" of the Sovereign Organism.
42	 * Implements Quaternary A* incorporating Directional Collision.
43	 */
44	export class DirectionalPathfinder {
45	
46	    constructor(private spatial: SpatialSovereigntyLimb) {
47	    }
48	
49	    /**
50	     * findPath - Quaternary A* for worker environments.
51	     */
52	    public findPath(
53	        start: Coord,
54	        end: Coord,
55	        gameState?: GameState,
56	        isPlayer = true,
57	        debug = false
58	    ): Coord[] {
59	        const npcIndex = gameState?.npcSpatialIndex;
60	        const openSet = new BinaryHeap<PathNode>();
61	        const closedSet = new Set<string>();
62	        const gScores = new Map<string, number>();
63	
64	        const startNode = new PathNode(
65	            start,
66	            0,
67	            this.heuristic(start, end)
68	        );
69	
70	        openSet.insert(startNode);
71	        gScores.set(startNode.key, 0);
72	
73	        let iterations = 0;
74	        const MAX_ITERATIONS = Math.max(5000, Math.floor(this.heuristic(start, end) * 100));
75	
76	        while (!openSet.isEmpty() && iterations < MAX_ITERATIONS) {
77	            iterations++;
78	            const current = openSet.pop()!;
79	
80	            if (current.x === end.x && current.y === end.y) {
81	                if (debug) logger.info(`Path found in ${iterations} iterations.`);
82	                return this.reconstructPath(current);
83	            }
84	
85	            closedSet.add(current.key);
86	
87	            // Expand Neighbors
88	            const neighbors = this.getNeighbors(current);
89	            for (const { coord: next, direction } of neighbors) {
90	                const nKey = `${next.plane}_${next.x}_${next.y}`;
91	
92	                if (closedSet.has(nKey)) continue;
93	
94	                // THE SOVEREIGN RULE: Verify Directional Collision
95	                const canMove = this.canMove(current.toCoord(), next, direction, npcIndex, isPlayer);
96	                if (!canMove) continue;
97	
98	                const tentativeG = current.gScore + 1;
99	                const existingG = gScores.get(nKey) ?? Infinity;
100	
101	                if (tentativeG < existingG) {
102	                    const nextNode = new PathNode(
103	                        next,
104	                        tentativeG,
105	                        tentativeG + this.heuristic(next, end),
106	                        current
107	                    );
108	                    gScores.set(nKey, tentativeG);
109	                    openSet.insert(nextNode);
110	                }
111	            }
112	        }
113	
114	        if (debug) logger.warn(`No path found after ${iterations} iterations.`);
115	        return [];
116	    }
117	
118	    /**
119	     * canMove - THE SOVEREIGN NAVIGATION RULE:
120	     * A move from (from) to (to) is valid ONLY if:
121	     * 1. (from) does not block exit in DIRECTION.
122	     * 2. (to) does not block entry in REVERSE_DIRECTION.
123	     * 3. Diagonals strictly forbid corner-cutting if adjacent cardinals are blocked.
124	     */
125	    public canMove(
126	        from: Coord,
127	        to: Coord,
128	        direction: Direction,
129	        npcIndex?: Map<string, any[]>,
130	        isPlayer = true
131	    ): boolean {
132	        // Target tile must be structurally walkable
133	        // Exception: 'up' / 'down' are portal transitions — bypass collision entirely
134	        if (direction === 'up' || direction === 'down') {
135	            const registry = PlaneTransitionRegistry.getInstance();
136	            const link = registry.getLink(from);
137	            return link !== null &&
138	                   link.to.x === to.x &&
139	                   link.to.y === to.y &&
140	                   link.to.plane === to.plane;
141	        }
142	
143	        if (!this.isWalkable(to.plane, to.x, to.y)) {
144	            return false;
145	        }
146	
147	        // --- DYNAMIC OBSTACLE CHECK (Phase 43) ---
148	        if (npcIndex) {
149	            const key = `${to.x},${to.y},${to.plane}`;
150	            const npcs = npcIndex.get(key);
151	            if (npcs && npcs.length > 0) {
152	                // If any NPC on the tile blocks movement
153	                return false;
154	            }
155	        }
156	
157	        // --- DIAGONAL CLIP RULE ---
158	        if (direction === 'north-east' || direction === 'north-west' || direction === 'south-east' || direction === 'south-west') {
159	            // Unpack direction
160	            const isNorth = direction.includes('north');
161	            const isSouth = direction.includes('south');
162	            const isEast = direction.includes('east');
163	            const isWest = direction.includes('west');
164	
165	            // Find orthogonal neighbors
166	            const orth1X = isEast ? from.x + 1 : (isWest ? from.x - 1 : from.x);
167	            const orth1Y = from.y; // Horizontal adj
168	            const orth2X = from.x;
169	            const orth2Y = isNorth ? from.y + 1 : (isSouth ? from.y - 1 : from.y); // Vertical adj
170	
171	            // 1. Orthogonal tiles must be structurally walkable (no corner cutting across solids)
172	            if (!this.isWalkable(from.plane, orth1X, orth1Y)) return false;
173	            if (!this.isWalkable(from.plane, orth2X, orth2Y)) return false;
174	
175	            // 2. Both current and target tiles must permit orthogonal transit within the diagonal envelope
176	            if (isNorth) { if (!this.canTransit(from, to, 'north', isPlayer)) return false; }
177	            if (isSouth) { if (!this.canTransit(from, to, 'south', isPlayer)) return false; }
178	            if (isEast)  { if (!this.canTransit(from, to, 'east', isPlayer)) return false; }
179	            if (isWest)  { if (!this.canTransit(from, to, 'west', isPlayer)) return false; }
180	
181	            return true;
182	        }
183	
184	        // --- CARDINAL CHECK ---
185	        return this.canTransit(from, to, direction, isPlayer);
186	    }
187	
188	    /**
189	     * Helper to verify if transit across an exact cardinal edge is permitted safely.
190	     */
191	    private canTransit(from: Coord, to: Coord, direction: Direction, isPlayer = true): boolean {
192	        const fromLogic = this.spatial.getLogicAt(from.plane, from.x, from.y);
193	        const toLogic = this.spatial.getLogicAt(to.plane, to.x, to.y);
194	
195	        if (fromLogic === null || toLogic === null) return false;
196	
197	        // 1. From Tile Edge Blocking
198	        if (typeof fromLogic === 'object') {
199	            const c = fromLogic as any;
200	            if (!isPlayer && c.npc_only_blocks?.includes(direction)) return false;
201	
202	            if (c.edges) {
203	                const edges = c.edges;
204	                if (direction === 'north' && edges.northBlocked) return false;
205	                if (direction === 'south' && edges.southBlocked) return false;
206	                if (direction === 'east' && edges.eastBlocked) return false;
207	                if (direction === 'west' && edges.westBlocked) return false;
208	            } else if (direction in c) {
209	                if (c[direction] === false) return false;
210	            }
211	        }
212	
213	        // 2. To Tile Edge Blocking
214	        const reverseDir = this.getReverseDirection(direction);
215	        if (typeof toLogic === 'object') {
216	            const c = toLogic as any;
217	            if (!isPlayer && c.npc_only_blocks?.includes(reverseDir)) return false;
218	
219	            if (c.edges) {
220	                const edges = c.edges;
221	                if (reverseDir === 'north' && edges.northBlocked) return false;
222	                if (reverseDir === 'south' && edges.southBlocked) return false;
223	                if (reverseDir === 'east' && edges.eastBlocked) return false;
224	                if (reverseDir === 'west' && edges.westBlocked) return false;
225	            } else if (reverseDir in c) {
226	                if (c[reverseDir] === false) return false;
227	            }
228	        }
229	
230	        // Legacy compat (0x100 overlay block etc)
231	        if (typeof toLogic === 'number' && (toLogic & 0x100)) return false;
232	
233	        return true;
234	    }
235	
236	    /**
237	     * isWalkable - Phase C3: Deterministic Cross-Region Check.
238	     * Delegates directly to SpatialSovereigntyLimb which uses bounds-based
239	     * matrix resolution (findMatrixForCoords). The old SpaceRegistry name gate
240	     * caused false-positives when registry names didn't match loaded matrix names.
241	     */
242	    private isWalkable(p: number, x: number, z: number): boolean {
243	        // Direct delegation — SpatialSovereigntyLimb.isWalkable already handles:
244	        // 1. GAL override check
245	        // 2. Bounds-based matrix lookup (findMatrixForCoords)
246	        // 3. Legacy surface stack fallback
247	        // If no matrix covers this tile, it falls through to surface stack,
248	        // which defaults walkable=true (No-Man's-Land equivalent).
249	        return this.spatial.isWalkable(p, x, z);
250	    }
251	
252	    private heuristic(a: Coord, b: Coord): number {
253	        // Chebyshev distance for uniform diagonal cost, slightly scaled to prefer direct routes
254	        const dx = Math.abs(a.x - b.x);
255	        const dy = Math.abs(a.y - b.y);
256	        const dp = Math.abs(a.plane - b.plane);
257	        return (Math.max(dx, dy) + (dp * 10)) * 1.01;
258	    }
259	
260	    private getNeighbors(node: PathNode): { coord: Coord; direction: Direction }[] {
261	        const neighbors: { coord: Coord; direction: Direction }[] = [
262	            { coord: { x: node.x, y: node.y + 1, plane: node.plane }, direction: 'north' },
263	            { coord: { x: node.x, y: node.y - 1, plane: node.plane }, direction: 'south' },
264	            { coord: { x: node.x + 1, y: node.y, plane: node.plane }, direction: 'east' },
265	            { coord: { x: node.x - 1, y: node.y, plane: node.plane }, direction: 'west' },
266	            { coord: { x: node.x + 1, y: node.y + 1, plane: node.plane }, direction: 'north-east' },
267	            { coord: { x: node.x - 1, y: node.y + 1, plane: node.plane }, direction: 'north-west' },
268	            { coord: { x: node.x + 1, y: node.y - 1, plane: node.plane }, direction: 'south-east' },
269	            { coord: { x: node.x - 1, y: node.y - 1, plane: node.plane }, direction: 'south-west' }
270	        ];
271	
272	        // ── Vertical Plane Transitions ────────────────────────────────────────
273	        const link = PlaneTransitionRegistry.getInstance().getLink(node.toCoord());
274	        if (link) {
275	            const dir: Direction = link.to.plane > node.plane ? 'up' : 'down';
276	            neighbors.push({ coord: link.to, direction: dir });
277	        }
278	
279	        return neighbors;
280	    }
281	
282	    private getReverseDirection(dir: Direction): Direction {
283	        const map: Record<Direction, Direction> = {
284	            north: 'south',
285	            south: 'north',
286	            east: 'west',
287	            west: 'east',
288	            'north-east': 'south-west',
289	            'south-west': 'north-east',
290	            'north-west': 'south-east',
291	            'south-east': 'north-west',
292	            up: 'down',
293	            down: 'up'
294	        };
295	        return map[dir];
296	    }
297	
298	    private reconstructPath(node: PathNode): Coord[] {
299	        const path: Coord[] = [];
300	        let curr: PathNode | undefined = node;
301	        while (curr) {
302	            path.unshift(curr.toCoord());
303	            curr = curr.parent;
304	        }
305	        return path;
306	    }
307	
308	    public handleMinimapClick(start: Coord, end: Coord, state: GameState): Coord[] {
309	        logger.info({ start, end }, '[DirectionalPathfinder] Minimap click handler invoked.');
310	        return this.findPath(start, end, state);
311	    }
312	}
