7	export interface NamedLocation {
8	    id: string;
9	    name: string;
10	    coord: Coord;
11	}
12	
13	/**
14	 * NavigationLimb
15	 * 
16	 * Generalizes "Places" in the POG2 world. Resolves named locations
17	 * (e.g., "Lumbridge", "Barrows") into coordinates by querying the 
18	 * WorldGrounding manifest, rather than using side templates.
19	 */
20	export class NavigationLimb {
21	    private static instance: NavigationLimb;
22	    private landmarks: Map<string, NamedLocation> = new Map();
23	
24	    private constructor() {
25	        this.initializeLandmarks();
26	    }
27	
28	    public static getInstance(): NavigationLimb {
29	        if (!NavigationLimb.instance) {
30	            NavigationLimb.instance = new NavigationLimb();
31	        }
32	        return NavigationLimb.instance;
33	    }
34	
35	    private initializeLandmarks() {
36	        // Load authoritative landmarks from the grounding manifest if they exist
37	        const grounding = WorldGroundingLimb.getInstance();
38	        const manifest = grounding.getManifest();
39	
40	        for (const [id, entry] of Object.entries(manifest.entities)) {
41	            if (id.startsWith('place_') || (entry as any).type === 'LANDMARK') {
42	                const data = entry.grounded.data;
43	                const coord = entry.coord || data.coord || data.spatial;
44	                if (coord) {
45	                    this.landmarks.set(id.replace('place_', '').toLowerCase(), {
46	                        id,
47	                        name: data.name || id,
48	                        coord: { x: coord.x, y: coord.y, plane: coord.plane || 0 }
49	                    });
50	                }
51	            }
52	        }
53	
54	        // Fallback: Legacy landmarks if manifest is empty (Recalibration Anchor)
55	        if (this.landmarks.size === 0) {
56	            logger.warn('Grounding manifest empty of places. Loading legacy navigation fallbacks.');
57	            const legacy = [
58	                { name: 'Lumbridge', x: 3221, y: 3218 },
59	                { name: 'Draynor', x: 3108, y: 3352 },
60	                { name: 'Falador', x: 2964, y: 3378 },
61	                { name: 'Varrock', x: 3212, y: 3422 },
62	                { name: 'Edgeville', x: 3093, y: 3491 },
63	                { name: 'Barrows', x: 3564, y: 3288 },
64	                { name: 'KBD', x: 2273, y: 4695 },
65	                { name: 'Prifddinas', x: 2200, y: 3400 }
66	            ];
67	
68	            legacy.forEach(l => {
69	                this.landmarks.set(l.name.toLowerCase(), {
70	                    id: `place_${l.name.toLowerCase()}`,
71	                    name: l.name,
72	                    coord: { x: l.x, y: l.y, plane: 0 }
73	                });
74	            });
75	        }
76	    }
77	
78	    public resolveLocation(name: string): NamedLocation | null {
79	        return this.landmarks.get(name.toLowerCase()) || null;
80	    }
81	
82	    public getAllLocations(): NamedLocation[] {
83	        return Array.from(this.landmarks.values());
84	    }
85	}
