1	import chalk from 'chalk';
2	import { GameState, NPC, Coord, DirectionalCollision, SovereignAvatar } from '../../core/models.js';
3	import { SovereignAvatarEntity } from '../../core/SovereignAvatar.js';
4	import { SpatialSovereigntyLimb, PADDED_SIZE, CORE_SIZE } from './SpatialSovereigntyLimb.js';
5	import { GhostSplatEngine, GhostSplatField } from '../../substrates/GhostSplatEngine.js';
6	
7	export class SpatialRadarLimb {
8	    private static instance: SpatialRadarLimb;
9	    private spatialLimb: SpatialSovereigntyLimb;
10	
11	    private constructor() {
12	        this.spatialLimb = SpatialSovereigntyLimb.getInstance();
13	    }
14	
15	    public static getInstance(): SpatialRadarLimb {
16	        if (!SpatialRadarLimb.instance) {
17	            SpatialRadarLimb.instance = new SpatialRadarLimb();
18	        }
19	        return SpatialRadarLimb.instance;
20	    }
21	
22	    /**
23	     * render - Generates a 2D Unicode grid representing the authoritative world state.
24	     * Default: 21x21 viewport.
25	     */
26	    public render(state: GameState, avatar: SovereignAvatar, fullRegion: boolean = true): string {
27	        const center = avatar.coord;
28	        const radius = fullRegion ? 33 : 10; 
29	        let output = '\n';
30	
31	        const rx = Math.floor(center.x / 64);
32	        const ry = Math.floor(center.y / 64);
33	
34	        // Header
35	        const stats = avatar.adrenaline !== undefined ? ` | Adrenaline: ${chalk.yellow(avatar.adrenalinePercent)} | Necrosis: ${chalk.green(avatar.necrosisStacks || 0)}` : '';
36	        output += chalk.cyan(`[ SPATIAL RADAR ] - Tick: ${state.tickNumber} | Region: ${rx}_${ry}${stats}\n`);
37	        output += chalk.dim('┌' + '─'.repeat(radius * 4 + 1) + '┐\n');
38	
39	        const yStart = fullRegion ? (ry * 64) + 65 : center.y + radius;
40	        const yEnd = fullRegion ? (ry * 64) - 1 : center.y - radius;
41	        const xStart = fullRegion ? (rx * 64) - 1 : center.x - radius;
42	        const xEnd = fullRegion ? (rx * 64) + 65 : center.x + radius;
43	
44	        const ghostSplat = GhostSplatEngine.getInstance().getLatestField();
45	        const projectedNpcs = new Set<string>();
46	        const projectedPlayers = new Set<string>();
47	        if (ghostSplat) {
48	            ghostSplat.projections.forEach(ghost => {
49	                const coord = ghost.projectedCoord;
50	                const key = `${coord.x},${coord.y},${coord.plane}`;
51	                if (ghost.entityId.startsWith('player_')) {
52	                    projectedPlayers.add(key);
53	                } else {
54	                    projectedNpcs.add(key);
55	                }
56	            });
57	        }
58	
59	        for (let y = yStart; y >= yEnd; y--) {
60	            let line = chalk.dim('│ ');
61	            for (let x = xStart; x <= xEnd; x++) {
62	                line += this.renderTile(x, y, center.plane, state, avatar, projectedNpcs, projectedPlayers, ghostSplat || undefined);
63	            }
64	            output += line + chalk.dim(' │\n');
65	        }
66	
67	        output += chalk.dim('└' + '─'.repeat(radius * 4 + 1) + '┘\n');
68	        output += this.renderLegend();
69	        
70	        return output;
71	    }
72	
73	    private renderTile(x: number, y: number, plane: number, state: GameState, avatar: SovereignAvatar, projectedNpcs: Set<string>, projectedPlayers: Set<string>, field?: GhostSplatField): string {
74	        const center = avatar.coord;
75	        const centerOffset = Math.floor(PADDED_SIZE / 2);
76	        
77	        // 0. Thermal Compositing (Phase 45: Thermal Overlay)
78	        let thermalBg: (s: string) => string = (s) => s;
79	        if (field) {
80	            const lx = x - center.x + centerOffset;
81	            const ly = y - center.y + centerOffset;
82	            if (lx >= 0 && lx < PADDED_SIZE && ly >= 0 && ly < PADDED_SIZE) {
83	                const heat = field.heatmap[ly * PADDED_SIZE + lx];
84	                if (heat > 0) {
85	                    if (heat >= 3) thermalBg = chalk.bgRed.black; // Critical Heat
86	                    else if (heat >= 2) thermalBg = chalk.bgYellow.black; // High Heat
87	                    else thermalBg = chalk.bgAnsi256(226).black; // Low Heat (Yellowish)
88	                }
89	            }
90	        }
91	
92	        // 1. Resolve Entity Priority
93	        if (avatar.coord.x === x && avatar.coord.y === y && avatar.coord.plane === plane) {
94	            let char = '@ ';
95	            if (avatar.metadata?.isAnimating) {
96	                char = '@*'; // Animation burst
97	                return chalk.cyan.bold.bgWhite(char);
98	            }
99	            if (avatar.metadata?.activeHitsplats?.length > 0) {
100	                // Return total damage in this tick
101	                const total = avatar.metadata.activeHitsplats.reduce((acc: number, h: any) => acc + h.amount, 0);
102	                char = `!${Math.min(9, Math.floor(total/100))}`; // Show intensity 0-9
103	                return thermalBg(chalk.white.bold(char));
104	            }
105	            return thermalBg(chalk.cyan.bold(char));
106	        }
107	
108	        const coordKey = `${x},${y},${plane}`;
109	        const npcsOnTile = state.npcSpatialIndex.get(coordKey) || [];
110	        if (npcsOnTile.length > 0) {
111	            const npc = npcsOnTile[0];
112	            const isTarget = avatar.intent?.targetId === `npc_${npc.id}`;
113	            const isHit = npc.metadata?.hitFlash === true;
114	            
115	            let color = isTarget ? chalk.bgMagenta.white : chalk.magenta;
116	            if (isHit) color = chalk.bgWhite.red.bold;
117	
118	            let char = 'N ';
119	            if (npc.interactionState === 'MOVING') char = '! ';
120	            if (npc.interactionState === 'EXECUTING') char = '* ';
121	
122	            return thermalBg(color(char));
123	        }
124	
125	        if (projectedPlayers.has(coordKey)) {
126	            return chalk.dim.cyan('◎ '); // Ghost Player
127	        }
128	        
129	        if (projectedNpcs.has(coordKey)) {
130	            return chalk.dim.magenta('○ '); // Ghost NPC
131	        }
132	
133	        // 2. Resolve Logic Substrate
134	        const audit = this.spatialLimb.auditTile(plane, x, y);
135	        let char = '. ';
136	        let tileColor = (text: string) => text;
137	
138	        // 2.5 Safespot Highlighting (Phase 45)
139	        if (field) {
140	            const isSafespot = field.safespots.some(s => s.x === x && s.y === y && s.plane === plane);
141	            if (isSafespot) {
142	                char = '+ ';
143	                tileColor = chalk.green.bold;
144	            }
145	        }
146	
147	        if (audit.collisionType === 'mapsquare_fragment' && audit.stack) {
148	            const layer = audit.stack.layers.find(l => l.plane === plane);
149	            if (layer?.type === 'water') {
150	                char = '~ ';
151	                tileColor = chalk.blue;
152	            } else if (!layer?.walkable) {
153	                char = 'X ';
154	                tileColor = chalk.red;
155	            } else if (layer?.type === 'bridge') {
156	                char = '= ';
157	                tileColor = chalk.yellow;
158	            }
159	        } else if (audit.collisionType === 'directional' && audit.raw) {
160	             const c = audit.raw as any;
161	             if (c.walkable === false) {
162	                 char = 'X ';
163	                 tileColor = chalk.red;
164	             } else {
165	                 char = this.resolveEdgeChar(c.edges || c);
166	                 tileColor = chalk.yellow;
167	             }
168	        } else if (!audit.walkable) {
169	            char = 'X ';
170	            tileColor = chalk.red;
171	        }
172	
173	        // 2.5 Combat Range Overlay
174	        if (avatar.intent?.action === 'castAbility' && (avatar.intent as any).abilityId) {
175	            const dist = Math.max(Math.abs(avatar.x - x), Math.abs(avatar.y - y));
176	            const range = (avatar.intent as any).range || 7; // Default or fetched
177	            if (dist <= range && char === '. ') {
178	                tileColor = chalk.dim.yellow;
179	                char = '· ';
180	            }
181	        }
182	
183	        // 3. Intent Trace (Ghost Avatar) - now handled by PlayerAgent ghosts above
184	        if (avatar.intent && avatar.intent.coord && !projectedPlayers.has(coordKey)) {
185	            if (avatar.intent.coord.x === x && avatar.intent.coord.y === y && avatar.intent.coord.plane === plane) {
186	                return chalk.dim.cyan('◎ ');
187	            }
188	        }
189	
190	        // 4. Boundary Markers (Padded Region Seams)
191	        // 4. Boundary Markers (Playable Core vs Padded Neighbor Bleed)
192	        const rx = Math.floor(avatar.coord.x / 64);
193	        const ry = Math.floor(avatar.coord.y / 64);
194	        
195	        const minX = rx * 64;
196	        const maxX = minX + 63;
197	        const minY = ry * 64;
198	        const maxY = minY + 63;
199	
200	        const inCore = x >= minX && x <= maxX && y >= minY && y <= maxY;
201	
202	        if (!inCore) {
203	            tileColor = (txt) => chalk.bgGrey.white(txt);
204	        }
205	
206	        return tileColor(char);
207	    }
208	
209	    private resolveEdgeChar(edges: any): string {
210	        const n = edges.northBlocked || edges.north === false;
211	        const s = edges.southBlocked || edges.south === false;
212	        const e = edges.eastBlocked || edges.east === false;
213	        const w = edges.westBlocked || edges.west === false;
214	
215	        if (n && s && e && w) return '□ ';
216	        if (n && s) return '║ ';
217	        if (e && w) return '═ ';
218	        if (n && e) return '└ ';
219	        if (n && w) return '┘ ';
220	        if (s && e) return '┌ ';
221	        if (s && w) return '┐ ';
222	        if (n) return '╨ ';
223	        if (s) return '╥ ';
224	        if (e) return '╟ ';
225	        if (w) return '╢ ';
226	        
227	        return '. ';
228	    }
229	
230	    private renderLegend(): string {
231	        return chalk.dim('  Legend: ') + 
232	               chalk.cyan('@') + chalk.dim(' (You) ') + 
233	               chalk.magenta('N') + chalk.dim(' (NPC) ') + 
234	               chalk.red('X') + chalk.dim(' (Blocked) ') + 
235	               chalk.blue('~') + chalk.dim(' (Water) ') +
236	               chalk.yellow('║/═') + chalk.dim(' (Partial Block) ') +
237	               chalk.dim.magenta('○') + chalk.dim(' (Ghost NPC) ') +
238	               chalk.dim.cyan('◎') + chalk.dim(' (Ghost You)\n');
239	    }
240	}
