1	import { SpatialMetrics } from '../../types/spatial.js';
2	import * as fs from 'fs/promises';
3	import * as path from 'path';
4	
5	export class SpatialMetricsRegistry {
6	  private static instance: SpatialMetricsRegistry;
7	  private metrics: Map<number, SpatialMetrics> = new Map();
8	  private readonly MODEL_UNITS_PER_TILE = 512;
9	  
10	  private constructor() {}
11	  
12	  public static getInstance(): SpatialMetricsRegistry {
13	    if (!SpatialMetricsRegistry.instance) {
14	      SpatialMetricsRegistry.instance = new SpatialMetricsRegistry();
15	    }
16	    return SpatialMetricsRegistry.instance;
17	  }
18	  
19	  async hydrateFromPedagogy(): Promise<void> {
20	    const dir = 'D:/sovereign/cache_pedagogy';
21	    try {
22	      const files = await fs.readdir(dir);
23	      for (const file of files) {
24	        if (!file.endsWith('.json')) continue;
25	        
26	        try {
27	          const filePath = path.join(dir, file);
28	          const content = await fs.readFile(filePath, 'utf8');
29	          const profile = JSON.parse(content);
30	          
31	          if (profile.id && profile.metrics && profile.metrics.dimensions) {
32	            // Extract numeric ID from "npc:0" or similar
33	            const idStr = profile.id.replace('npc:', '').replace('object:', '').replace('item:', '');
34	            const id = parseInt(idStr, 10);
35	            
36	            if (!isNaN(id)) {
37	              let type: 'npc' | 'item' | 'object' | 'player' = 'npc';
38	              if (profile.id.startsWith('object:')) type = 'object';
39	              if (profile.id.startsWith('item:')) type = 'item';
40	              if (profile.id.startsWith('player:')) type = 'player';
41	              
42	              this.metrics.set(id, this.convertProfile(profile, id, type, file));
43	            }
44	          }
45	        } catch (e) {
46	          // Skip malformed files
47	          continue;
48	        }
49	      }
50	      console.log(`SpatialMetricsRegistry hydrated: ${this.metrics.size} entities`);
51	    } catch (err) {
52	      console.error('Failed to read pedagogy directory:', err);
53	    }
54	  }
55	  
56	  private convertProfile(profile: any, entityId: number, entityType: 'npc' | 'item' | 'object' | 'player', filename: string): SpatialMetrics {
57	    const { x, y, z } = profile.metrics.dimensions;
58	    const maxHorizontal = Math.max(x, y);
59	    
60	    return {
61	      entityId,
62	      entityType,
63	      dimensions: { x, y, z },
64	      tileScale: {
65	        radius: (maxHorizontal / 2) / this.MODEL_UNITS_PER_TILE,
66	        height: z / this.MODEL_UNITS_PER_TILE,
67	        volume: (x * y * z) / Math.pow(this.MODEL_UNITS_PER_TILE, 3)
68	      },
69	      polyCount: profile.metrics.polyCount || 0,
70	      cacheRevision: profile.cacheRevision || 0,
71	      extractionTimestamp: Date.now(),
72	      sourceFile: filename
73	    };
74	  }
75	  
76	  getMetrics(entityId: number): SpatialMetrics | undefined {
77	    return this.metrics.get(entityId);
78	  }
79	}
