1	import { OBJECT_INTERACTION_STORE, getInteractionResult } from '../../forensics/ObjectBinaryStore.js';
2	import { SovereignVocabularyLimb, InteractionCategory } from '../logical/SovereignVocabularyLimb.js';
3	
4	export type ProbeState = 'IDLE' | 'TRACE' | 'BUMP_DETECTED' | 'INTERACTING' | 'TRANSITING';
5	
6	export interface ProbeSimulationState {
7	    probeId: number;
8	    entityId: number; // 3597 or 7015
9	    state: ProbeState;
10	    coords: { x: number, z: number, plane: number };
11	    targetCoords?: { x: number, z: number, plane: number };
12	    lastBumpedObjectId?: number;
13	}
14	
15	/**
16	 * Sovereign Interaction Limb
17	 * Neural controller for autonomous spatial probes.
18	 */
19	export class SovereignInteractionLimb {
20	    private activeProbes: Map<number, ProbeSimulationState> = new Map();
21	    private vocabLimb: SovereignVocabularyLimb;
22	
23	    constructor() {
24	        this.vocabLimb = new SovereignVocabularyLimb();
25	        console.log("SovereignInteractionLimb: Neural Interaction & Semantics initialized.");
26	    }
27	
28	    /**
29	     * Registers a new probe for autonomous archaeology.
30	     */
31	    public registerProbe(probeId: number, entityId: number, startCoords: { x: number, z: number, plane: number }) {
32	        this.activeProbes.set(probeId, {
33	            probeId,
34	            entityId,
35	            state: 'IDLE',
36	            coords: startCoords
37	        });
38	        console.log(`Probe Registered: ${probeId} (Entity: ${entityId}) at ${JSON.stringify(startCoords)}`);
39	    }
40	
41	    /**
42	     * Core Simulation Tick: Drives probe decision logic, gated by CanonicalClock.
43	     */
44	    public onTick() {
45	        if (!require('../../utils/CanonicalClock.js').clock.isTickingPermitted()) {
46	            return;
47	        }
48	        for (const [id, probe] of this.activeProbes) {
49	            this.processProbeLogic(probe);
50	        }
51	    }
52	
53	    private processProbeLogic(probe: ProbeSimulationState) {
54	        switch (probe.state) {
55	            case 'IDLE':
56	                this.initiateTrace(probe);
57	                break;
58	            case 'BUMP_DETECTED':
59	                this.handleBump(probe);
60	                break;
61	            case 'INTERACTING':
62	                this.finalizeInteraction(probe);
63	                break;
64	            default:
65	                // No-op for TRACE and TRANSITING (handled by spatial limb)
66	                break;
67	        }
68	    }
69	
70	    private initiateTrace(probe: ProbeSimulationState) {
71	        // AI Logic: Find an unmapped direction
72	        probe.state = 'TRACE';
73	        console.log(`Probe ${probe.probeId}: Initiating trace...`);
74	    }
75	
76	    private handleBump(probe: ProbeSimulationState) {
77	        if (!probe.lastBumpedObjectId) {
78	            probe.state = 'IDLE';
79	            return;
80	        }
81	
82	        const interaction = getInteractionResult(probe.lastBumpedObjectId);
83	        if (interaction) {
84	            const category = this.vocabLimb.categorize(interaction.action);
85	            console.log(`Probe ${probe.probeId}: Interaction Link found for Object ${probe.lastBumpedObjectId} -> ${interaction.action} [${category}]`);
86	            
87	            if (category === InteractionCategory.MECHANICAL || category === InteractionCategory.TRANSVERSAL) {
88	                 probe.state = 'INTERACTING';
89	            } else {
90	                 probe.state = 'IDLE'; // Not a pathing-related interaction
91	            }
92	        } else {
93	            console.log(`Probe ${probe.probeId}: No Interaction Link for Object ${probe.lastBumpedObjectId}. Turning...`);
94	            probe.state = 'IDLE'; // AI fallback
95	        }
96	    }
97	
98	    private finalizeInteraction(probe: ProbeSimulationState) {
99	        // Logic: Simulate the result of the interaction (e.g. door opening)
100	        // This would be synchronized with the local WorldSubstrate.
101	        probe.state = 'TRACE';
102	        console.log(`Probe ${probe.probeId}: Interaction complete. Path cleared.`);
103	    }
