105	    /**
106	     * External Trigger: Called by the Spatial Limb when a collision occurs.
107	     */
108	    public notifyBump(probeId: number, objectId: number) {
109	        const probe = this.activeProbes.get(probeId);
110	        if (probe) {
111	            probe.state = 'BUMP_DETECTED';
112	            probe.lastBumpedObjectId = objectId;
113	        }
114	    }
