1	import { Coord } from '../../core/models.js';
2	import { createLogger } from '../../utils/logger.js';
3	
4	const logger = createLogger('PlaneTransitionRegistry');
5	
6	export interface PlaneLink {
7	    from: Coord;
8	    to: Coord;
9	    objectId?: number;      // Source object (for display / interaction hooks)
10	    label?: string;         // "Climb-up", "Climb-down", "Ladder", etc.
11	    bidirectional?: boolean; // Default true — also registers the reverse link
12	}
13	
14	/**
15	 * PlaneTransitionRegistry
16	 * Authoritative registry of all tile-to-tile plane transitions.
17	 *
18	 * Links are the RS "staircase/ladder" mechanism:
19	 *   - Plane 0 → Plane 1 (Climb-up)
20	 *   - Plane 1 → Plane 0 (Climb-down)
21	 *   - Arbitrary cross-plane teleports (dungeons, towers, underground passages)
22	 *
23	 * Used by DirectionalPathfinder.getNeighbors() — when standing on a registered
24	 * tile, the destination plane coord is offered as a valid neighbor with
25	 * direction 'up' or 'down'.
26	 */
27	export class PlaneTransitionRegistry {
28	    private static instance: PlaneTransitionRegistry;
29	
30	    // Key format: `${plane}_${x}_${y}` → destination Coord
31	    private links = new Map<string, PlaneLink>();
32	
33	    static getInstance(): PlaneTransitionRegistry {
34	        if (!this.instance) this.instance = new PlaneTransitionRegistry();
35	        return this.instance;
36	    }
37	
38	    private tileKey(c: Coord): string {
39	        return `${c.plane}_${c.x}_${c.y}`;
40	    }
41	
42	    /**
43	     * register — Adds a directional plane link.
44	     */
45	    public register(link: PlaneLink): void {
46	        this.links.set(this.tileKey(link.from), link);
47	
48	        if (link.bidirectional !== false) {
49	            // Register reverse link automatically
50	            const reverse: PlaneLink = {
51	                from: link.to,
52	                to: link.from,
53	                objectId: link.objectId,
54	                label: link.label?.includes('up') ? link.label.replace('up', 'down')
55	                     : link.label?.includes('down') ? link.label.replace('down', 'up')
56	                     : link.label,
57	                bidirectional: false // Prevent infinite recursion
58	            };
59	            this.links.set(this.tileKey(link.to), reverse);
60	        }
61	
62	        logger.debug({
63	            from: link.from,
64	            to: link.to,
65	            label: link.label
66	        }, '[PlaneRegistry] Link registered.');
67	    }
68	
69	    /**
70	     * registerMany — Batch registration.
71	     */
72	    public registerMany(links: PlaneLink[]): void {
73	        links.forEach(l => this.register(l));
74	        logger.info({ count: links.length }, '[PlaneRegistry] Batch registration complete.');
75	    }
76	
77	    /**
78	     * getLink — Returns the plane link from a given tile, or null if none.
79	     */
80	    public getLink(coord: Coord): PlaneLink | null {
81	        return this.links.get(this.tileKey(coord)) ?? null;
82	    }
83	
84	    /**
85	     * hasLink — Quick check for neighbor expansion.
86	     */
87	    public hasLink(coord: Coord): boolean {
88	        return this.links.has(this.tileKey(coord));
89	    }
90	
91	    /**
92	     * hydrateFromObjects — Scans entity list from synthesized JSON for Climb/Ascend/Descend actions.
93	     * Call this after SovereignWorldLoader loads a region.
94	     */
95	    public hydrateFromObjects(entities: Array<{
96	        type: string;
97	        id: number;
98	        x: number;
99	        y: number;
100	        plane: number;
101	        actions?: string[];
102	        metadata?: Record<string, any>;
103	    }>): number {
104	        const CLIMB_ACTIONS = ['climb-up', 'climb-down', 'climb', 'ascend', 'descend',
105	                               'go-up', 'go-down', 'ladder', 'steps', 'trapdoor'];
106	
107	        let registered = 0;
108	
109	        for (const entity of entities) {
110	            if (entity.type !== 'object') continue;
111	
112	            const actions = entity.actions?.map(a => a?.toLowerCase()) ?? [];
113	            const hasClimb = actions.some(a => CLIMB_ACTIONS.some(ca => a?.includes(ca)));
114	            if (!hasClimb) continue;
115	
116	            const from: Coord = { x: entity.x, y: entity.y, plane: entity.plane };
117	
118	            const actionStr = actions.join(' ');
119	            const goingUp = actionStr.includes('up') || actionStr.includes('ascend') ||
120	                            actionStr.includes('go-up');
121	            const planeDelta = goingUp ? 1 : -1;
122	            const toPlane = entity.plane + planeDelta;
123	
124	            // ── Sovereignty Bridge Table (from heatmap.html) ──────────────
125	            // Explicit cross-chunk teleports for deep-world infiltration
126	            let toX = entity.metadata?.destX ?? entity.x;
127	            let toY = entity.metadata?.destY ?? entity.y;
128	            let destPlane = toPlane;
129	            let label = goingUp ? 'climb-up' : 'climb-down';
130	
131	            const name = (entity.metadata?.name || '').toLowerCase();
132	            let isSpecialJump = false;
133	            
134	            if (name === 'trapdoor' || name === 'stairs' || name === 'staircase') {
135	                // Hardcoded jump to Catacombs (cx: 83, cz: 37) based on heatmap.html
136	                toX = (83 * 64) + (entity.x % 64);
137	                toY = (37 * 64) + (entity.y % 64);
138	                destPlane = 0; // Usually B1 loads on plane 0 in separate chunk
139	                label = `Enter Catacombs (B1)`;
140	                isSpecialJump = true;
141	            } else if (name === 'ladder') {
142	                // generic plane offset
143	            }
144	
145	            // Reject invalid bounds ONLY if it's not a special bridge warp
146	            if (!isSpecialJump && (destPlane < 0 || destPlane > 3)) {
147	                continue;
148	            }
149	    
150	
151	            const to: Coord = { x: toX, y: toY, plane: destPlane };
152	
153	            this.register({
154	                from,
155	                to,
156	                objectId: entity.id,
157	                label,
158	                bidirectional: true
159	            });
160	            registered++;
161	        }
162	
163	        if (registered > 0) {
164	            logger.info({ registered }, '[PlaneRegistry] Hydrated from entity list.');
165	        }
166	        return registered;
167	    }
168	
169	    /**
170	     * clear — Wipe registry (for testing / fresh region loads).
171	     */
172	    public clear(): void {
173	        this.links.clear();
174	    }
175	
176	    public get size(): number {
177	        return this.links.size;
178	    }
179	
180	    public healthCheck(): { online: boolean; details: string } {
181	        return {
182	            online: true,
183	            details: `PlaneTransitionRegistry: ${this.links.size} links active.`
184	        };
185	    }
186	}
