18	export type VoidType =
19	    | 'pillar_top'
20	    | 'platform_underside'
21	    | 'waterfall_face'
22	    | 'cliff_edge'
23	    | 'agility_shortcut'
24	    | 'quest_gate'
25	    | 'transport_trigger'
26	    | 'decorative_nocollision'
27	    | 'cantilevered_floor'
