31	    | 'patrol_boundary'
32	    | 'unknown';
33	
34	export type AnnotationConfidence = 'RESOLVED' | 'INFERRED' | 'CONTESTED';
35	export type AnnotationSource = 'HUMAN' | 'LEARNER' | 'ARCHAEOLOGIST';
36	
37	export type GeometryAnnotation = {
38	    id:           string;               // "<x>_<z>_<plane>_<index>"
39	    region:       { x: number; z: number; plane: number };
40	    tile_range:   { x1: number; z1: number; x2: number; z2: number };
41	    void_type:    VoidType;
42	    navigable:    boolean;
43	    signal:       string;               // Human-readable label
44	    confidence:   AnnotationConfidence;
45	    source:       AnnotationSource;
46	    object_ids?:  number[];             // Cache object IDs that match
47	    varbit_ids?:  number[];             // Varbits governing state
48	    notes?:       string;
49	    timestamp:    string;
50	};
51	
52	export type GALIndex = {
53	    version:      number;
54	    updated:      string;
55	    count:        number;
56	    entries:      GALIndexEntry[];
57	};
58	
59	type GALIndexEntry = {
60	    id:           string;
61	    region:       { x: number; z: number; plane: number };
62	    tile_range:   { x1: number; z1: number; x2: number; z2: number };
63	    void_type:    VoidType;
64	    navigable:    boolean;
65	    confidence:   AnnotationConfidence;
66	};
67	
68	// â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
69	// CORE CLASS
70	// â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•â•
71	
72	export class GeometryAnnotationLayer {
73	    private static readonly BASE_DIR = 'D:/sovereign/atlas/annotations';
74	    private static readonly INDEX_PATH = `${GeometryAnnotationLayer.BASE_DIR}/index.gal.json`;
75	
76	    private index: GALIndex;
77	    private cache: Map<string, GeometryAnnotation> = new Map();
78	
79	    constructor() {
80	        this.ensureDir();
81	        this.index = this.loadIndex();
82	    }
83	
84	    private ensureDir() {
85	        if (!existsSync(GeometryAnnotationLayer.BASE_DIR)) {
86	            mkdirSync(GeometryAnnotationLayer.BASE_DIR, { recursive: true });
87	        }
88	    }
89	
90	    private loadIndex(): GALIndex {
91	        if (!existsSync(GeometryAnnotationLayer.INDEX_PATH)) {
92	            return { version: 1, updated: new Date().toISOString(), count: 0, entries: [] };
93	        }
94	        try {
95	            return JSON.parse(readFileSync(GeometryAnnotationLayer.INDEX_PATH, 'utf-8'));
96	        } catch {
97	            return { version: 1, updated: new Date().toISOString(), count: 0, entries: [] };
98	        }
99	    }
100	
101	    private saveIndex() {
102	        this.index.updated = new Date().toISOString();
103	        this.index.count = this.index.entries.length;
104	        writeFileSync(GeometryAnnotationLayer.INDEX_PATH, JSON.stringify(this.index, null, 2));
105	    }
106	
107	    private annotationPath(id: string): string {
108	        return resolve(GeometryAnnotationLayer.BASE_DIR, `${id}.gal.json`);
109	    }
110	
111	    private tileKey(x: number, z: number, plane: number): string {
112	        return `${x}_${z}_${plane}`;
113	    }
114	
115	    /**
116	     * Resolve a single tile coordinate against the annotation layer.
117	     * Returns null if no annotation covers this tile.
118	     */
119	    resolve(x: number, z: number, plane: number): GeometryAnnotation | null {
120	        // Check all index entries for range coverage
121	        for (const entry of this.index.entries) {
122	            if (entry.region.plane !== plane) continue;
123	            const { x1, z1, x2, z2 } = entry.tile_range;
124	            if (x >= x1 && x <= x2 && z >= z1 && z <= z2) {
125	                // Load full annotation if not cached
126	                const cacheKey = entry.id;
127	                if (!this.cache.has(cacheKey)) {
128	                    try {
129	                        const ann = JSON.parse(readFileSync(this.annotationPath(entry.id), 'utf-8'));
130	                        this.cache.set(cacheKey, ann);
131	                    } catch {
132	                        return null;
133	                    }
134	                }
135	                return this.cache.get(cacheKey) ?? null;
136	            }
137	        }
138	        return null;
139	    }
140	
141	    /**
142	     * Check if a tile is navigable according to human annotation.
143	     * Returns null if no annotation exists (caller should use raw bitmask).
144	     */
145	    isNavigable(x: number, z: number, plane: number): boolean | null {
146	        const ann = this.resolve(x, z, plane);
147	        if (!ann || ann.confidence === 'CONTESTED') return null;
148	        return ann.navigable;
149	    }
150	
151	    /**
152	     * Write a new geometry annotation.
153	     */
154	    annotate(ann: Omit<GeometryAnnotation, 'id' | 'timestamp'>): GeometryAnnotation {
155	        const { region, tile_range } = ann;
156	        const existingIndex = this.index.entries.filter(e =>
157	            e.region.x === region.x && e.region.z === region.z && e.region.plane === region.plane &&
158	            e.tile_range.x1 === tile_range.x1 && e.tile_range.z1 === tile_range.z1
159	        ).length;
160	
161	        const id = `${region.x}_${region.z}_${region.plane}_${existingIndex}`;
162	        const full: GeometryAnnotation = { ...ann, id, timestamp: new Date().toISOString() };
163	
164	        // Write annotation file
165	        writeFileSync(this.annotationPath(id), JSON.stringify(full, null, 2));
166	
167	        // Update index
168	        const indexEntry: GALIndexEntry = {
169	            id, region, tile_range,
170	            void_type: ann.void_type,
171	            navigable: ann.navigable,
172	            confidence: ann.confidence,
173	        };
174	
175	        // Remove existing entry with same id if present
176	        this.index.entries = this.index.entries.filter(e => e.id !== id);
177	        this.index.entries.push(indexEntry);
178	        this.saveIndex();
179	
180	        // Invalidate cache
181	        this.cache.delete(id);
182	
183	        console.log(`[GAL] Annotated: ${full.signal} @ (${tile_range.x1}-${tile_range.x2}, ${tile_range.z1}-${tile_range.z2}, plane ${region.plane})`);
184	        return full;
185	    }
186	
187	    /**
188	     * Bulk load all annotations for a region (for renderer overlay).
189	     */
190	    getRegionAnnotations(regionX: number, regionZ: number, plane: number): GeometryAnnotation[] {
191	        const results: GeometryAnnotation[] = [];
192	        for (const entry of this.index.entries) {
193	            if (entry.region.x === regionX && entry.region.z === regionZ && entry.region.plane === plane) {
194	                try {
195	                    const ann = JSON.parse(readFileSync(this.annotationPath(entry.id), 'utf-8'));
196	                    results.push(ann);
197	                } catch {}
198	            }
199	        }
200	        return results;
201	    }
202	
203	    /**
204	     * Get all annotations as a flat array (for renderer full overlay).
205	     */
206	    getAllAnnotations(): GALIndexEntry[] {
207	        return this.index.entries;
208	    }
209	
210	    stats(): { total: number; resolved: number; regions: number } {
211	        const resolved = this.index.entries.filter(e => e.confidence === 'RESOLVED').length;
212	        const regions = new Set(this.index.entries.map(e => `${e.region.x}_${e.region.z}_${e.region.plane}`)).size;
213	        return { total: this.index.entries.length, resolved, regions };
214	    }
215	}
