71	        if (!AbilityDiscoveryLimb.instance) {
72	            AbilityDiscoveryLimb.instance = new AbilityDiscoveryLimb();
73	        }
74	        return AbilityDiscoveryLimb.instance;
75	    }
76	
77	    static resetInstance(): void {
78	        AbilityDiscoveryLimb.instance = undefined;
79	    }
80	
81	    // ─────────────────────────────────────────────────
82	    // Source 1: Action Bar Interface Scanning
83	    // ─────────────────────────────────────────────────
84	
85	    /**
86	     * Scan an action bar interface and discover bound abilities.
87	     * Extracts slot scripts, cross-references AbilityBook.
88	     */
89	    async discoverFromActionBar(interfaceId: number = 1430): Promise<DiscoveredAbility[]> {
90	        // Check cache first
91	        if (this.discoveredCache.has(interfaceId)) {
92	            return this.discoveredCache.get(interfaceId)!;
93	        }
94	
95	        let hud: HUDForensicsLimb;
96	        try {
97	            hud = new HUDForensicsLimb();
98	        } catch {
99	            logger.warn('HUDForensicsLimb unavailable — falling back to AbilityBook discovery');
100	            return this.discoverFromAbilityBook();
101	        }
102	
103	        const forensics = await hud.getInterface(interfaceId);
104	        if (!forensics.ok) {
105	            logger.warn({ interfaceId, error: (forensics as any).error?.message }, 'Action bar interface unavailable');
106	            return this.discoverFromAbilityBook();
107	        }
108	
109	        const abilities: DiscoveredAbility[] = [];
110	        const bindings = this.discoverAbilityBindings(forensics.value);
111	
112	        for (const comp of forensics.value.components) {
113	            const discovered = this.matchComponentToAbility(comp);
114	            if (discovered) {
115	                const slotIndex = bindings.get(comp.componentId);
116	                if (slotIndex !== undefined) {
117	                    discovered.slotIndex = slotIndex;
118	                }
119	                abilities.push(discovered);
120	            }
121	        }
122	
123	        logger.info({ interfaceId, count: abilities.length }, 'Abilities discovered from action bar');
124	        this.discoveredCache.set(interfaceId, abilities);
125	        return abilities;
126	    }
127	
128	    /**
129	     * Map action bar slot components to their logical slot indices.
130	     * Uses script 10896 pattern: [10896, SELF, enumOrComp, varbitId]
131	     */
132	    private discoverAbilityBindings(forensics: any): Map<number, number> {
133	        const bindings = new Map<number, number>();
134	        
135	        for (const comp of forensics.components) {
136	            if (comp.scripts?.load && comp.scripts.load[0] === 10896) {
137	                // Script 10896 pattern: [10896, SELF, enumOrComp, varbitId]
138	                // We use the inferred geometry to determine the 0-13 slot index
139	                const slotIndex = this.inferSlotIndex(comp);
140	                bindings.set(comp.componentId, slotIndex);
141	            }
142	        }
143	        
144	        return bindings;
145	    }
146	
147	    /**
148	     * Heuristic: Infer slot position from layout geometry.
149	     * RS3 action bar: 14 slots, typically arranged in rows.
150	     * Slot 0-6 = first row, 7-13 = second row.
151	     */
152	    private inferSlotIndex(comp: any): number {
153	        const row = Math.floor(comp.baseposy / 50); // heuristic row height
154	        const col = Math.floor(comp.baseposx / 50);   // heuristic col width
155	        return row * 7 + col;
156	    }
157	
158	    // ─────────────────────────────────────────────────
159	    // Source 2: Full AbilityBook Scan
160	    // ─────────────────────────────────────────────────
161	
162	    /**
163	     * Discover all abilities from the AbilityBook for a given style.
164	     * This is the fallback when cache/HUD introspection isn't available.
165	     */
166	    discoverFromAbilityBook(style?: CombatStyle): DiscoveredAbility[] {
167	        const allAbilities = style
168	            ? this.abilityBook.getByStyle(style)
169	            : this.abilityBook.getAll();
170	
171	        return allAbilities
172	            .filter(a => a.damageRange[0] > 0 || a.damageRange[1] > 0 || a.flags.includes('buff'))
173	            .map(a => this.abilityDefToDiscovered(a, 'ability_book'));
174	    }
175	
176	    // ─────────────────────────────────────────────────
177	    // Source 3: Equipment-Inferred Style
178	    // ─────────────────────────────────────────────────
179	
180	    /**
181	     * Infer combat style from equipped weapon type.
182	     * Used when no action bar is bound.
183	     */
184	    inferStyleFromWeapon(weaponName: string): CombatStyle {
185	        const lower = weaponName.toLowerCase();
186	
187	        if (/sword|scimitar|mace|spear|halberd|dagger|claw|whip|godsword|lance/.test(lower)) return 'melee';
188	        if (/bow|crossbow|blowpipe|javelin|dart|thrown|shieldbow|shortbow|longbow/.test(lower)) return 'ranged';
189	        if (/staff|wand|book|orb|battlestaff|seismic|virtus/.test(lower)) return 'magic';
190	        if (/skull|lantern|death guard|omni guard/.test(lower)) return 'necromancy';
191	
192	        return 'melee'; // Default assumption
193	    }
194	
195	    // ─────────────────────────────────────────────────
196	    // Rotation Builder
197	    // ─────────────────────────────────────────────────
198	
199	    /**
200	     * Build an optimal rotation from discovered abilities and current adrenaline.
201	     *
202	     * Strategy:
203	     *   - Basics to build adrenaline when below threshold cost
204	     *   - Thresholds when adrenaline ≥ 50% (1500 on internal scale)
205	     *   - Ultimates when adrenaline = 100% (10000)
206	     *   - Prioritize by damage efficiency (avg damage / effective cooldown)
207	     */
208	    buildOptimalRotation(
209	        availableAbilities: DiscoveredAbility[],
210	        currentAdrenaline: number,
211	        targetStyle?: CombatStyle
212	    ): RotationStep[] {
213	        // Filter by style if specified
214	        const pool = targetStyle
215	            ? availableAbilities.filter(a => a.style === targetStyle || a.style === 'defense')
216	            : availableAbilities;
217	
218	        if (pool.length === 0) return [];
219	
220	        // Separate by tier
221	        const basics = pool.filter(a => a.category === 'basic');
222	        const thresholds = pool.filter(a => a.category === 'enhanced' || a.category === 'special');
223	        const ultimates = pool.filter(a => a.category === 'ultimate');
224	
225	        // Sort each tier by damage efficiency
226	        const byEfficiency = (a: DiscoveredAbility, b: DiscoveredAbility) => {
227	            const avgA = (a.damageRange[0] + a.damageRange[1]) / 2;
228	            const avgB = (b.damageRange[0] + b.damageRange[1]) / 2;
229	            const effA = avgA / Math.max(1, a.cooldownTicks);
230	            const effB = avgB / Math.max(1, b.cooldownTicks);
231	            return effB - effA;
232	        };
233	
234	        basics.sort(byEfficiency);
235	        thresholds.sort(byEfficiency);
236	        ultimates.sort(byEfficiency);
237	
238	        const rotation: RotationStep[] = [];
239	        let simAdrenaline = currentAdrenaline;
240	
241	        // Phase 1: Build to threshold if needed
242	        if (simAdrenaline < 1500 && thresholds.length > 0) {
243	            const ticksNeeded = Math.ceil((1500 - simAdrenaline) / 900); // ~900 gain per basic
244	            for (let i = 0; i < ticksNeeded && basics.length > 0; i++) {
245	                const basic = basics[i % basics.length];
246	                rotation.push({
247	                    ability: basic,
248	                    reason: `Build adrenaline (${simAdrenaline} → ${simAdrenaline + basic.adrenalineGain})`
249	                });
250	                simAdrenaline += basic.adrenalineGain;
251	            }
252	        }
253	
254	        // Phase 2: Fire best threshold
255	        if (simAdrenaline >= 1500 && thresholds.length > 0) {
256	            const best = thresholds[0];
257	            rotation.push({
258	                ability: best,
259	                reason: `Threshold at ${simAdrenaline} adrenaline — ${best.name} (${(best.damageRange[0] + best.damageRange[1]) / 2}% avg)`
260	            });
261	            simAdrenaline -= best.adrenalineCost;
262	        }
263	
264	        // Phase 3: Build to ultimate if available
265	        if (ultimates.length > 0 && simAdrenaline < 10000) {
266	            const remaining = Math.ceil((10000 - simAdrenaline) / 900);
267	            for (let i = 0; i < remaining && basics.length > 0; i++) {
268	                const basic = basics[i % basics.length];
269	                rotation.push({
270	                    ability: basic,
271	                    reason: `Build toward ultimate (${simAdrenaline} → ${simAdrenaline + basic.adrenalineGain})`
272	                });
273	                simAdrenaline += basic.adrenalineGain;
274	            }
275	        }
276	
277	        // Phase 4: Fire ultimate
278	        if (simAdrenaline >= 10000 && ultimates.length > 0) {
279	            const best = ultimates[0];
280	            rotation.push({
281	                ability: best,
282	                reason: `Ultimate at ${simAdrenaline} adrenaline — ${best.name}`
283	            });
284	        }
285	
286	        return rotation;
287	    }
288	
289	    // ─────────────────────────────────────────────────
290	    // Diagnostics
291	    // ─────────────────────────────────────────────────
292	
293	    healthCheck(): { online: boolean; details: string } {
294	        const bookHealth = this.abilityBook.healthCheck();
295	        return {
296	            online: bookHealth.online,
297	            details: `AbilityDiscoveryLimb: ${bookHealth.loaded} abilities in book, ${this.discoveredCache.size} interfaces scanned`
298	        };
299	    }
300	
301	    // ─────────────────────────────────────────────────
302	    // Internal Helpers
303	    // ─────────────────────────────────────────────────
304	
305	    /**
306	     * Match an action bar component to an AbilityBook entry.
307	     * Uses sprite ID, script ID, and right-click options as heuristics.
308	     */
309	    private matchComponentToAbility(comp: InterfaceComponent): DiscoveredAbility | null {
310	        // Strategy 1: Match by right-click option text against ability names
311	        if (comp.rightclickopts && comp.rightclickopts.length > 0) {
312	            for (const opt of comp.rightclickopts) {
313	                if (!opt || opt === 'null') continue;
314	                const ability = this.abilityBook.getByName(opt);
315	                if (ability) {
316	                    const discovered = this.abilityDefToDiscovered(ability, 'action_bar');
317	                    discovered.spriteId = comp.spriteId;
318	                    discovered.scriptId = comp.scripts?.load?.[0] as number | undefined;
319	                    return discovered;
320	                }
321	            }
322	        }
323	
324	        // Strategy 2: Match by script load args (10896 pattern or Varp 5899)
325	        // We look for script arguments that match known action bar varps (e.g. 5899)
326	        if (comp.scripts) {
327	            for (const [trigger, args] of Object.entries(comp.scripts)) {
328	                if (!args || args.length === 0) continue;
329	                
330	                // Generic Option Loader (10896) or direct Varp reference (5899)
331	                if (args[0] === 10896 || args.includes(5899)) {
332	                    // Try to infer which slot this is based on geometry
333	                    const slotIndex = this.inferSlotIndex(comp);
334	                    
335	                    // Cross-reference with AbilityBook based on current varp value
336	                    // Note: This requires active varp state, which is handled in PlayerAgent
337	                    logger.debug({ componentId: comp.componentId, trigger, args, slotIndex }, 'Action bar slot identified via Varp 5899');
338	                    
339	                    // Return a placeholder discovery if we can't match a name yet
340	                    // This allows the agent to know a slot exists even if the ability isn't identified
341	                    return {
342	                        id: `unknown-slot-${slotIndex}`,
343	                        name: `Action Slot ${slotIndex}`,
344	                        category: 'basic',
345	                        adrenalineCost: 0,
346	                        adrenalineGain: 0,
347	                        cooldownTicks: 3,
348	                        damageRange: [0, 0],
349	                        style: 'melee', // placeholder style
350	                        slotIndex,
351	                        spriteId: comp.spriteId,
352	                        scriptId: args[0] === 10896 ? 10896 : 5899,
353	                        source: 'action_bar'
354	                    };
355	                }
356	            }
357	        }
358	
359	        // Strategy 3: Match by high-confidence varbits
360	        if (comp.scripts?.load) {
361	            const varbitId = comp.scripts.load[3];
362	            if (typeof varbitId === 'number' && [49664, 29696, 2816].includes(varbitId)) {
363	                logger.debug({ componentId: comp.componentId, varbitId }, 'Action bar slot matched to high-confidence varbit');
364	            }
365	        }
366	
367	        return null;
368	    }
369	
370	    /**
371	     * Reactive system to sync discovered abilities with current Varp state.
372	     * Maps Varp 5899 values to AbilityBook entries.
373	     */
374	    public syncWithVarpState(varpState: Map<number, number>): DiscoveredAbility[] {
375	        const abilities: DiscoveredAbility[] = [];
376	        
377	        // Varp 5899 is the primary action bar container (March 2026)
378	        const mainBarValue = varpState.get(5899);
379	        if (mainBarValue !== undefined) {
380	            // Logic to decode packed abilities from Varp 5899 goes here
381	            // For now, we use it to validate known slots
382	            logger.debug({ varpValue: mainBarValue }, 'Syncing action bar with Varp 5899 state');
383	        }
384	
385	        return abilities;
386	    }
387	
388	    private abilityDefToDiscovered(a: AbilityDefinition, source: DiscoveredAbility['source']): DiscoveredAbility {
389	        return {
390	            id: a.id,
391	            name: a.name,
392	            category: a.type,
393	            adrenalineCost: a.adrenalineCost,
394	            adrenalineGain: a.adrenalineGain,
395	            cooldownTicks: a.cooldownTicks,
396	            damageRange: a.damageRange,
397	            style: a.style,
398	            source
399	        };
400	    }
401	}
