20	 */
21	export class FragmentOrchestrator {
22	    private spatial: SpatialSovereigntyLimb;
23	    private registry: SpaceRegistry;
24	    private loadedRegions: Set<string> = new Set();
25	    
26	    // Hysteresis: Only check for new regions when moving significant distance
27	    private lastCheckCoord: Coord | null = null;
28	    private readonly checkThreshold = 8; // tiles
