35	    /**
36	     * update - Heartbeat for regional loading.
37	     */
38	    public async update(avatar: Coord): Promise<void> {
39	        if (this.shouldSkipCheck(avatar)) return;
40	
41	        const centerX = avatar.x >> 6;
42	        const centerY = avatar.y >> 6;
43	
44	        const loadPromises: Promise<any>[] = [];
45	
46	        // Scan 5x5 grid (radius 2) for missing logic fragments
47	        for (let mx = centerX - 2; mx <= centerX + 2; mx++) {
48	            for (let my = centerY - 2; my <= centerY + 2; my++) {
49	                const anchor = `m_${mx}_${my}`;
50	                
51	                if (!this.loadedRegions.has(anchor)) {
52	                    loadPromises.push(this.attemptRegionalLoad(anchor, mx, my));
53	                }
54	            }
55	        }
56	
57	        if (loadPromises.length > 0) {
58	            logger.info({ count: loadPromises.length }, 'Triggering proactive regional logic loads.');
59	            await Promise.all(loadPromises);
60	        }
61	
62	        // 4. Update Neurological Vibe based on current anchor
63	        const currentAnchor = `m_${centerX}_${centerY}`;
64	        const registry = RegistryB.getInstance();
65	        const logic = registry.getFragmentLogic(currentAnchor);
66	        if (logic) {
67	            VibeMapper.getInstance().updateVibe(logic);
68	        }
69	
70	        this.lastCheckCoord = { ...avatar };
71	    }
