75	     */
76	    private async attemptRegionalLoad(anchor: string, mx: number, my: number): Promise<void> {
77	        // Priority 1: Sovereign Path Authority resolution (D:\sovereign\atlas\spatial\)
78	        const logicPath = resolveLogicFragment(anchor);
79	        
80	        const originLabel = logicPath?.includes('D:\\sovereign') ? '[D-SOVEREIGN]' : '[C-LOCAL]';
81	        if (logicPath) {
82	            logger.info(`${originLabel} Fragment resolved: ${logicPath}`);
83	        } else {
84	            logger.warn({ anchor }, 'No logic fragment found in Sovereign Atlas (D:). Using blank stub.');
85	        }
86	
87	        let success = { ok: false };
88	        if (logicPath) {
89	            success = await this.spatial.loadLogic(anchor);
90	        } else {
91	            // Coordinate fallback: Even if no JSON exists, RegistryB will seed a baseline stub
92	            // if it stays within the mapped coordinate range.
93	            success = await this.spatial.loadLogic(anchor);
94	        }
95	
96	        if (success.ok) {
97	            logger.info({ anchor }, 'Proactive Space Logic applied.');
