108	        if (!this.subscribers.has(nodeId)) {
109	            this.subscribers.set(nodeId, []);
110	        }
111	        this.subscribers.get(nodeId)!.push(callback);
112	    }
113	
114	    /**
115	     * Connects to the Multiplayer Globe substrate.
116	     * Stores the connection promise so healthCheck() can await it.
117	     */
118	    public async connect(): Promise<Result<boolean>> {
119	        if (!this.enabled) {
120	            return ok(false);
121	        }
122	
123	        this.connectPromise = new Promise((resolve) => {
124	            try {
125	                this.ws = new WebSocket(this.endpoint);
126	
127	                let pingInterval: NodeJS.Timeout;
128	
129	                this.ws.on('open', () => {
130	                    logger.info({ endpoint: this.endpoint }, 'Connected to Multiplayer Globe Substrate');
131	                    
132	                    // Phase 22: Keep-alive interval to prevent Cloudflare 100s idle timeout
133	                    pingInterval = setInterval(() => {
134	                        if (this.ws?.readyState === WebSocket.OPEN) {
135	                            this.ws.ping();
136	                            // Also send an application-level ping just in case
137	                            this.ws.send(JSON.stringify({ type: 'ping', timestamp: Date.now() }));
138	                        }
139	                    }, 30000);
140	
141	                    resolve(ok(true));
142	                });
143	
144	                this.ws.on('close', () => {
145	                    if (pingInterval) clearInterval(pingInterval);
146	                    logger.warn('Globe connection closed. Attempting reconnect in 5 seconds...');
147	                    setTimeout(() => {
148	                        if (this.enabled) this.connect();
149	                    }, 5000);
150	                });
151	
152	                this.ws.on('message', (data: string) => {
153	                    try {
154	                        const msg = JSON.parse(data);
155	                        if (msg.type === 'state-sync') {
156	                            this.state = msg.state;
157	                            logger.debug('State synchronized from Globe');
158	
159	                            // Notify subscribers of the new state
160	                            for (const [nodeId, nodeData] of Object.entries(this.state.nodes)) {
161	                                const callbacks = this.subscribers.get(nodeId);
162	                                if (callbacks) {
163	                                    callbacks.forEach(cb => {
164	                                        try { cb(nodeData); } catch (e) { logger.error({ err: e }, 'Globe subscriber error'); }
165	                                    });
166	                                }
167	                            }
168	                        } else if (msg.type === 'human_intervention' || msg.type === 'volitional_request') {
169	                            logger.info({ payload: msg }, '🧠 Received volition/intervention from Globe, routing to SwitchboardLimb admin queue');
170	                            // Dynamically import to avoid circular dependencies if needed
171	                            import('../../monitor/SwitchboardLimb.js').then(({ SwitchboardLimb }) => {
172	                                SwitchboardLimb.getInstance().pushAdminCommand({
173	                                    type: msg.action || msg.intent || 'human_intervention',
174	                                    metadata: { ...msg, timestamp: Date.now() }
175	                                });
176	                            });
177	                        }
178	                    } catch (err) {
179	                        logger.warn({ err }, 'Failed to parse Globe message');
180	                    }
181	                });
182	
183	                this.ws.on('error', (err: any) => {
184	                    logger.error({ err }, 'Globe connection error');
185	                    resolve({ ok: false, error: err });
186	                });
187	
188	            } catch (err) {
189	                resolve({ ok: false, error: err as Error });
190	            }
191	        });
192	        return this.connectPromise;
193	    }
194	
195	    /**
196	     * Push a node's state to the global substrate.
197	     */
198	    public async pushNodeState(nodeId: string, data: any): Promise<Result<boolean>> {
199	        // Enforce active visual state for POG2 telemetry nodes if properties are missing
200	        if (data && typeof data === 'object') {
201	            if (data.score === undefined) {
202	                if (nodeId === 'routing_event') {
203	                    const complexityScores: Record<string, number> = { low: 0.2, medium: 0.5, high: 0.8, extreme: 1.0 };
204	                    data.score = complexityScores[data.classifiedComplexity?.toLowerCase()] ?? 0.5;
205	                } else if (nodeId === 'thinking_event') {
206	                    data.score = data.curiosity !== undefined ? data.curiosity : 0.95;
207	                } else {
208	                    data.score = 1.00;
209	                }
210	            }
211	            if (data.status === undefined) {
212	                data.status = 'active';
213	            }
214	            if (data.lastActivity === undefined) {
215	                if (nodeId === 'routing_event' && data.chosenModel) {
216	                    data.lastActivity = `Route: ${data.chosenModel} (${data.classifiedComplexity || 'low'})`;
217	                } else if (nodeId === 'thinking_event' && data.reflection) {
218	                    data.lastActivity = data.reflection.length > 35 ? data.reflection.substring(0, 35) + '...' : data.reflection;
219	                } else if (nodeId === 'fprag_event') {
220	                    data.lastActivity = data.directive 
221	                        ? (data.directive.length > 30 ? `Directive: ${data.directive.substring(0, 30)}...` : `Directive: ${data.directive}`)
222	                        : (data.task?.length > 30 ? `Audit: ${data.task.substring(0, 30)}...` : `Audit: ${data.task || 'Active'}`);
223	                } else {
224	                    data.lastActivity = 'monitoring';
225	                }
226	            }
227	        }
228	
229	        this.state.nodes[nodeId] = data;
230	        this.state.lastSync = Date.now();
231	
232	        if (this.ws?.readyState === WebSocket.OPEN) {
233	            this.ws.send(JSON.stringify({
234	                type: 'update-node',
235	                nodeId,
236	                data,
237	                timestamp: this.state.lastSync
238	            }));
239	            return ok(true);
240	        }
241	
242	        return { ok: false, error: new Error('Globe substrate offline') };
243	    }
244	
245	    /**
246	     * Push a batch of spatial perception entities to the global substrate.
247	     */
248	    public pushBatchPerception(entities: any[]): void {
249	        if (this.ws?.readyState === WebSocket.OPEN && entities.length > 0) {
250	            this.ws.send(JSON.stringify({
251	                type: 'batch_perception',
252	                payload: { entities }
253	            }));
254	        }
255	    }
256	
257	    /**
258	     * Query state from the substrate.
259	     */
260	    public getNodeState(nodeId: string): any {
261	        return this.state.nodes[nodeId];
262	    }
263	
264	    /**
265	     * Sovereign FinOps: Push quota state to durable substrate.
266	     */
267	    public async syncQuotaState(qt: QuotaTracker): Promise<void> {
268	        await this.pushNodeState('quota', qt.serialize());
269	    }
270	
271	    /**
272	     * Sovereign FinOps: Load persisted quota state.
273	     */
274	    public loadQuotaState(): QuotaState | null {
275	        return this.getNodeState('quota') as QuotaState | null;
276	    }
277	
278	    public async healthCheck(): Promise<{ online: boolean; details: string; retryable?: boolean }> {
279	        // If a connection is pending, wait briefly for it to resolve
280	        if (this.connectPromise && (!this.ws || this.ws.readyState !== WebSocket.OPEN)) {
281	            try {
282	                await Promise.race([
283	                    this.connectPromise,
284	                    new Promise(resolve => setTimeout(resolve, 3000))
285	                ]);
286	            } catch {
287	                // Connection failed â€” fall through to status check
288	            }
289	        }
290	
291	        const isOnline = this.ws?.readyState === WebSocket.OPEN;
292	        const isConnecting = this.ws?.readyState === WebSocket.CONNECTING;
293	
294	        return {
295	            online: isOnline,
296	            retryable: isConnecting,
297	            details: isOnline
298	                ? `Globe Substrate Active: ${Object.keys(this.state.nodes).length} nodes synced.`
299	                : (isConnecting ? 'Globe Substrate Offline: Waiting for connection.' : 'Globe Substrate Offline: Connection failed or closed.')
300	        };
301	    }
302	}
