33	/**
34	 * HUDOverlayLimb
35	 * 
36	 * Responsible for rendering the RS3 interface components as an HTML overlay.
37	 * Uses CSS logic derived from renderrsinterface.ts to handle responsive positioning (AspectType).
38	 */
39	export class HUDOverlayLimb {
40	    private static instance: HUDOverlayLimb;
41	    private container: HTMLElement | null = null;
42	    private componentMap = new Map<string, HTMLElement>(); // key: `${interfaceId}:${componentId}`
43	    private targetSelector: string;
44	
45	    constructor(targetSelector: string = '#sovereign-hud-overlay') {
46	        this.targetSelector = targetSelector;
47	    }
48	
49	    public static getInstance(): HUDOverlayLimb {
50	        if (!HUDOverlayLimb.instance) {
51	            HUDOverlayLimb.instance = new HUDOverlayLimb();
52	        }
53	        return HUDOverlayLimb.instance;
54	    }
55	
56	    initialize(): void {
57	        if (typeof document === 'undefined') {
58	            logger.warn('No document available in this context (Node.js?). HUDOverlayLimb requires a DOM to render.');
59	            return;
60	        }
61	
62	        this.container = document.querySelector(this.targetSelector);
63	        if (!this.container) {
64	            this.container = document.createElement('div');
65	            this.container.id = this.targetSelector.replace('#', '');
66	            this.container.style.cssText = `
67	                position: fixed;
68	                top: 0; left: 0;
69	                width: 100vw; height: 100vh;
70	                pointer-events: none;
71	                z-index: 10000;
72	                overflow: hidden;
73	            `;
74	            document.body.appendChild(this.container);
75	        }
76	        logger.info('HUDOverlayLimb attached to DOM');
77	    }
78	
79	    render(rendered: RenderedInterface): void {
80	        if (typeof document === 'undefined') return;
81	        if (!this.container) {
82	            this.initialize();
83	        }
84	        if (!this.container) return;
85	
86	        this.clearInterface(rendered.interfaceId);
87	
88	        for (const comp of rendered.components) {
89	            if (!comp.visible) continue;
90	
91	            const el = this.createElement(comp);
92	            this.container.appendChild(el);
93	            this.componentMap.set(`${comp.interfaceId}:${comp.id}`, el);
94	        }
95	
96	        logger.debug({ interfaceId: rendered.interfaceId, componentCount: rendered.components.length }, 'Rendered interface');
97	    }
98	
99	    private createElement(comp: RenderedComponent): HTMLElement {
100	        const el = document.createElement('div');
101	        el.id = `if-${comp.interfaceId}-comp-${comp.id}`;
102	        el.className = 'rs-component';
103	        
104	        // Base styles
105	        el.style.position = 'absolute';
106	        el.style.pointerEvents = 'auto';
107	        el.style.boxSizing = 'border-box';
108	
109	        // Apply pre-computed style if available
110	        if (comp.style) {
111	            el.style.cssText += comp.style;
112	        } else {
113	            // Fallback to absolute positioning
114	            el.style.left = `${comp.x}px`;
115	            el.style.top = `${comp.y}px`;
116	            el.style.width = `${comp.width}px`;
117	            el.style.height = `${comp.height}px`;
118	        }
119	
120	        // Content injection
121	        if (comp.type === 'TEXT' && comp.content?.text) {
122	            el.textContent = comp.content.text;
123	            el.style.display = 'flex';
124	            el.style.color = comp.content.color || '#ffffff';
125	        }
126	
127	        // Event binding
128	        if (comp.scripts?.onClick) {
129	            el.onclick = () => {
130	                logger.debug({ scriptId: comp.scripts!.onClick }, 'Component clicked');
131	                // TODO: Dispatch to InterfaceRuntimeLimb for CS2 execution
132	            };
133	        }
134	
135	        return el;
136	    }
137	
138	    clearInterface(interfaceId: number): void {
139	        for (const [key, el] of this.componentMap) {
140	            if (key.startsWith(`${interfaceId}:`)) {
141	                el.remove();
142	                this.componentMap.delete(key);
143	            }
144	        }
145	    }
146	
147	    destroy(): void {
148	        this.container?.remove();
149	        this.componentMap.clear();
150	        this.container = null;
151	    }
152	}
