90	export type AgentEvent =
91	    | { type: 'SLOT_DISCOVERED'; interfaceId: number; componentId: number; slot: RenderedComponent }
92	    | { type: 'INTERFACE_READY'; interfaceId: number; rendered: RenderedInterface }
93	    | { type: 'CHILD_REF_FOUND'; parentInterface: number; childInterface: number; childComponent: number };
