97	export class InterfaceRuntimeLimb {
98	    private interpreter: any = null;
99	    private nativeRegistry: SovereignCs2NativeRegistry;
100	    private overlay: HUDOverlayLimb;
101	    private calli: any = null;
102	    private source: any = null;
103	    private agentListeners: AgentEventHandler[] = [];
104	    private bootstrappedInterfaces = new Set<number>();
105	    
106	    constructor() {
107	        this.nativeRegistry = SovereignCs2NativeRegistry.getInstance();
108	        this.overlay = new HUDOverlayLimb();
109	    }
110	    
111	    async initialize(): Promise<void> {
112	        this.overlay.initialize();
113	        logger.info('Initializing InterfaceRuntimeLimb...');
114	        let GameCacheLoader: any;
115	        let prepareClientScript: any;
116	        let ClientScriptInterpreter: any;
117	
118	        try {
119	            const alt1 = require('alt1cache');
120	            GameCacheLoader = alt1.GameCacheLoader;
121	            prepareClientScript = alt1.prepareClientScript;
122	            ClientScriptInterpreter = alt1.ClientScriptInterpreter;
123	        } catch (e) {
124	            const inspectorPath = 'D:/rsmv_inspector';
125	            const sqlitePath = path.join(inspectorPath, 'src', 'cache', 'sqlite.ts');
126	            const indexTsPath = path.join(inspectorPath, 'src', 'clientscript', 'index.ts');
127	            const interpreterPath = path.join(inspectorPath, 'src', 'clientscript', 'interpreter.ts');
128	            
129	            ({ GameCacheLoader } = require(sqlitePath));
130	            ({ prepareClientScript } = require(indexTsPath));
131	            ({ ClientScriptInterpreter } = require(interpreterPath));
132	        }
133	
134	        const { getrsmvCachePath } = require('../../utils/SovereignPathResolver.js');
135	        const cachePath = getrsmvCachePath();
136	        this.source = new GameCacheLoader(cachePath);
137	        
138	        // Wait for calibration to complete and load
139	        this.calli = await prepareClientScript(this.source);
140	        
141	        // We defer interpreter instantiation per-script because the interpreter is stateful,
142	        // but we cache the ClientScriptInterpreter constructor.
143	        this.interpreter = ClientScriptInterpreter;
144	        logger.info('InterfaceRuntimeLimb initialized successfully.');
145	    }
146	    
147	    /** Register an agent listener for the forensics feedback loop */
148	    onAgentEvent(handler: AgentEventHandler): void {
149	        this.agentListeners.push(handler);
150	    }
151	
152	    private emit(event: AgentEvent): void {
153	        for (const handler of this.agentListeners) handler(event);
154	    }
155	
156	    /**
157	     * Decode a packed component reference (RS3 format: high 16 bits = interfaceId, low 16 = componentId)
158	     * e.g. 120651776 = 0x7300100 → { interfaceId: 1840, componentId: 256 }
159	     */
160	    private decodePackedRef(packed: number): { interfaceId: number; componentId: number } | null {
161	        if (typeof packed !== 'number' || packed <= 0 || packed > 0x7FFFFFFF) return null;
162	        const interfaceId = (packed >>> 16) & 0xFFFF;
163	        const componentId = packed & 0xFFFF;
164	        // Valid RS3 interface range
165	        if (interfaceId < 1 || interfaceId > 3500) return null;
166	        return { interfaceId, componentId };
167	    }
168	
169	    /**
170	     * Scan script args for packed component refs and recursively bootstrap those interfaces.
171	     * This is the forensics → agent feedback loop.
172	     */
173	    private async followComponentRefs(
174	        args: (number | string)[],
175	        parentInterfaceId: number
176	    ): Promise<void> {
177	        const childInterfaces = new Set<number>();
178	
179	        for (const arg of args) {
180	            if (typeof arg !== 'number') continue;
181	            const ref = this.decodePackedRef(arg);
182	            if (!ref) continue;
183	            if (ref.interfaceId === parentInterfaceId) continue; // Skip self-refs
184	
185	            this.emit({
186	                type: 'CHILD_REF_FOUND',
187	                parentInterface: parentInterfaceId,
188	                childInterface: ref.interfaceId,
189	                childComponent: ref.componentId
190	            });
191	
192	            childInterfaces.add(ref.interfaceId);
193	        }
194	
195	        // Recursively bootstrap each discovered child interface (once only)
196	        for (const childId of childInterfaces) {
197	            if (!this.bootstrappedInterfaces.has(childId)) {
198	                logger.info(`Following component ref: interface ${parentInterfaceId} → ${childId}`);
199	                try {
200	                    await this.bootstrapInterface(childId);
201	                } catch (e: any) {
202	                    logger.warn(`Failed to bootstrap child interface ${childId}: ${e.message}`);
203	                }
204	            }
205	        }
206	    }
207	
208	    async bootstrapInterface(interfaceId: number): Promise<RenderedInterface> {
209	        if (this.bootstrappedInterfaces.has(interfaceId)) {
210	            logger.debug(`Interface ${interfaceId} already bootstrapped, skipping.`);
211	            return { interfaceId, components: [] };
212	        }
213	        this.bootstrappedInterfaces.add(interfaceId);
214	
215	        // 1. Get deep-decoded components
216	        const hud = new HUDForensicsLimb();
217	        const forensics = await hud.getInterface(interfaceId);
218	        if (!forensics.ok) throw forensics.error;
219	        
220	        logger.info(`Bootstrapping interface ${interfaceId} with ${forensics.value.components.length} components.`);
221	        
222	        // 2. Execute load scripts + follow packed component refs (the feedback loop)
223	        for (const comp of forensics.value.components) {
224	            if (comp.scripts?.load && comp.scripts.load.length > 0) {
225	                const [scriptId, ...args] = comp.scripts.load;
226	                // Follow any packed child interface refs embedded in the script args
227	                await this.followComponentRefs(args as number[], interfaceId);
228	                await this.executeScript(scriptId as number, args, interfaceId, comp.componentId);
229	            }
230	        }
231	        
232	        // 3. Resolve layout
233	        const rendered = this.resolveLayout(forensics.value.components, interfaceId);
234	        
235	        // 4. Emit agent event: interface is ready for consumption
236	        this.emit({ type: 'INTERFACE_READY', interfaceId, rendered });
237	
238	        // 5. Notify agent of each interactive slot discovered
239	        for (const slot of rendered.components) {
240	            if (slot.scripts?.onClick !== undefined) {
241	                this.emit({ type: 'SLOT_DISCOVERED', interfaceId, componentId: slot.id, slot });
242	            }
243	        }
244	
245	        // 6. Hand off to HUD renderer
246	        this.overlay.render(rendered);
247	        
248	        return rendered;
249	    }
250	    
251	    private async executeScript(
252	        scriptId: number, 
253	        args: (number | string)[], 
254	        interfaceId: number, 
255	        componentId: number
256	    ): Promise<void> {
257	        if (!this.interpreter) throw new Error('Interpreter not initialized');
258	        
259	        logger.debug(`Executing script ${scriptId} on component ${interfaceId}:${componentId} with args: ${JSON.stringify(args)}`);
260	
261	        // Create a mock UiRenderContext that provides the CS2ApiAdapter
262	        const uictx = {
263	            comps: {
264	                get: (compId: number) => {
265	                    return { api: new CS2ApiAdapter(interfaceId, compId, this.nativeRegistry) };
266	                }
267	            },
268	            touchedComps: new Set(),
269	            runOnloadScripts: true
270	        };
271	
272	        // Instantiate interpreter with our mocked uictx
273	        const inter = new this.interpreter(this.calli, uictx);
274	        
275	        inter.reset();
276	        inter.pushlist(args);
277	        inter.activecompid = componentId;
278	        await inter.callscriptid(scriptId);
279	        await inter.runToEnd();
280	    }
281	    
282	    private resolveLayout(components: any[], interfaceId: number): RenderedInterface {
283	        // Option B: HTML overlay CSS resolution
284	        const rendered: RenderedComponent[] = components.map(comp => {
285	            let type: 'CONTAINER' | 'TEXT' | 'SPRITE' | 'MODEL' | 'FIGURE' = 'CONTAINER';
286	            const content: any = {};
287	            
288	            if (comp.type === 4) {
289	                type = 'TEXT';
290	                content.text = comp.textdata?.text || '';
291	                content.color = comp.textdata?.color ? '#' + (comp.textdata.color & 0xffffff).toString(16).padStart(6, '0') : '#ffffff';
292	                content.font = comp.textdata?.fontid?.toString();
293	            } else if (comp.type === 5) {
294	                type = 'SPRITE';
295	                content.spriteId = comp.spritedata?.spriteid;
296	            } else if (comp.type === 6) {
297	                type = 'MODEL';
298	                content.modelId = comp.modeldata?.modelid;
299	            } else if (comp.type === 3) {
300	                type = 'FIGURE';
301	                content.color = comp.figuredata?.color ? '#' + (comp.figuredata.color & 0xffffff).toString(16).padStart(6, '0') : '#000000';
302	            }
303	
304	            return {
305	                id: comp.componentId,
306	                interfaceId,
307	                x: comp.baseposx,
308	                y: comp.baseposy,
309	                width: comp.basewidth,
310	                height: comp.baseheight,
311	                visible: !comp.hidden,
312	                type,
313	                content,
314	                scripts: {
315	                    onClick: comp.scripts?.op ? comp.scripts.op[0] : undefined,
316	                    onHover: comp.scripts?.mousehover ? comp.scripts.mousehover[0] : undefined
317	                },
318	                style: this.cssPosition(comp) + this.cssSize(comp)
319	            };
320	        });
321	        
322	        return { interfaceId, components: rendered };
323	    }
324	    
325	    private cssPosition(data: any) {
326	        let css = "";
327	        const defaulttranslate = "0px";
328	        let translatex = defaulttranslate;
329	        let translatey = defaulttranslate;
330	
331	        if (data.aspectxtype == 0) { css += `left:${data.baseposx}px;`; }
332	        else if (data.aspectxtype == 1) { css += `left:50%;margin-left:${data.baseposx}px;`; translatex = "-50%"; }
333	        else if (data.aspectxtype == 2) { css += `right:${data.baseposx}px;`; }
334	        else if (data.aspectxtype == 3) { css += `left:${data.baseposx * 100 / (1 << 14)}%;`; }
335	        else if (data.aspectxtype == 4) { css += `left:${50 + data.baseposx * 100 / (1 << 14)}%;`; translatex = "-50%"; }
336	        else if (data.aspectxtype == 5) { css += `right:${data.baseposx * 100 / (1 << 14)}%;`; }
337	
338	        if (data.aspectytype == 0) { css += `top:${data.baseposy}px;`; }
339	        else if (data.aspectytype == 1) { css += `top:50%;margin-top:${data.baseposy}px;`; translatey = "-50%"; }
340	        else if (data.aspectytype == 2) { css += `bottom:${data.baseposy}px;`; }
341	        else if (data.aspectytype == 3) { css += `top:${data.baseposy * 100 / (1 << 14)}%;`; }
342	        else if (data.aspectytype == 4) { css += `top:${50 + data.baseposy * 100 / (1 << 14)}%;`; translatey = "-50%"; }
343	        else if (data.aspectytype == 5) { css += `bottom:${data.baseposy * 100 / (1 << 14)}%;`; }
344	
345	        if (translatex != defaulttranslate || translatey != defaulttranslate) {
346	            css += `translate:${translatex} ${translatey};`;
347	        }
348	        return css;
349	    }
350	
351	    private cssSize(data: any) {
352	        let css = "";
353	        if (data.aspectwidthtype == 0) { css += `width:${data.basewidth}px;`; }
354	        else if (data.aspectwidthtype == 1) { css += `width:calc(100% - ${data.basewidth}px);`; }
355	        else if (data.aspectwidthtype == 2) { css += `width:${data.basewidth * 100 / (1 << 14)}%;`; }
356	
357	        if (data.aspectheighttype == 0) { css += `height:${data.baseheight}px;`; }
358	        else if (data.aspectheighttype == 1) { css += `height:calc(100% - ${data.baseheight}px);`; }
359	        else if (data.aspectheighttype == 2) { css += `height:${data.baseheight * 100 / (1 << 14)}%;`; }
360	
361	        return css;
362	    }
363	}
