19	    /**
20	     * wear - Attaches an item from inventory to its designated equipment slot.
21	     */
22	    public wear(avatar: SovereignAvatar, slot: number): Result<boolean> {
23	        const item = avatar.inventory[slot];
24	        if (!item) return err(new Error('No item in slot.'));
25	
26	        // Retrieve authentic, cache-backed equipment slot from the forensic registry
27	        const rawSlot = CacheForensicsLimb.getInstance().findItemSlot(item.id);
28	        let targetSlot: EquipmentSlot = item.metadata?.equipSlot || EquipmentSlot.WEAPON;
