93	                level: 25, 
94	                runes: [
95	                    { id: 563, count: 1 }, // Law Rune
96	                    { id: 554, count: 1 }, // Fire Rune
97	                    { id: 556, count: 3 }  // Air Rune
98	                ]
99	            },
100	            'LUMBRIDGE': {
101	                level: 31,
102	                runes: [
