58	
59	            for (const archiveInfo of index) {
60	                if (!archiveInfo) continue;
61	                const archive = await this.cache.getArchiveById(MAJOR_MATERIALS, archiveInfo.minor);
62	                for (const f of archive) {
63	                    try {
64	                        const matId = archiveInfo.minor | f.fileid; // depending on RS3 packaging, but storing flat ID
65	                        const decoded = parse.materials.read(f.buffer, this.cache);
66	                        decoded.id = matId;
67	                        materials[matId] = decoded;
68	                        count++;
69	                    } catch (e) {
70	                        logger.warn({ archive: archiveInfo.minor, file: f.fileid, error: (e as Error).message }, 'Failed to decode material substrate entry. Skipping corrupt file.');
71	                    }
72	                }
73	            }
74	
75	            const payload = {
76	                metadata: {
77	                    extractedAt: new Date().toISOString(),
78	                    materialCount: count
79	                },
80	                materials
81	            };
82	
83	            const outPath = path.join(this.outDir, 'materials.json');
84	            fs.writeFileSync(outPath, JSON.stringify(payload, null, 2));
85	
86	            logger.info({ path: outPath, materials: count }, 'Material Database successfully anchored.');
87	            return ok(true);
88	        } catch (error) {
89	            logger.error({ error: (error as Error).message }, 'Material Extraction Failed.');
90	            return err(error as Error);
91	        }
92	    }
