1	import { createLogger } from '../../utils/logger.js';
2	
3	const logger = createLogger('SovereignCs2NativeRegistry');
4	
5	export type CS2OpHandler = (interfaceId: number, componentId: number, ...args: any[]) => void | any;
6	
7	export class SovereignCs2NativeRegistry {
8	    private static instance: SovereignCs2NativeRegistry;
9	    private handlers: Map<string, CS2OpHandler> = new Map();
10	
11	    public constructor() {
12	        this.initializeScaffold();
13	    }
14	
15	    public static getInstance(): SovereignCs2NativeRegistry {
16	        if (!SovereignCs2NativeRegistry.instance) {
17	            SovereignCs2NativeRegistry.instance = new SovereignCs2NativeRegistry();
18	        }
19	        return SovereignCs2NativeRegistry.instance;
20	    }
21	
22	    private initializeScaffold() {
23	        // --- Structural Mutators ---
24	        this.register('IF_SETTEXT', (interfaceId: number, componentId: number, text: string) => {
25	            logger.info(`[IF_SETTEXT] Targeting ${interfaceId}:${componentId} -> "${text}"`);
26	        });
27	
28	        this.register('IF_SETHIDE', (interfaceId: number, componentId: number, hidden: number) => {
29	            logger.info(`[IF_SETHIDE] Targeting ${interfaceId}:${componentId} -> ${hidden ? 'HIDDEN' : 'VISIBLE'}`);
30	        });
31	
32	        this.register('IF_SETPOSITION', (interfaceId: number, componentId: number, x: number, y: number, modeX: number, modeY: number) => {
33	            logger.info(`[IF_SETPOSITION] Targeting ${interfaceId}:${componentId} -> (${x}, ${y}) Modes: ${modeX}, ${modeY}`);
34	        });
35	
36	        this.register('IF_SETSIZE', (interfaceId: number, componentId: number, w: number, h: number, modeW: number, modeH: number) => {
37	            logger.info(`[IF_SETSIZE] Targeting ${interfaceId}:${componentId} -> ${w}x${h} Modes: ${modeW}, ${modeH}`);
38	        });
39	
40	        // --- Behavioral Hooks ---
41	        this.register('CC_SETONCLICK', (interfaceId: number, componentId: number, scriptArgs: any[]) => {
42	            logger.info({ scriptArgs }, `[CC_SETONCLICK] Binding Script array to ${interfaceId}:${componentId}`);
43	        });
44	
45	        // --- Common Stubs ---
46	        const commonOps = [
47	            'IF_SETSCROLLPOS', 'IF_SETCOLOUR', 'IF_SETFILL', 'IF_SETTRANS', 'IF_SETGRAPHIC', 'IF_SETMODEL',
48	            'CC_SETTEXT', 'CC_SETTEXTFONT', 'CC_SETTEXTALIGN', 'CC_SETTEXTSHADOW',
49	            'IF_SETTEXTFONT', 'IF_SETTEXTALIGN', 'IF_SETTEXTSHADOW', 'IF_SETNOCLICKTHROUGH'
50	        ];
51	
52	        commonOps.forEach(op => {
53	            this.register(op, (iface: number, comp: number, ...args: any[]) => {
54	                logger.debug({ args }, `[${op}] Stub invoked on ${iface}:${comp}`);
55	            });
56	        });
57	    }
58	
59	    public register(opcodeName: string, handler: CS2OpHandler) {
60	        this.handlers.set(opcodeName, handler);
61	    }
62	
63	    public execute(opcodeName: string, interfaceId: number, componentId: number, ...args: any[]): any {
64	        const handler = this.handlers.get(opcodeName);
65	        if (handler) {
66	            return handler(interfaceId, componentId, ...args);
67	        } else {
68	            logger.warn({ args }, `[UNMAPPED OP] ${opcodeName} called on ${interfaceId}:${componentId}`);
69	        }
70	    }
71	
72	    /**
73	     * Contextual proxy for the interpreter adapter.
74	     */
75	    public withContext(interfaceId: number, componentId: number): any {
76	        return new Proxy(this, {
77	            get: (target, prop: string) => {
78	                if (target.handlers.has(prop)) {
79	                    return (...args: any[]) => target.execute(prop, interfaceId, componentId, ...args);
80	                }
81	                return (target as any)[prop];
82	            }
83	        });
84	    }
85	}
