25	     * Extracts DB Tables and DB Rows into a cohesive relational JSON.
26	     */
27	    public async extractSystemTaxonomy(): Promise<Result<boolean>> {
28	        try {
29	            logger.info('Commencing System Taxonomy Extraction (Bridge-mediated)...');
30	
31	            const tablesResult = await rsmvBridge.getDBTables();
32	            if (!tablesResult.ok) return err(new Error(`Failed to extract DBTables: ${tablesResult.error}`));
33	
34	            const rowsResult = await rsmvBridge.getDBRows();
35	            if (!rowsResult.ok) return err(new Error(`Failed to extract DBRows: ${rowsResult.error}`));
36	
37	            const varpsResult = await rsmvBridge.getVarps();
