1	import { readFileSync, writeFileSync, mkdirSync, existsSync, readdirSync } from 'fs';
2	import { resolve, join } from 'path';
3	import { getSovereignRoot } from '../../utils/SovereignPathResolver.js';
4	
5	export interface ArchaeologyHit {
6	    keyword: string;
7	    id: string | number;
8	    name: string;
9	    models?: any;
10	    op?: string[];
11	    params?: any;
12	    extra?: any;
13	    boundSize?: number;
14	    walkRange?: number;
15	    respawnDirection?: number;
16	    movementType?: number;
17	    followerPriority?: number;
18	    actions?: any;
19	    morphs?: any;
20	}
21	
22	export interface ArchaeologyReport {
23	    archaeologist_version: 3;
24	    timestamp: string;
25	    sources: {
26	        objects: string;
27	        npcs: string;
28	        unified_extract: string;
29	    };
30	    counts: {
31	        total_objects: number;
32	        total_npcs: number;
33	        unified_mapsquares: number;
34	        grounded_npcs: number;
35	    };
36	    hits: ArchaeologyHit[];
37	    grounded_entities: any[];
38	}
39	
40	export class ArchaeologyEngine {
41	    private readonly sovereignBase: string;
42	    private readonly unifiedDir: string;
43	    private readonly outputDir: string;
44	
45	    constructor() {
46	        this.sovereignBase = 'D:/sovereign';
47	        this.unifiedDir = resolve(this.sovereignBase, 'atlas/spatial/unified_extract');
48	        this.outputDir = resolve(this.sovereignBase, 'atlas/spatial/pathing_theory');
49	        
50	        if (!existsSync(this.outputDir)) {
51	            mkdirSync(this.outputDir, { recursive: true });
52	        }
53	    }
54	
55	    public async runAudit(keywords: string[]): Promise<ArchaeologyReport> {
56	        console.log(`[Archaeology] Starting audit with ${keywords.length} keywords...`);
57	
58	        const objectsPath = resolve(this.sovereignBase, 'cache_pedagogy/json_dumps/objects.json');
59	        const npcsPath = resolve(this.sovereignBase, 'cache_pedagogy/json_dumps/npcs.json');
60	
61	        const objects = this.loadJson(objectsPath);
62	        const npcs = this.loadJson(npcsPath);
63	
64	        const hits = this.searchEntities([...objects, ...npcs], keywords);
65	        const groundedData = await this.scanUnifiedDirectory();
66	
67	        const report: ArchaeologyReport = {
68	            archaeologist_version: 3,
69	            timestamp: new Date().toISOString(),
70	            sources: {
71	                objects: objectsPath,
72	                npcs: npcsPath,
73	                unified_extract: this.unifiedDir
74	            },
75	            counts: {
76	                total_objects: objects.length,
77	                total_npcs: npcs.length,
78	                unified_mapsquares: groundedData.mapsquares,
79	                grounded_npcs: groundedData.entities.length
80	            },
81	            hits,
82	            grounded_entities: groundedData.entities
83	        };
84	
85	        const reportPath = resolve(this.outputDir, 'unified_audit_report.json');
86	        writeFileSync(reportPath, JSON.stringify(report, null, 2));
87	        
88	        return report;
89	    }
90	
91	    private loadJson(path: string): any[] {
92	        if (!existsSync(path)) return [];
93	        try {
94	            const raw = readFileSync(path, 'utf-8');
95	            const parsed = JSON.parse(raw);
96	            if (Array.isArray(parsed)) return parsed;
97	            if (parsed.files && Array.isArray(parsed.files)) return parsed.files;
98	            return [parsed];
99	        } catch (e) {
100	            return [];
101	        }
102	    }
103	
104	    private searchEntities(entities: any[], keywords: string[]): ArchaeologyHit[] {
105	        const hits: ArchaeologyHit[] = [];
106	        const lowerKeywords = keywords.map(k => k.toLowerCase());
107	
108	        for (const entity of entities) {
109	            if (!entity) continue;
110	            const name = (entity.name || '').toLowerCase();
111	            const rawStr = JSON.stringify(entity).toLowerCase();
112	
113	            for (const kw of lowerKeywords) {
114	                if (name.includes(kw) || rawStr.includes(kw)) {
115	                    hits.push({
116	                        keyword: kw,
117	                        id: entity.$fileid ?? entity.id ?? 'unknown',
118	                        name: entity.name ?? '',
119	                        models: entity.models,
120	                        op: entity.op,
121	                        params: entity.params,
122	                        extra: entity.extra,
123	                        boundSize: entity.boundSize,
124	                        walkRange: entity.walkRange,
125	                        respawnDirection: entity.respawnDirection,
126	                        movementType: entity.movementType,
127	                        followerPriority: entity.followerPriority,
128	                        actions: entity.actions,
129	                        morphs: entity.morphs_1 || entity.morphs_2,
130	                    });
131	                    break;
132	                }
133	            }
134	        }
135	        return hits;
136	    }
137	
138	    private async scanUnifiedDirectory(): Promise<{ mapsquares: number, entities: any[] }> {
139	        if (!existsSync(this.unifiedDir)) return { mapsquares: 0, entities: [] };
140	
141	        const files = readdirSync(this.unifiedDir).filter(f => f.endsWith('.json'));
142	        const allEntities: any[] = [];
143	
144	        for (const file of files) {
145	            try {
146	                const content = JSON.parse(readFileSync(join(this.unifiedDir, file), 'utf-8'));
147	                if (content.pedagogy?.npcs) {
148	                    allEntities.push(...content.pedagogy.npcs.map((n: any) => ({
149	                        ...n,
150	                        source_file: file,
151	                        region: content.region || file.replace('ms_', '').replace('.json', '')
152	                    })));
153	                }
154	            } catch (e) {
155	                console.error(`[Archaeology] Failed to parse ${file}:`, e);
156	            }
157	        }
158	
159	        return {
160	            mapsquares: files.length,
161	            entities: allEntities
162	        };
163	    }
164	}
