13	/**
14	 * FragmentOrchestrator - Phase 34 Mastery: Logistical Sovereign Purity.
15	 * 
16	 * Responsibilities:
17	 * 1. Monitor avatar position relative to mapsquare (fragment) boundaries.
18	 * 2. Proactively load neighboring logic fragments from the D: drive "Atlas".
19	 * 3. Bridges the "C3 Gap" by ensuring mechanical rules are injected per-fragment.
20	 */
21	export class FragmentOrchestrator {
22	    private spatial: SpatialSovereigntyLimb;
23	    private registry: SpaceRegistry;
24	    private loadedRegions: Set<string> = new Set();
25	    
26	    // Hysteresis: Only check for new regions when moving significant distance
27	    private lastCheckCoord: Coord | null = null;
28	    private readonly checkThreshold = 8; // tiles
29	
30	    constructor(spatial: SpatialSovereigntyLimb) {
31	        this.spatial = spatial;
32	        this.registry = SpaceRegistry.getInstance();
33	    }
34	
35	    /**
36	     * update - Heartbeat for regional loading.
37	     */
38	    public async update(avatar: Coord): Promise<void> {
39	        if (this.shouldSkipCheck(avatar)) return;
40	
41	        const centerX = avatar.x >> 6;
42	        const centerY = avatar.y >> 6;
43	
44	        const loadPromises: Promise<any>[] = [];
45	
46	        // Scan 5x5 grid (radius 2) for missing logic fragments
47	        for (let mx = centerX - 2; mx <= centerX + 2; mx++) {
48	            for (let my = centerY - 2; my <= centerY + 2; my++) {
49	                const anchor = `m_${mx}_${my}`;
50	                
51	                if (!this.loadedRegions.has(anchor)) {
52	                    loadPromises.push(this.attemptRegionalLoad(anchor, mx, my));
53	                }
54	            }
55	        }
56	
57	        if (loadPromises.length > 0) {
58	            logger.info({ count: loadPromises.length }, 'Triggering proactive regional logic loads.');
59	            await Promise.all(loadPromises);
60	        }
61	
62	        // 4. Update Neurological Vibe based on current anchor
63	        const currentAnchor = `m_${centerX}_${centerY}`;
64	        const registry = RegistryB.getInstance();
65	        const logic = registry.getFragmentLogic(currentAnchor);
66	        if (logic) {
67	            VibeMapper.getInstance().updateVibe(logic);
68	        }
69	
70	        this.lastCheckCoord = { ...avatar };
71	    }
72	
73	    /**
74	     * attemptRegionalLoad - Locates and ingests a logic fragment from the C3 Bridge.
75	     */
76	    private async attemptRegionalLoad(anchor: string, mx: number, my: number): Promise<void> {
77	        // Priority 1: Sovereign Path Authority resolution (D:\sovereign\atlas\spatial\)
78	        const logicPath = resolveLogicFragment(anchor);
79	        
80	        const originLabel = logicPath?.includes('D:\\sovereign') ? '[D-SOVEREIGN]' : '[C-LOCAL]';
81	        if (logicPath) {
82	            logger.info(`${originLabel} Fragment resolved: ${logicPath}`);
83	        } else {
84	            logger.warn({ anchor }, 'No logic fragment found in Sovereign Atlas (D:). Using blank stub.');
85	        }
86	
87	        let success = { ok: false };
88	        if (logicPath) {
89	            success = await this.spatial.loadLogic(anchor);
90	        } else {
91	            // Coordinate fallback: Even if no JSON exists, RegistryB will seed a baseline stub
92	            // if it stays within the mapped coordinate range.
93	            success = await this.spatial.loadLogic(anchor);
94	        }
95	
96	        if (success.ok) {
97	            logger.info({ anchor }, 'Proactive Space Logic applied.');
98	        } else {
99	            // RegistryB logic will handle the C3 Gap even if loadLogic "fails" to find a file.
100	            logger.debug({ anchor }, 'Registering baseline logic for unmapped region.');
101	        }
102	
103	        this.loadedRegions.add(anchor);
104	    }
