106	
107	    private shouldSkipCheck(avatar: Coord): boolean {
108	        if (!this.lastCheckCoord) return false;
109	        const dist = Math.abs(avatar.x - this.lastCheckCoord.x) + Math.abs(avatar.y - this.lastCheckCoord.y);
110	        return dist < this.checkThreshold;
111	    }
112	
113	    public getLoadedCount(): number {
114	        return this.loadedRegions.size;
115	    }
116	}
