1	import { createLogger } from '../../utils/logger.js';
2	import { Mesh, Vector3, StandardMaterial, DynamicTexture, Scene, Color3 } from '@babylonjs/core';
3	import { AvatarRenderLimb } from './AvatarRenderLimb.js';
4	
5	const logger = createLogger('GhostSplatLimb');
6	
7	export interface SplatEvent {
8	    type: 'damage' | 'xp' | 'block' | 'heal' | 'poison' | 'crit';
9	    value?: number;
10	    skillId?: number;      // for XP drops
11	    position?: Vector3;    // override spawn position
12	    color?: string;        // hex override
13	    duration?: number;     // ms before fade
14	}
15	
16	export class GhostSplatLimb {
17	    private scene: Scene;
18	    private splats: Map<string, Mesh> = new Map();
19	    private splatId = 0;
20	    
21	    constructor(private renderer: any) {
22	        // Assume renderer has scene exposed or we pass scene directly
23	        this.scene = renderer.scene || renderer;
24	    }
25	    
26	    emit(event: SplatEvent): void {
27	        const id = `splat_${++this.splatId}`;
28	        const spawnPos = event.position || this.getAvatarHeadPosition();
29	        
30	        switch (event.type) {
31	            case 'damage':
32	                this.createDamageSplat(id, event.value || 0, spawnPos, event.color || '#ff0000');
33	                break;
34	            case 'xp':
35	                this.createXpSplat(id, event.value || 0, event.skillId || 0, spawnPos);
36	                break;
37	            case 'block':
38	                this.createBlockSplat(id, spawnPos);
39	                break;
40	            case 'heal':
41	                this.createHealSplat(id, event.value || 0, spawnPos);
42	                break;
43	            case 'poison':
44	                this.createPoisonSplat(id, event.value || 0, spawnPos);
45	                break;
46	            case 'crit':
47	                this.createCritSplat(id, event.value || 0, spawnPos);
48	                break;
49	        }
50	        
51	        logger.debug({ id, type: event.type, value: event.value }, 'Splat emitted');
52	    }
53	    
54	    private createTextPlane(id: string, text: string, color: string, pos: Vector3, font: string = 'bold 64px Verdana', scale: number = 10): Mesh {
55	        const plane = Mesh.CreatePlane(id, scale, this.scene);
56	        // Start slightly offset based on random jitter to prevent overlap
57	        const jitterX = (Math.random() - 0.5) * 10;
58	        const jitterY = (Math.random() - 0.5) * 10;
59	        plane.position = new Vector3(pos.x + jitterX, pos.y + jitterY, pos.z);
60	        plane.billboardMode = Mesh.BILLBOARDMODE_ALL;
61	        
62	        const texture = new DynamicTexture(`tex_${id}`, { width: 256, height: 128 }, this.scene, false);
63	        const ctx = texture.getContext() as any;
64	        ctx.font = font;
65	        ctx.fillStyle = color;
66	        ctx.textAlign = 'center';
67	        ctx.textBaseline = 'middle';
68	        
69	        // Outline text
70	        ctx.lineWidth = 4;
71	        ctx.strokeStyle = '#000000';
72	        ctx.strokeText(text, 128, 64);
73	        ctx.fillText(text, 128, 64);
74	        texture.update();
75	        
76	        const mat = new StandardMaterial(`mat_${id}`, this.scene);
77	        mat.diffuseTexture = texture;
78	        mat.emissiveColor = Color3.FromHexString(color);
79	        mat.alpha = 1.0;
80	        // make sure it renders on top of everything
81	        mat.disableLighting = true;
82	        mat.useAlphaFromDiffuseTexture = true;
83	        
84	        // Actually, for DynamicTexture background is black, we want transparent
85	        texture.hasAlpha = true;
86	        plane.material = mat;
87	        
88	        return plane;
89	    }
90	
91	    private animateSplat(id: string, plane: Mesh, mat: StandardMaterial, dy: number, fadeRate: number) {
92	        const animate = () => {
93	            if (!this.splats.has(id)) return;
94	            plane.position.y += dy;
95	            mat.alpha -= fadeRate;
96	            if (mat.alpha <= 0) {
97	                plane.dispose();
98	                this.splats.delete(id);
99	            } else {
100	                requestAnimationFrame(animate);
101	            }
102	        };
103	        requestAnimationFrame(animate);
104	        this.splats.set(id, plane);
105	    }
106	    
107	    private createDamageSplat(id: string, value: number, pos: Vector3, color: string): void {
108	        const plane = this.createTextPlane(id, value.toString(), color, pos);
109	        this.animateSplat(id, plane, plane.material as StandardMaterial, 0.5, 0.015);
110	    }
111	    
112	    private createXpSplat(id: string, value: number, skillId: number, pos: Vector3): void {
113	        const skillColors: Record<number, string> = {
114	            0: '#ff0000', // Attack
115	            1: '#00ff00', // Defence
116	            2: '#0000ff', // Strength
117	            // ...
118	        };
119	        const color = skillColors[skillId] || '#ffffff';
120	        const plane = this.createTextPlane(id, `+${value} XP`, color, pos, 'bold 48px Verdana');
121	        
122	        // arc trajectory
123	        let t = 0;
124	        const mat = plane.material as StandardMaterial;
125	        const startX = plane.position.x;
126	        const startY = plane.position.y;
127	        
128	        const animate = () => {
129	            if (!this.splats.has(id)) return;
130	            t += 0.05;
131	            plane.position.x = startX + Math.sin(t) * 10;
132	            plane.position.y = startY + t * 5;
133	            mat.alpha -= 0.01;
134	            if (mat.alpha <= 0) {
135	                plane.dispose();
136	                this.splats.delete(id);
137	            } else {
138	                requestAnimationFrame(animate);
139	            }
140	        };
141	        requestAnimationFrame(animate);
142	        this.splats.set(id, plane);
143	    }
144	    
145	    private createBlockSplat(id: string, pos: Vector3): void {
146	        const plane = this.createTextPlane(id, 'BLOCK', '#aaaaaa', pos);
147	        this.animateSplat(id, plane, plane.material as StandardMaterial, 0.2, 0.02);
148	    }
149	    
150	    private createHealSplat(id: string, value: number, pos: Vector3): void {
151	        const plane = this.createTextPlane(id, `+${value}`, '#00ff00', pos);
152	        this.animateSplat(id, plane, plane.material as StandardMaterial, 0.8, 0.01);
153	    }
154	    
155	    private createPoisonSplat(id: string, value: number, pos: Vector3): void {
156	        const plane = this.createTextPlane(id, value.toString(), '#00cc00', pos);
157	        // Drip effect
158	        this.animateSplat(id, plane, plane.material as StandardMaterial, -0.3, 0.01);
159	    }
160	    
161	    private createCritSplat(id: string, value: number, pos: Vector3): void {
162	        const plane = this.createTextPlane(id, value.toString(), '#ffaa00', pos, 'bold 84px Verdana', 15);
163	        this.animateSplat(id, plane, plane.material as StandardMaterial, 0.6, 0.01);
164	    }
165	    
166	    private getAvatarHeadPosition(): Vector3 {
167	        // Point cloud coordinates scale; we'll spawn at Y = 100 for our mesh bounds
168	        return new Vector3(0, 100, 0);
169	    }
170	    
171	    clearAll(): void {
172	        for (const [id, mesh] of this.splats) {
173	            mesh.dispose();
174	        }
175	        this.splats.clear();
176	    }
177	}
