83	            const isVisualEvent = event.type === 'entity_spawn' || 
84	                                 event.type === 'direct_perception' || 
85	                                 event.type === 'telemetry';
86	
87	            const packet = {
88	                type: event.type, // Use the actual event type for the globe dispatcher
89	                id: event.id,
90	                eventType: event.type,
91	                source: event.source,
92	                traceId: event.traceId,
93	                timestamp: event.timestamp,
94	                payload: isVisualEvent ? event.payload : undefined,
95	                latency: event.payload?.latencyMs,
96	            };
97	
98	            this.ws.send(JSON.stringify(packet), (err: any) => { 
99	                if (err) logger.debug({ err }, 'Failed to stream telemetry packet'); 
100	            });
