104	    /**
105	     * Subscribe to state updates for a specific neurological node ID.
106	     */
107	    public onStateUpdate(nodeId: string, callback: (data: any) => void): void {
108	        if (!this.subscribers.has(nodeId)) {
109	            this.subscribers.set(nodeId, []);
