114	    /**
115	     * Connects to the Multiplayer Globe substrate.
116	     * Stores the connection promise so healthCheck() can await it.
117	     */
118	    public async connect(): Promise<Result<boolean>> {
119	        if (!this.enabled) {
120	            return ok(false);
121	        }
122	
123	        this.connectPromise = new Promise((resolve) => {
124	            try {
125	                this.ws = new WebSocket(this.endpoint);
126	
127	                let pingInterval: NodeJS.Timeout;
128	
129	                this.ws.on('open', () => {
130	                    logger.info({ endpoint: this.endpoint }, 'Connected to Multiplayer Globe Substrate');
131	                    
132	                    // Phase 22: Keep-alive interval to prevent Cloudflare 100s idle timeout
133	                    pingInterval = setInterval(() => {
134	                        if (this.ws?.readyState === WebSocket.OPEN) {
135	                            this.ws.ping();
136	                            // Also send an application-level ping just in case
137	                            this.ws.send(JSON.stringify({ type: 'ping', timestamp: Date.now() }));
138	                        }
139	                    }, 30000);
140	
141	                    resolve(ok(true));
142	                });
143	
144	                this.ws.on('close', () => {
145	                    if (pingInterval) clearInterval(pingInterval);
146	                    logger.warn('Globe connection closed. Attempting reconnect in 5 seconds...');
147	                    setTimeout(() => {
148	                        if (this.enabled) this.connect();
149	                    }, 5000);
150	                });
151	
152	                this.ws.on('message', (data: string) => {
153	                    try {
154	                        const msg = JSON.parse(data);
155	                        if (msg.type === 'state-sync') {
156	                            this.state = msg.state;
157	                            logger.debug('State synchronized from Globe');
158	
159	                            // Notify subscribers of the new state
160	                            for (const [nodeId, nodeData] of Object.entries(this.state.nodes)) {
161	                                const callbacks = this.subscribers.get(nodeId);
162	                                if (callbacks) {
163	                                    callbacks.forEach(cb => {
164	                                        try { cb(nodeData); } catch (e) { logger.error({ err: e }, 'Globe subscriber error'); }
165	                                    });
166	                                }
167	                            }
168	                        } else if (msg.type === 'human_intervention' || msg.type === 'volitional_request') {
169	                            logger.info({ payload: msg }, '🧠 Received volition/intervention from Globe, routing to SwitchboardLimb admin queue');
170	                            // Dynamically import to avoid circular dependencies if needed
171	                            import('../../monitor/SwitchboardLimb.js').then(({ SwitchboardLimb }) => {
172	                                SwitchboardLimb.getInstance().pushAdminCommand({
173	                                    type: msg.action || msg.intent || 'human_intervention',
174	                                    metadata: { ...msg, timestamp: Date.now() }
175	                                });
176	                            });
177	                        }
178	                    } catch (err) {
179	                        logger.warn({ err }, 'Failed to parse Globe message');
180	                    }
181	                });
182	
183	                this.ws.on('error', (err: any) => {
184	                    logger.error({ err }, 'Globe connection error');
185	                    resolve({ ok: false, error: err });
186	                });
187	
188	            } catch (err) {
189	                resolve({ ok: false, error: err as Error });
190	            }
191	        });
192	        return this.connectPromise;
193	    }
