1	import { createLogger } from '../../utils/logger.js';
2	import { Item, SovereignAvatar, EquipmentSlot, Result, ok, err, SkillId } from '../../core/models.js';
3	import { CacheForensicsLimb } from './CacheForensicsLimb.js';
4	
5	const logger = createLogger('ItemLifecycleLimb');
6	
7	export class ItemLifecycleLimb {
8	    private static instance: ItemLifecycleLimb;
9	
10	    private constructor() {}
11	
12	    public static getInstance(): ItemLifecycleLimb {
13	        if (!ItemLifecycleLimb.instance) {
14	            ItemLifecycleLimb.instance = new ItemLifecycleLimb();
15	        }
16	        return ItemLifecycleLimb.instance;
17	    }
18	
19	    /**
20	     * wear - Attaches an item from inventory to its designated equipment slot.
21	     */
22	    public wear(avatar: SovereignAvatar, slot: number): Result<boolean> {
23	        const item = avatar.inventory[slot];
24	        if (!item) return err(new Error('No item in slot.'));
25	
26	        // Retrieve authentic, cache-backed equipment slot from the forensic registry
27	        const rawSlot = CacheForensicsLimb.getInstance().findItemSlot(item.id);
28	        let targetSlot: EquipmentSlot = item.metadata?.equipSlot || EquipmentSlot.WEAPON;
29	        if (rawSlot) {
30	            const slotMap: Record<string, EquipmentSlot> = {
31	                helm: EquipmentSlot.HEAD,
32	                face: EquipmentSlot.HEAD,
33	                beard: EquipmentSlot.HEAD,
34	                cape: EquipmentSlot.CAPE,
35	                necklace: EquipmentSlot.NECK,
36	                weapon: EquipmentSlot.WEAPON,
37	                body: EquipmentSlot.BODY,
38	                arms: EquipmentSlot.BODY,
39	                offhand: EquipmentSlot.SHIELD,
40	                legs: EquipmentSlot.LEGS,
41	                gloves: EquipmentSlot.HANDS,
42	                boots: EquipmentSlot.FEET,
43	                ring: EquipmentSlot.RING,
44	                ammo: EquipmentSlot.AMMO,
45	                aura: EquipmentSlot.AURA
46	            };
47	            if (slotMap[rawSlot]) {
48	                targetSlot = slotMap[rawSlot];
49	            }
50	        }
51	
52	        // Unequip current item first if exists
53	        const current = avatar.equipment[targetSlot];
54	        if (current) {
55	            this.unequip(avatar, targetSlot);
56	        }
57	
58	        // Equipment Swap
59	        avatar.equipment[targetSlot] = item;
60	        avatar.inventory[slot] = null;
61	
62	        logger.info(`EQUIP: ${item.id} worn in ${targetSlot}.`);
63	        return ok(true);
64	    }
65	
66	    /**
67	     * unequip - Returns an item from equipment slot to inventory.
68	     */
69	    public unequip(avatar: SovereignAvatar, slot: string): Result<boolean> {
70	        const item = avatar.equipment[slot];
71	        if (!item) return err(new Error('Slot is empty.'));
72	
73	        const invSlot = avatar.firstEmptySlot?.() ?? -1;
74	        if (invSlot === -1) return err(new Error('Inventory full.'));
75	
76	        avatar.inventory[invSlot] = item;
77	        avatar.equipment[slot] = null;
78	
79	        logger.info(`UNEQUIP: ${item.id} returned to inventory.`);
80	        return ok(true);
81	    }
82	
83	    /**
84	     * canTeleport - Validates requirements for coordinate jumps.
85	     */
86	    public canTeleport(avatar: SovereignAvatar, type: 'VARROCK' | 'LUMBRIDGE' | 'FALADOR'): Result<boolean> {
87	        const magicSkill = avatar.skills[SkillId.MAGIC];
88	        const inv = avatar.inventory;
89	
90	        // Basic authentic requirements
91	        const reqs: Record<string, { level: number; runes: { id: number; count: number }[] }> = {
92	            'VARROCK': { 
93	                level: 25, 
94	                runes: [
95	                    { id: 563, count: 1 }, // Law Rune
96	                    { id: 554, count: 1 }, // Fire Rune
97	                    { id: 556, count: 3 }  // Air Rune
98	                ]
99	            },
100	            'LUMBRIDGE': {
101	                level: 31,
102	                runes: [
103	                    { id: 563, count: 1 }, // Law Rune
104	                    { id: 557, count: 1 }, // Earth Rune
105	                    { id: 556, count: 3 }  // Air Rune
106	                ]
107	            }
108	        };
109	
110	        const config = reqs[type];
111	        if (!config) return err(new Error('Unknown teleport type.'));
112	
113	        // Level check
114	        if ((magicSkill?.level || 1) < config.level) {
115	            return err(new Error(`Requires level ${config.level} Magic.`));
116	        }
117	
118	        // Rune check
119	        for (const req of config.runes) {
120	            const has = inv.filter(i => i?.id === req.id).reduce((sum, i) => sum + (i?.amount || 0), 0);
121	            if (has < req.count) {
122	                return err(new Error(`Missing runes for ${type} teleport.`));
123	            }
124	        }
125	
126	        return ok(true);
127	    }
128	}
