1	import { InteractionPair, isTransversal, getInteractionResult } from '../../forensics/ObjectBinaryStore.js';
2	import { SovereignInteractionLimb } from './SovereignInteractionLimb.js';
3	
4	export interface KinematicProbe {
5	    id: number;
6	    type: 'MOUSE' | 'PLATYPUS';
7	    coords: { x: number, z: number, plane: number };
8	    velocity: { dx: number, dz: number };
9	    isWoundUp: boolean;
10	}
11	
12	/**
13	 * Kinematic Probe Limb
14	 * Locomotion engine for autonomous spatial probes.
15	 */
16	export class KinematicProbeLimb {
17	    private probes: Map<number, KinematicProbe> = new Map();
18	    private collisionMap: any = null;
19	    private interactionLimb: SovereignInteractionLimb | null = null;
20	
21	    constructor() {
22	        console.log("KinematicProbeLimb: Locomotion initialized.");
23	    }
24	
25	    public setInteractionLimb(limb: SovereignInteractionLimb) {
26	        this.interactionLimb = limb;
27	    }
28	
29	    /**
30	     * Injects the local mapsquare collision substrate.
31	     */
32	    public setCollisionMap(map: any) {
33	        this.collisionMap = map;
34	    }
35	
36	    /**
37	     * Updates the position of all active probes.
38	     */
39	    public update(deltaTime: number) {
40	        for (const [id, probe] of this.probes) {
41	            this.processMovement(probe, deltaTime);
42	        }
43	    }
44	
45	    private processMovement(probe: KinematicProbe, deltaTime: number) {
46	        if (probe.type === 'MOUSE' && !probe.isWoundUp) return;
47	
48	        // 1. Calculate prospective next tile
49	        const nextX = Math.round(probe.coords.x + probe.velocity.dx);
50	        const nextZ = Math.round(probe.coords.z + probe.velocity.dz);
51	
52	        // 2. Perform Collision Check (Abstracted)
53	        // In the real system, this queries the SpatialSovereigntyLimb
54	        const collision = this.checkCollision(
55	            probe.coords.x, probe.coords.z, 
56	            nextX, nextZ, 
57	            probe.coords.plane
58	        );
59	
60	        if (collision) {
61	            this.handleCollision(probe, collision.objectId);
62	        } else {
63	            probe.coords.x = nextX;
64	            probe.coords.z = nextZ;
65	        }
66	    }
67	
68	    private handleCollision(probe: KinematicProbe, objectId: number) {
69	        console.log(`Probe ${probe.id}: Bumper hit on Object ${objectId}`);
70	        
71	        if (this.interactionLimb) {
72	            this.interactionLimb.notifyBump(probe.id, objectId);
73	        }
74	
75	        // Check for Transversal (Ladders/Caves)
76	        if (isTransversal(objectId)) {
77	            this.performTransversal(probe, objectId);
78	        }
79	    }
80	
81	    private performTransversal(probe: KinematicProbe, objectId: number) {
82	        const interaction = getInteractionResult(objectId);
83	        if (!interaction) return;
84	
85	        console.log(`Probe ${probe.id}: Transversal triggered (${interaction.type})`);
86	
87	        if (interaction.type === 'LADDER') {
88	            if (interaction.action.includes('up')) probe.coords.plane++;
89	            if (interaction.action.includes('down')) probe.coords.plane--;
90	            console.log(`Probe ${probe.id}: Plane shifted to ${probe.coords.plane}`);
91	        } else if (interaction.type === 'CAVE' || interaction.type === 'PORTAL') {
92	            // Teleport logic (Forensic link)
93	            console.log(`Probe ${probe.id}: Entering Portal/Cave logic...`);
94	        }
95	    }
96	
97	    /**
98	     * Authentic collision check against the 10/10 spatial heatmap.
99	     * Supports legacy bitmasks, 4-way edges (JSON), and 9-way masks (Hi-Fi).
100	     */
101	    private checkCollision(fromX: number, fromZ: number, toX: number, toZ: number, plane: number): { objectId: number } | null {
102	        if (!this.collisionMap) return null;
103	
104	        // 1. Identify Direction
105	        const dx = toX - fromX;
106	        const dz = toZ - fromZ;
107	        
108	        // 2. Resolve Tile Logic
109	        // The collisionMap can be a sparse array (tiles[]) or a coordinate matrix (collision_matrix{})
110	        let tile: any = null;
111	        if (this.collisionMap.tiles) {
112	            tile = this.collisionMap.tiles.find((t: any) => t.x === toX && t.z === toZ && t.plane === plane);
113	        } else if (this.collisionMap.collision_matrix) {
114	            tile = this.collisionMap.collision_matrix[`${toX}_${toZ}_${plane}`] || this.collisionMap.collision_matrix[`${toX}_${toZ}`];
115	        }
116	
117	        if (!tile) return null;
118	
119	        // 3. Perform Multi-Format Collision Check
120	        let isBlocked = false;
121	
122	        // A. Legacy Bitmask (0x80 = Solid, 0x100 = Overlay)
123	        if (typeof tile.collision === 'number' && (tile.collision & 0x80)) isBlocked = true;
124	
125	        // B. 4-Way Edges (from mapsquare json / synthesis audit)
126	        if (tile.edges) {
127	            if (dz > 0 && tile.edges.southBlocked) isBlocked = true; // Moving North
128	            if (dz < 0 && tile.edges.northBlocked) isBlocked = true; // Moving South
129	            if (dx > 0 && tile.edges.westBlocked) isBlocked = true;  // Moving East
130	            if (dx < 0 && tile.edges.eastBlocked) isBlocked = true;  // Moving West
131	        }
132	
133	        // C. 9-Way Mask (from lumbridge_collision_v1.json)
134	        // Note: dz > 0 is North, dx > 0 is East in Sovereign coords
135	        if (tile.mask) {
136	            if (tile.mask.center) isBlocked = true;
137	            if (dz > 0 && tile.mask.bottom) isBlocked = true;
138	            if (dz < 0 && tile.mask.top) isBlocked = true;
139	            if (dx > 0 && tile.mask.left) isBlocked = true;
140	            if (dx < 0 && tile.mask.right) isBlocked = true;
141	            
142	            // Diagonals
143	            if (dx > 0 && dz > 0 && tile.mask.botleft) isBlocked = true;
144	            if (dx < 0 && dz > 0 && tile.mask.botright) isBlocked = true;
145	            if (dx > 0 && dz < 0 && tile.mask.topleft) isBlocked = true;
146	            if (dx < 0 && dz < 0 && tile.mask.topright) isBlocked = true;
147	        }
148	
149	        // D. Top-level walkable flag
150	        if (tile.walkable === false) isBlocked = true;
151	
152	        if (isBlocked) {
153	            return { objectId: tile.objectId || 99999 };
154	        }
155	
156	        return null;
157	    }
158	
159	    public spawnProbe(id: number, type: 'MOUSE' | 'PLATYPUS', coords: { x: number, z: number, plane: number }) {
160	        this.probes.set(id, {
161	            id,
162	            type,
163	            coords,
164	            velocity: { dx: 1, dz: 0 },
165	            isWoundUp: true
166	        });
167	    }
168	}
