32	    /**
33	     * learnTile - Extracts metadata for a specific coordinate.
34	     * Note: This is an async extraction from the cache.
35	     */
36	    public async learnTile(plane: number, x: number, y: number): Promise<TileMetadata> {
37	        const startTime = Date.now();
38	
39	        // Query the Sensory Limb (Extraction)
40	        const [objects, terrainFlags] = await Promise.all([
