18	/**
19	 * MaterialLimb - Extractor for shader layer materials.
20	 * Extracts Cache Major 26 (Materials) to map PBR properties, textures,
21	 * and visual components into the Sovereign Atlas. 
22	 */
23	export class MaterialLimb {
24	    private readonly cachePath = getrsmvCachePath();
25	    private readonly outDir = getCachePedagogyPath();
26	    private cache: any | null = null;
27	
28	    constructor() {
29	        try {
30	            if (GameCacheLoader) {
31	                this.cache = new GameCacheLoader(this.cachePath);
32	                logger.info({ path: this.cachePath }, 'MaterialLimb connected to substrate.');
33	            } else {
34	                logger.warn('MaterialLimb: GameCacheLoader not available.');
35	            }
36	        } catch (e) {
