41	    /**
42	     * Extracts Materials into a cohesive sensory JSON.
43	     */
44	    public async extractMaterials(): Promise<Result<boolean>> {
45	        if (!this.cache) return err(new Error('Cache connection offline.'));
46	        if (!parse || !parse.materials) return err(new Error('Required RS3 parser (materials) not available.'));
47	
48	        try {
49	            logger.info('Commencing Material Shader Extraction (Major 26)...');
50	            const MAJOR_MATERIALS = 26;
51	
52	            // Materials typically sit in archive 0, or fileids correspond to material IDs across archives
53	            // In RS3, Major 26 often has archive 0 with many files, or multiple archives with file 0
54	            // Let's attempt to load all available archives in Major 26
55	            const index = await this.cache.getCacheIndex(MAJOR_MATERIALS);
56	            const materials: Record<number, any> = {};
57	            let count = 0;
58	
59	            for (const archiveInfo of index) {
60	                if (!archiveInfo) continue;
61	                const archive = await this.cache.getArchiveById(MAJOR_MATERIALS, archiveInfo.minor);
62	                for (const f of archive) {
63	                    try {
64	                        const matId = archiveInfo.minor | f.fileid; // depending on RS3 packaging, but storing flat ID
65	                        const decoded = parse.materials.read(f.buffer, this.cache);
66	                        decoded.id = matId;
67	                        materials[matId] = decoded;
68	                        count++;
69	                    } catch (e) {
70	                        logger.warn({ archive: archiveInfo.minor, file: f.fileid, error: (e as Error).message }, 'Failed to decode material substrate entry. Skipping corrupt file.');
71	                    }
72	                }
73	            }
74	
75	            const payload = {
76	                metadata: {
77	                    extractedAt: new Date().toISOString(),
78	                    materialCount: count
79	                },
80	                materials
81	            };
82	
83	            const outPath = path.join(this.outDir, 'materials.json');
84	            fs.writeFileSync(outPath, JSON.stringify(payload, null, 2));
85	
