2	// Phase 4B/5: Audio Synthesis with Keyframe Sync
3	
4	import { spawn } from 'child_process';
5	import { readFileSync, existsSync } from 'fs';
6	import { tmpdir } from 'os';
7	import { join } from 'path';
8	import { type Result, ok, err } from '../../core/models.js';
9	
10	export interface AudioCue {
11	  timeMs: number;
12	  intensity: number;
13	  type: 'ROAR_BUILD' | 'ROAR_PEAK' | 'ROAR_DECAY';
14	}
15	
16	export interface SoundtrackParams {
17	  prompt: string;
18	  duration: number;
19	  keyframes: AudioCue[];
20	  channels: number;
21	  sampleRate: number;
22	  bitDepth: number;
23	}
24	
25	export interface SoundtrackResult {
26	  buffer: Buffer;
27	  path: string;
28	}
29	
30	export class SoundtrackLimb {
31	  async generate(params: SoundtrackParams): Promise<Result<SoundtrackResult>> {
32	    console.log(`ðŸŽµ Synthesizing ${params.channels}ch audio: ${params.duration}s`);
33	
34	    try {
35	      // Generate volume modulation curve from keyframes
36	      const volumeCurve = this.generateVolumeCurve(params.keyframes, params.duration);
37	      
38	      // Use ffmpeg with aevalsrc for procedural audio
39	      const filterComplex = this.buildFilterComplex(params, volumeCurve);
40	      
41	      const result = await this.renderWithFFmpeg(params, filterComplex);
42	      return ok(result);
43	    } catch (e: any) {
44	      return err(e);
45	    }
46	  }
47	
48	  private generateVolumeCurve(cues: AudioCue[], duration: number): number[] {
49	    const samples = Math.ceil(duration * 100); // 10ms resolution
50	    const curve = new Array(samples).fill(0);
51	    
52	    for (const cue of cues) {
53	      const index = Math.floor(cue.timeMs / 10);
54	      if (index < samples) {
55	        curve[index] = cue.intensity;
56	      }
57	    }
58	    
59	    // Smooth interpolation
60	    return this.smoothCurve(curve);
61	  }
62	
63	  private smoothCurve(curve: number[]): number[] {
64	    const smoothed = [...curve];
65	    for (let i = 1; i < curve.length - 1; i++) {
66	      smoothed[i] = (curve[i-1] + curve[i] + curve[i+1]) / 3;
67	    }
68	    return smoothed;
69	  }
70	
71	  private buildFilterComplex(params: SoundtrackParams, volumeCurve: number[]): string {
72	    // piece-wise constant volume modulation (flat additive sum to avoid nesting limits)
73	    const volumeExprParts: string[] = [];
74	    
75	    for (let i = 0; i < volumeCurve.length; i++) {
76	        const v = volumeCurve[i];
77	        if (v > 0.001) { 
78	            const t1 = (i / 100).toFixed(3);
79	            const t2 = ((i + 1) / 100).toFixed(3);
80	            // Boost intensity by 5x to ensure audibility
81	            volumeExprParts.push(`${(v * 5.0).toFixed(3)}*between(t,${t1},${t2})`);
82	        }
83	    }
84	    
85	    // Base floor of 0.05 to prevent absolute silence
86	    const volumeExpr = volumeExprParts.length > 0 ? `0.05 + (${volumeExprParts.join('+')})` : '0.2';
87	    
88	    // 5.1 channel mapping: Spread mono over 5.1
89	    const channels = params.channels === 6 
90	      ? 'pan=5.1|FL=c0|FR=c0|FC=c0|LFE=c0*0.5|BL=c0*0.3|BR=c0*0.3'
91	      : 'pan=stereo';
92	    
93	    return `volume='${volumeExpr}',${channels}`;
94	  }
95	
96	  private async renderWithFFmpeg(params: SoundtrackParams, filter: string): Promise<SoundtrackResult> {
97	    const outputPath = join(tmpdir(), `kbd_roar_${Date.now()}.wav`);
98	    
99	    return new Promise((resolve, reject) => {
100	      const ffmpeg = spawn('ffmpeg', [
101	        '-y',
102	        '-f', 'lavfi', '-i', `anoisesrc=d=${params.duration}:c=white:amp=1.0`, // White noise for full spectrum
103	        '-af', filter,
104	        '-t', params.duration.toString(),
105	        '-ar', params.sampleRate.toString(),
106	        '-ac', params.channels.toString(),
107	        outputPath
108	      ]);
109	
110	      let errorOutput = '';
111	      ffmpeg.stderr.on('data', (data) => {
112	        errorOutput += data.toString();
113	      });
114	
115	      ffmpeg.on('close', (code) => {
116	        if (code === 0) {
117	          resolve({
118	            buffer: readFileSync(outputPath),
119	            path: outputPath
120	          });
121	        } else {
122	          console.error('FFmpeg Error Output:', errorOutput);
123	          reject(new Error(`FFmpeg exited ${code}`));
124	        }
125	      });
126	    });
127	  }
128	
129	  healthCheck(): { online: boolean; details: string } {
130	    return { online: true, details: 'SoundtrackLimb: FFmpeg synthesis ready' };
131	  }
132	}
