1	import { Coord, Result, ok, err } from '../../core/models.js';
2	import { SpatialSovereigntyLimb, CORE_SIZE } from './SpatialSovereigntyLimb.js';
3	import { createLogger } from '../../utils/logger.js';
4	
5	const logger = createLogger('DiscoveryLimb');
6	
7	/**
8	 * DiscoveryLimb - Phase B1: The "MAPPING" substrate.
9	 * 
10	 * Responsibilities:
11	 * 1. Track tile visitation within a session.
12	 * 2. Scan mapsquares for "Frontier" tiles (Walkable but Unvisited).
13	 * 3. Calculate exploration coverage metrics.
14	 */
15	export class DiscoveryLimb {
16	    private visitedTiles: Set<string> = new Set();
17	    private readonly mapsquareSize = CORE_SIZE; // NXT: 64-tile playable core
18	
19	    /**
20	     * markVisited - Record the avatar's presence on a tile.
21	     */
22	    public markVisited(plane: number, x: number, y: number): void {
23	        const key = `${plane}_${x}_${y}`;
24	        if (!this.visitedTiles.has(key)) {
25	            this.visitedTiles.add(key);
26	            logger.info({ plane, x, y }, 'New tile discovered.');
27	        }
28	    }
29	
30	    /**
31	     * isVisited - Check if the avatar has prioritized this tile before.
32	     */
33	    public isVisited(plane: number, x: number, y: number): boolean {
34	        return this.visitedTiles.has(`${plane}_${x}_${y}`);
35	    }
36	
37	    /**
38	     * getUnvisitedWalkableTiles - Scans an NXT mapsquare (64×64 core) for exploration targets.
39	     * This is the "Frontier Detection" logic for Phase B2.
40	     */
41	    public async getUnvisitedWalkableTiles(
42	        plane: number,
43	        mapsquareX: number,
44	        mapsquareY: number,
45	        spatial: SpatialSovereigntyLimb
46	    ): Promise<Coord[]> {
47	        return this.getFrontierExtended(plane, mapsquareX, mapsquareY, 0, spatial);
48	    }
49	
50	    /**
51	     * getGlobalFrontier - Phase C2: Global World Discovery.
52	     * Consolidates unvisited tiles from the 3x3 mapsquare grid (192x192 tiles).
53	     */
54	    public async getGlobalFrontier(
55	        plane: number,
56	        currentX: number,
57	        currentY: number,
58	        spatial: SpatialSovereigntyLimb
59	    ): Promise<Coord[]> {
60	        const mx = currentX >> 6;
61	        const my = currentY >> 6;
62	        return this.getFrontierExtended(plane, mx, my, 1, spatial);
63	    }
64	
65	    /**
66	     * getFrontierExtended - Scans a range of mapsquares.
67	     * radius=0: current mapsquare only (NXT 64×64 core)
68	     * radius=1: 3x3 mapsquare grid (192×192) - User Request: "Triple the view"
69	     */
70	    public async getFrontierExtended(
71	        plane: number,
72	        centerX: number,
73	        centerY: number,
74	        radius: number,
75	        spatial: SpatialSovereigntyLimb
76	    ): Promise<Coord[]> {
77	        const unvisited: Coord[] = [];
78	        
79	        for (let mx = centerX - radius; mx <= centerX + radius; mx++) {
80	            for (let my = centerY - radius; my <= centerY + radius; my++) {
81	                const startX = mx << 6;
82	                const startY = my << 6;
83	
84	                for (let lx = 0; lx < this.mapsquareSize; lx++) {
85	                    for (let ly = 0; ly < this.mapsquareSize; ly++) {
86	                        const wx = startX + lx;
87	                        const wy = startY + ly;
88	
89	                        if (!this.isVisited(plane, wx, wy)) {
90	                            // Check common walkability first, then regional check
91	                            if (spatial.isWalkable(plane, wx, wy)) {
92	                                unvisited.push({ x: wx, y: wy, plane });
93	                            }
94	                        }
95	                    }
96	                }
97	            }
98	        }
99	        return unvisited;
100	    }
101	
102	    /**
103	     * getCoverage - Returns visitation metrics for a specific mapsquare.
104	     */
105	    public getCoverage(plane: number, mapsquareX: number, mapsquareY: number): {
106	        visited: number;
107	        total: number;
108	        percentage: string;
109	    } {
110	        const startX = mapsquareX << 6;
111	        const startY = mapsquareY << 6;
112	        let visitedCount = 0;
113	        const totalTiles = this.mapsquareSize * this.mapsquareSize;
114	
115	        for (let lx = 0; lx < this.mapsquareSize; lx++) {
116	            for (let ly = 0; ly < this.mapsquareSize; ly++) {
117	                if (this.isVisited(plane, startX + lx, startY + ly)) {
118	                    visitedCount++;
119	                }
120	            }
121	        }
122	
123	        return {
124	            visited: visitedCount,
125	            total: totalTiles,
126	            percentage: ((visitedCount / totalTiles) * 100).toFixed(2)
127	        };
128	    }
129	
130	    /**
131	     * reset - Clear session memory (for teleportation or re-exploration).
132	     */
133	    public reset(): void {
134	        this.visitedTiles.clear();
135	        logger.warn('Discovery memory purged.');
136	    }
137	}
